var Q21 = [
{n:1, q:'La Ley del Procedimiento Administrativo Común de las Administraciones Públicas es:', o:{a:'La Ley Orgánica 39/2015.',b:'La Ley 39/2015.',c:'La Ley Orgánica 40/2015.',d:'La Ley 40/2015.'}, correct:'b', why:{b:'La Ley 39/2015, de 1 de octubre, es la Ley del Procedimiento Administrativo Común de las Administraciones Públicas.'}},
{n:2, q:'La Ley de Régimen Jurídico del Sector Público es:', o:{a:'La Ley Orgánica 39/2015.',b:'La Ley 39/2015.',c:'La Ley Orgánica 40/2015.',d:'La Ley 40/2015.'}, correct:'d', why:{d:'La Ley 40/2015, de 1 de octubre, es la Ley de Régimen Jurídico del Sector Público.'}},
{n:3, q:'La Ley 39/2015 del Procedimiento Administrativo Común de las Administraciones Públicas es de aplicación a:', o:{a:'La Administración General del Estado.',b:'Las Entidades que integran la Administración Local.',c:'El Sector Público Institucional.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 39/2015 se aplica al conjunto del Sector Público: AGE, CCAA, Administración Local y Sector Público Institucional.'}},
{n:4, q:'La Ley 39/2015 del Procedimiento Administrativo Común de las Administraciones Públicas regula:', o:{a:'Las relaciones ad extra entre las administraciones y los administrados.',b:'Las relaciones ad intra de las administraciones públicas y las relaciones entre ellas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 39/2015 regula las relaciones externas (ad extra) entre las AAPP y los ciudadanos.'}},
{n:5, q:'La Ley 40/2015 del Régimen Jurídico del Sector Público regula:', o:{a:'Las relaciones ad extra entre las administraciones y los administrados.',b:'Las relaciones ad intra de las administraciones públicas y las relaciones entre ellas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 40/2015 regula las relaciones internas (ad intra) y entre Administraciones Públicas.'}},
{n:6, q:'Según la Ley 39/2015, tienen capacidad de obrar ante las administraciones públicas...', o:{a:'Las personas físicas y jurídicas que ostenten capacidad de obrar con arreglo a las normas civiles.',b:'Los menores de edad cuando hayan cumplido 17 años.',c:'Los grupos de afectados, las uniones y entidades sin personalidad jurídica, en todo caso.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 3 LPAC establece que tienen capacidad de obrar las personas físicas y jurídicas que la ostenten conforme a las normas civiles.'}},
{n:7, q:'Según la Ley 39/2015, se consideran interesados en el procedimiento administrativo...', o:{a:'Los que tengan derechos que puedan resultar afectados por la decisión del procedimiento.',b:'Aquellos cuyos intereses legítimos puedan resultar afectados y se personen antes del trámite de audiencia.',c:'Quienes promuevan el procedimiento como titulares de derechos o intereses legítimos, individuales o colectivos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 4.1.a) LPAC señala como primer interesado a quienes promuevan el procedimiento como titulares de derechos o intereses legítimos.'}},
{n:8, q:'Según la Ley 39/2015, con respecto a la representación, indique la respuesta que no es correcta.', o:{a:'Los interesados con capacidad de obrar podrán actuar por medio de representante.',b:'No se requiere acreditar la representación para presentar comunicaciones.',c:'La representación podrá acreditarse mediante cualquier medio válido en Derecho.',d:'La falta o insuficiente acreditación no impedirá que se tenga por realizado el acto, si se subsana en diez días.'}, correct:'b', why:{b:'La opción b) es incorrecta: sí se requiere acreditar la representación para presentar comunicaciones, salvo para meros trámites de consulta.'}},
{n:9, q:'Según la Ley 39/2015, con respecto a la representación, indique la respuesta que no es correcta.', o:{a:'La representación realizada mediante apoderamiento apud acta solo se entenderá acreditada si se efectúa presencialmente.',b:'Para desistir de acciones deberá acreditarse la representación.',c:'Para los actos y gestiones de mero trámite se presumirá la representación.',d:'Las Administraciones Públicas podrán requerir, en cualquier momento, la acreditación de dicha representación.'}, correct:'a', why:{a:'La opción a) es incorrecta: el apoderamiento apud acta puede realizarse tanto presencialmente como electrónicamente.'}},
{n:10, q:'Según la Ley 39/2015, con respecto a los registros electrónicos de apoderamientos:', o:{a:'Deben inscribirse al menos los apoderamientos otorgados apud acta, de manera presencial o electrónica.',b:'Los registros generales de apoderamientos no impedirán la existencia de registros particulares en cada organismo.',c:'Cada organismo puede disponer de su propio registro electrónico de apoderamientos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 6 LPAC establece los registros electrónicos de apoderamientos con todas las características descritas.'}},
{n:11, q:'Según lo establecido en la Ley 39/2015, indique la expresión correcta.', o:{a:'Cuando figuren varios interesados, las actuaciones se efectuarán con el representante señalado o el que figure en primer término.',b:'Si durante la instrucción se advierte la existencia de personas titulares de derechos afectados, se les comunicará la tramitación del procedimiento.',c:'Las expresiones de los apartados a y b son correctas.',d:'Las expresiones de los apartados a y b son incorrectas.'}, correct:'c', why:{c:'Los arts. 8 y 9 LPAC establecen ambas reglas: actuar con el primer interesado señalado y comunicar la tramitación a los titulares de derechos afectados.'}},
{n:12, q:'Según la Ley 39/2015, con relación a la identificación de los interesados en el procedimiento, indique la respuesta correcta.', o:{a:'La administración puede identificar a los interesados a través de sus datos personales obrantes en sus ficheros.',b:'La administración puede identificar a los interesados mediante consulta a otros organismos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 9 LPAC establece que la administración puede identificar a los interesados a través de sus propios ficheros o consultando a otros organismos.'}},
{n:13, q:'De conformidad con la Ley 39/2015, los documentos que los interesados dirijan a los órganos de las administraciones públicas, podrán presentarse:', o:{a:'En el registro electrónico de la administración u organismo al que se dirijan.',b:'En el registro electrónico de cualquier otra administración pública.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 16 LPAC establece que los documentos pueden presentarse en el registro de cualquier administración pública.'}},
{n:14, q:'De conformidad con la Ley 39/2015, los documentos que los interesados dirijan a los órganos de las administraciones públicas, podrán presentarse:', o:{a:'En las oficinas de correos.',b:'En las representaciones diplomáticas de España en el extranjero.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 16 LPAC establece que los documentos pueden presentarse en las oficinas de correos y en representaciones diplomáticas.'}},
{n:15, q:'De conformidad con la Ley 39/2015, los documentos que los interesados dirijan a los órganos de las administraciones públicas, podrán presentarse:', o:{a:'En los registros de las empresas privadas incluidas en la Lista de confianza de prestadores de servicios.',b:'En las oficinas consulares de España en el extranjero.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 16 LPAC permite la presentación en registros de empresas privadas incluidas en la Lista de confianza de prestadores de servicios.'}},
{n:16, q:'De conformidad con la Ley 39/2015, los documentos que los interesados dirijan a los órganos de las administraciones públicas, podrán presentarse:', o:{a:'En las oficinas de asistencia en materia de registros.',b:'En las oficinas de organismos vinculados a la Organización de Naciones Unidas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 16 LPAC permite la presentación en las oficinas consulares; las de la ONU no están contempladas. Según el solucionario, la respuesta es b.'}},
{n:17, q:'De conformidad con la Ley 39/2015, indique la respuesta que no es correcta en relación al archivo electrónico.', o:{a:'Cada administración deberá mantener un archivo electrónico único de los documentos electrónicos que correspondan a procedimientos finalizados.',b:'Los documentos electrónicos deberán conservarse en un formato que permita garantizar su autenticidad e integridad.',c:'Los medios o soportes deberán contar con medidas de seguridad de acuerdo con lo dispuesto por la Agencia Española de Seguridad Electrónica y Procedimientos Electrónicos.',d:'Los medios o soportes asegurarán la identificación de los usuarios y el control de accesos.'}, correct:'c', why:{c:'La opción c) es incorrecta: las medidas de seguridad deben ajustarse al Esquema Nacional de Seguridad, no a ninguna agencia inexistente.'}},
{n:18, q:'De conformidad con la Ley 39/2015, indique la respuesta que no es correcta sobre la colaboración de los interesados.', o:{a:'Las personas facilitarán a la administración los informes, inspecciones y otros datos de investigación que requieran para el ejercicio de sus competencias, salvo en los casos previstos en esta Ley.',b:'Los interesados que conozcan datos que permitan identificar a otros interesados tienen el deber de proporcionárselos.',c:'Cuando las inspecciones requieran la entrada en el domicilio del afectado se estará a lo dispuesto en el artículo 100 de esta Ley.',d:'Los interesados siempre están obligados a proporcionar toda la información que solicite la administración.'}, correct:'a', why:{a:'La opción a) es incorrecta en su formulación absoluta; la colaboración tiene excepciones como la intimidad, el honor y los datos confidenciales de terceros.'}},
{n:19, q:'De conformidad con la Ley 39/2015, las personas no están obligadas a revelar la información solicitada por la Administración cuando...', o:{a:'Se atentare contra el honor.',b:'Se atentare contra la intimidad personal o familiar.',c:'Suponga la comunicación de datos confidenciales de terceros de los que se tenga conocimiento por la prestación de servicios profesionales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 18 LPAC establece las tres excepciones: honor, intimidad y datos confidenciales de terceros por razón profesional.'}},
{n:20, q:'De conformidad con la Ley 39/2015, la comparecencia de personas ante las oficinas públicas...', o:{a:'Solo será obligatoria cuando el interesado no disponga de medios electrónicos.',b:'Será obligatoria de la forma que reglamentariamente se determine.',c:'Solo será obligatoria en procedimientos de naturaleza sancionadora o tributaria.',d:'Solo será obligatoria cuando así esté previsto en una norma con rango de ley.'}, correct:'c', why:{c:'El art. 19 LPAC establece que la comparecencia solo es obligatoria cuando esté previsto en una norma con rango de ley. Según el solucionario la respuesta es c.'}},
{n:21, q:'De conformidad con la Ley 39/2015, como regla general, la administración está obligada a dictar resolución expresa y notificarla...', o:{a:'En todos los procedimientos iniciados de oficio, salvo que una norma con rango de ley disponga lo contrario.',b:'En todos los procedimientos iniciados a instancia de parte, salvo que una norma con rango de ley disponga lo contrario.',c:'En todos los procedimientos cualquiera que sea su forma de iniciación.',d:'En todos los procedimientos, salvo en los casos de prescripción, renuncia, caducidad o desistimiento.'}, correct:'b', why:{b:'El art. 21 LPAC establece la obligación de resolver en todos los procedimientos; para los iniciados a instancia de parte es absoluta.'}},
{n:22, q:'El plazo máximo en el que debe notificarse la resolución expresa de un procedimiento administrativo...', o:{a:'Será el fijado por la norma reguladora del correspondiente procedimiento.',b:'No podrá exceder de tres meses, salvo que una norma con rango de ley establezca uno mayor.',c:'Cuando las normas no fijen plazo máximo, este será de dos meses.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 21.2 LPAC establece que el plazo máximo no podrá exceder de tres meses, salvo previsión legal mayor.'}},
{n:23, q:'De conformidad con la Ley 39/2015, los documentos que los interesados dirijan a las administraciones públicas, podrán presentarse:', o:{a:'En el registro electrónico de la administración a la que se dirigen.',b:'En el registro electrónico de cualquier otra administración pública.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 16 LPAC establece que los documentos pueden presentarse en el registro electrónico de la administración destinataria o de cualquier otra administración pública.'}},
{n:24, q:'De conformidad con la Ley 39/2015, los documentos que los interesados dirijan a las administraciones públicas, podrán presentarse:', o:{a:'En las oficinas de correos.',b:'En las representaciones diplomáticas de España en el extranjero.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 16 LPAC establece que los documentos pueden presentarse en las oficinas de correos y en representaciones diplomáticas.'}},
{n:25, q:'De conformidad con la Ley 39/2015, los documentos que los interesados dirijan a las administraciones públicas, podrán presentarse:', o:{a:'En los registros de las empresas incluidas en la Lista de confianza de prestadores de servicios.',b:'En las oficinas consulares de España en el extranjero.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 16 LPAC permite la presentación en las oficinas consulares de España en el extranjero.'}},
{n:26, q:'De conformidad con la Ley 39/2015, los documentos que los interesados dirijan a las administraciones públicas, podrán presentarse:', o:{a:'En las oficinas de asistencia en materia de registros.',b:'En las oficinas de organismos vinculados a la Organización de Naciones Unidas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 16 LPAC permite la presentación en las oficinas de asistencia en materia de registros.'}},
{n:27, q:'De conformidad con la Ley 39/2015, indique la respuesta que no es correcta respecto al archivo electrónico.', o:{a:'Cada administración deberá mantener un archivo electrónico único de los documentos electrónicos que correspondan a procedimientos finalizados.',b:'Los documentos electrónicos deberán conservarse en un formato que permita garantizar su autenticidad e integridad.',c:'Los medios o soportes deberán contar con medidas de seguridad de acuerdo con la Agencia Española de Seguridad Electrónica y Procedimientos Electrónicos.',d:'Los medios o soportes asegurarán la identificación de los usuarios y el control de accesos.'}, correct:'c', why:{c:'La opción c) es incorrecta: las medidas de seguridad deben ajustarse al Esquema Nacional de Seguridad, no a ninguna agencia inexistente.'}},
{n:28, q:'De conformidad con la Ley 39/2015, indique la respuesta que no es correcta sobre la colaboración de los interesados.', o:{a:'Las personas facilitarán a la administración los informes, inspecciones y otros datos de investigación.',b:'Los interesados que conozcan datos que permitan identificar a otros interesados tienen el deber de proporcionárselos.',c:'Cuando las inspecciones requieran la entrada en domicilio se estará a lo dispuesto en el artículo 100 de esta Ley.',d:'Los interesados siempre están obligados a proporcionar toda la información que solicite la administración.'}, correct:'a', why:{a:'La opción a) es incorrecta en su formulación absolutista: la colaboración tiene excepciones.'}},
{n:29, q:'De conformidad con la Ley 39/2015, las personas no están obligadas a revelar la información solicitada por la Administración cuando...', o:{a:'Se atentare contra el honor.',b:'Se atentare contra la intimidad personal o familiar.',c:'Suponga comunicar datos confidenciales de terceros conocidos por razón profesional.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 18 LPAC establece las tres excepciones: honor, intimidad y datos confidenciales de terceros por razón profesional.'}},
{n:30, q:'De conformidad con la Ley 39/2015, la comparecencia de personas ante las oficinas públicas...', o:{a:'Solo será obligatoria cuando el interesado no disponga de medios electrónicos.',b:'Será obligatoria de la forma que reglamentariamente se determine.',c:'Solo será obligatoria en procedimientos sancionadores o tributarios.',d:'Solo será obligatoria cuando así esté previsto en una norma con rango de ley.'}, correct:'d', why:{d:'El art. 19 LPAC establece que la comparecencia ante las oficinas solo es obligatoria cuando esté previsto en una norma con rango de ley.'}},
{n:31, q:'De conformidad con la Ley 39/2015, como regla general, la administración está obligada a dictar resolución expresa y notificarla...', o:{a:'En todos los procedimientos iniciados de oficio, salvo que una ley disponga lo contrario.',b:'En todos los procedimientos iniciados a instancia de parte, salvo que una ley disponga lo contrario.',c:'En todos los procedimientos cualquiera que sea su forma de iniciación.',d:'En todos los procedimientos salvo desistimiento, renuncia, caducidad o prescripción.'}, correct:'c', why:{c:'El art. 21 LPAC establece la obligación incondicional de resolver en todos los procedimientos.'}},
{n:32, q:'El plazo máximo en el que debe notificarse la resolución expresa de un procedimiento administrativo...', o:{a:'Será el fijado por la norma reguladora del correspondiente procedimiento.',b:'No podrá exceder de tres meses salvo norma legal mayor.',c:'Cuando las normas no fijen plazo, este será de dos meses.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 21.2 LPAC establece que el plazo máximo es el fijado por la norma reguladora del procedimiento correspondiente.'}},
{n:33, q:'De conformidad con la Ley 39/2015, considera directamente responsables de la obligación legal de dictar resolución expresa en plazo...', o:{a:'A las autoridades u organismos que tengan atribuida la competencia para emitir dicha resolución.',b:'Al personal al servicio de las administraciones públicas que tenga a su cargo el despacho de los asuntos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 20 LPAC establece la responsabilidad tanto de las autoridades competentes como del personal encargado del despacho.'}},
{n:34, q:'La Ley 39/2015 considera directamente responsables de la obligación legal de dictar resolución expresa en plazo...', o:{a:'A los titulares de los órganos administrativos competentes para instruir y resolver.',b:'A los funcionarios con habilitación de carácter nacional de las entidades locales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 20 LPAC responsabiliza a los titulares de órganos competentes. Según el solucionario la respuesta es b.'}},
{n:35, q:'La Ley 39/2015 permite suspender el plazo máximo legal para resolver un procedimiento y notificarlo...', o:{a:'Cuando deba requerirse a cualquier interesado para la subsanación de deficiencias o la aportación de documentos.',b:'Cuando deba obtenerse un pronunciamiento previo y preceptivo de un órgano de la Unión Europea.',c:'Cuando exista un procedimiento no finalizado en el ámbito de la Unión Europea que condicione directamente el contenido de la resolución.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 22 LPAC establece como causa de suspensión el requerimiento al interesado para subsanación de deficiencias.'}},
{n:36, q:'La Ley 39/2015 permite suspender el plazo máximo legal para resolver y notificar cuando se soliciten informes preceptivos...', o:{a:'Cuando se soliciten informes preceptivos a un órgano de la misma administración.',b:'Cuando se soliciten informes preceptivos a un órgano de otra administración distinta.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El art. 22 LPAC establece que la suspensión por informes preceptivos aplica cuando son determinantes del contenido de la resolución; no toda solicitud suspende automáticamente. Según el solucionario la respuesta es d.'}},
{n:37, q:'La Ley 39/2015 permite suspender el plazo máximo legal para resolver y notificar...', o:{a:'Solo cuando se soliciten informes preceptivos a órganos de la misma administración.',b:'Solo cuando se soliciten informes preceptivos a órganos de otras administraciones.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 22 LPAC permite la suspensión tanto por informes preceptivos de la propia administración como de otras administraciones, siempre que sean determinantes.'}},
{n:38, q:'La Ley 39/2015 permite suspender el plazo máximo legal para resolver y notificar...', o:{a:'En aquellos procedimientos en los que exista una pluralidad de interesados.',b:'Cuando se puedan realizarse pruebas técnicas o análisis contradictorios o dirimentes propuestos por los interesados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 22 LPAC permite suspender el plazo cuando sea necesaria la realización de pruebas técnicas o análisis contradictorios propuestos por los interesados.'}},
{n:39, q:'La Ley 39/2015 permite suspender el plazo máximo legal para resolver y notificar...', o:{a:'Cuando se inicien negociaciones con vistas a la conclusión de un pacto o convenio.',b:'Cuando para la resolución sea indispensable la obtención de un previo pronunciamiento jurisdiccional.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 22 LPAC establece la suspensión tanto por inicio de negociaciones para pactos como por necesidad de pronunciamiento jurisdiccional previo.'}},
{n:40, q:'La Ley 39/2015 determina la obligatoriedad de suspender el plazo máximo para resolver cuando...', o:{a:'El órgano decida realizar alguna actuación complementaria.',b:'Se produzca el desistimiento o renuncia de cualquiera de las partes personadas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El desistimiento o renuncia no es causa de suspensión obligatoria del plazo. Según el solucionario la respuesta es b.'}},
{n:41, q:'La Ley 39/2015 determina la obligatoriedad de suspender el plazo máximo legal para resolver cuando...', o:{a:'Se trate de actos que requieran una motivación específica.',b:'Los interesados promuevan la recusación en cualquier momento de la tramitación del procedimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 22.1.d) LPAC establece la suspensión obligatoria cuando los interesados promuevan la recusación.'}},
{n:42, q:'La Ley 39/2015 permite ampliar el plazo máximo para resolver y notificar...', o:{a:'En los procedimientos de revisión de actos anulables.',b:'Cuando se hayan agotado los medios personales y materiales disponibles.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 23 LPAC permite ampliar el plazo cuando se hayan agotado los medios personales y materiales disponibles.'}},
{n:43, q:'La Ley 39/2015 permite ampliar el plazo máximo de resolución y notificación...', o:{a:'Cuando los interesados promuevan la recusación.',b:'De manera motivada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 23 LPAC establece que la ampliación del plazo debe acordarse de forma motivada.'}},
{n:44, q:'La Ley 39/2015 permite ampliar el plazo máximo de resolución y notificación...', o:{a:'Por un plazo no superior al establecido para la tramitación del procedimiento.',b:'Salvo en procedimientos de responsabilidad patrimonial iniciados a instancia de los interesados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 23 LPAC permite la ampliación hasta la mitad del plazo original. Según el solucionario la respuesta es a.'}},
{n:45, q:'De conformidad con la Ley 39/2015, en los procedimientos iniciados a solicitud del interesado, cuando se produce el vencimiento del plazo máximo sin resolución expresa...', o:{a:'El interesado está legitimado para entender que su solicitud ha sido estimada.',b:'El interesado debe entender que sus pretensiones han sido desestimadas.',c:'El interesado debe entender estimada su pretensión, salvo que una norma con rango de ley o de la UE establezca lo contrario.',d:'Se produce la caducidad del procedimiento.'}, correct:'c', why:{c:'El art. 24 LPAC establece el silencio positivo como regla general, salvo que una ley o norma de la UE disponga lo contrario.'}},
{n:46, q:'En los procedimientos iniciados de oficio de los que pudiera derivarse el reconocimiento de derechos, cuando se produce el vencimiento del plazo máximo sin resolución expresa...', o:{a:'El interesado está legitimado para entender que su solicitud ha sido estimada.',b:'El interesado debe entender que sus pretensiones han sido desestimadas por silencio administrativo.',c:'El interesado debe entender estimada su pretensión por silencio.',d:'Se produce la caducidad del procedimiento.'}, correct:'b', why:{b:'El art. 25 LPAC establece que en procedimientos iniciados de oficio que puedan crear derechos, el vencimiento del plazo produce silencio negativo.'}},
{n:47, q:'En los procedimientos iniciados de oficio en los que la administración ejercite potestades sancionadoras, cuando se produce el vencimiento del plazo máximo sin resolución expresa...', o:{a:'El interesado está legitimado para entender que su solicitud ha sido estimada.',b:'El interesado debe entender que sus pretensiones han sido desestimadas.',c:'El interesado debe entender estimada su pretensión.',d:'Se produce la caducidad del procedimiento.'}, correct:'d', why:{d:'El art. 25.1 LPAC establece que en procedimientos sancionadores iniciados de oficio, el vencimiento del plazo produce caducidad.'}},
{n:48, q:'En los procedimientos iniciados a solicitud del interesado, el silencio administrativo tendrá efecto desestimatorio cuando se trate de...', o:{a:'Procedimientos relativos al derecho de petición del art. 29 CE.',b:'Actos discrecionales que requieran motivación específica.',c:'Procedimientos de naturaleza tributaria.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 24 LPAC establece que el silencio es desestimatorio en los procedimientos del derecho de petición, tributarios y otros previstos legalmente.'}},
{n:49, q:'En los procedimientos iniciados a solicitud del interesado, el silencio administrativo tendrá efecto desestimatorio cuando...', o:{a:'La estimación implique transferir facultades sobre el dominio público o el servicio público.',b:'La actividad que se pretenda ejercer pueda dañar el medio ambiente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 24 LPAC establece el silencio desestimatorio cuando la estimación implicaría transferir facultades sobre dominio o servicio público, o para actividades que puedan dañar el medio ambiente.'}},
{n:50, q:'En los procedimientos iniciados a solicitud del interesado, el silencio administrativo tendrá efecto desestimatorio en...', o:{a:'Los procedimientos de impugnación de actos y disposiciones.',b:'Los procedimientos tramitados por el procedimiento abreviado.',c:'Los procedimientos de selección de personal.',d:'Los procedimientos de recuperación del dominio público.'}, correct:'a', why:{a:'El art. 24 LPAC establece el silencio desestimatorio en los procedimientos de impugnación de actos y disposiciones (recursos administrativos).'}},
{n:51, q:'En los procedimientos iniciados a solicitud del interesado, el silencio administrativo tendrá efecto desestimatorio en...', o:{a:'Los procedimientos de revisión de oficio iniciados por solicitud del interesado.',b:'Los procedimientos de contratación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 24 LPAC establece el silencio desestimatorio en los procedimientos de revisión de oficio iniciados a instancia de interesado.'}},
{n:52, q:'Cuando se interponga recurso de alzada contra la desestimación por silencio administrativo y el órgano competente no dictase resolución expresa en plazo...', o:{a:'El recurso se entenderá estimado.',b:'El recurso se entenderá desestimado.',c:'El recurso se entenderá desestimado salvo que sea procedimiento de declaración responsable.',d:'El recurso se entenderá estimado, siempre que no se refiera a las materias enumeradas en el segundo párrafo del artículo 24.1 de esta ley.'}, correct:'d', why:{d:'El art. 24.3 LPAC establece que el recurso de alzada contra el silencio desestimatorio se entenderá estimado si el órgano no resuelve en plazo, salvo en las materias excepcionadas.'}},
{n:53, q:'En cuanto a la obligación de dictar resolución expresa cuando se haya producido silencio administrativo, el artículo 24.3 de la Ley 39/2015 dispone:', o:{a:'Que en casos de desestimación por silencio, la resolución expresa posterior solo podrá dictarse como confirmatoria.',b:'Que en casos de estimación por silencio, la resolución expresa posterior se adoptará sin vinculación alguna al sentido del silencio.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El art. 24.3 LPAC establece que tras silencio negativo la administración puede resolver en cualquier sentido; tras silencio positivo la resolución posterior solo puede ser confirmatoria.'}},
{n:54, q:'Los actos administrativos producidos por silencio administrativo...', o:{a:'Se podrán hacer valer tanto ante la administración como ante cualquier persona física o jurídica, pública o privada.',b:'Producen efectos desde el vencimiento del plazo máximo en el que debe dictarse y notificarse la resolución expresa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 24 LPAC establece que los actos por silencio son oponibles frente a todos y producen efectos desde el vencimiento del plazo de resolución.'}},
{n:55, q:'Los actos administrativos producidos por silencio administrativo...', o:{a:'Pueden acreditarse por cualquier medio de prueba admitido en Derecho.',b:'Pueden acreditarse mediante un certificado expedido de oficio en el plazo de 5 días.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 24 LPAC establece que los actos por silencio pueden acreditarse por cualquier medio de prueba admitido en Derecho.'}},
{n:56, q:'Para ser considerados válidos, los documentos electrónicos administrativos deben:', o:{a:'Contener información en soporte electrónico, en formato determinado susceptible de identificación y tratamiento diferenciado.',b:'Disponer de los datos de identificación que permitan su individualización.',c:'Incorporar una referencia temporal, los metadatos mínimos exigidos y las firmas electrónicas que correspondan.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 26 LPAC establece que los documentos electrónicos son válidos cuando contienen información en formato adecuado, datos de identificación, referencia temporal, metadatos y firmas electrónicas.'}},
{n:57, q:'Con respecto a la validez y eficacia de las copias realizadas por las administraciones públicas, la Ley 39/2015 dispone:', o:{a:'Que tendrán la consideración de copia auténtica las realizadas por los órganos competentes en las que quede garantizada la identidad del órgano y su contenido.',b:'Que las copias auténticas tendrán la misma validez y eficacia que los documentos originales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 27 LPAC establece que las copias auténticas tienen la misma validez y eficacia que los originales.'}},
{n:58, q:'Con respecto a la forma de computar los términos y plazos, la Ley 39/2015 dispone:', o:{a:'Que salvo norma contraria, cuando los plazos se señalen por horas, se entiende que estas son hábiles.',b:'Que son hábiles todas las horas del día que formen parte de un día hábil.',c:'Que los plazos expresados por horas se contarán de hora en hora y de minuto en minuto.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 29 LPAC establece que los plazos por horas son hábiles, que son hábiles todas las horas del día hábil, y que se computan de hora en hora.'}},
{n:59, q:'Con respecto a la forma de computar los términos y plazos, la Ley 39/2015 dispone:', o:{a:'Que cuando los plazos se expresen por horas no podrán tener una duración superior a las 24 horas.',b:'Que cuando los plazos se señalen por días, se entiende que estos son naturales.',c:'Que cuando los plazos se hayan señalado en días naturales no será necesario hacer constar tal circunstancia en las notificaciones.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 29 LPAC establece que cuando los plazos se expresen por horas no podrán tener una duración superior a 24 horas.'}},
{n:60, q:'Con respecto a la forma de computar los términos y plazos, la Ley 39/2015 dispone:', o:{a:'Que los plazos expresados en días se contarán a partir del día en que tenga lugar la notificación o publicación del acto.',b:'Que si el plazo se fija en meses o años, estos se computarán a partir del día siguiente a aquel en que tenga lugar la notificación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 30 LPAC establece que los plazos en meses o años se computan a partir del día siguiente a la notificación.'}},
{n:61, q:'La Ley 39/2015 dispone que cuando el plazo se haya fijado en meses o años...', o:{a:'Dicho plazo concluirá el día equivalente al de la notificación en el mes de vencimiento.',b:'Si en el mes de vencimiento no hubiera día equivalente al que comienza el cómputo, se entenderá que el plazo expira el último día del mes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 30.4 LPAC establece que si en el mes de vencimiento no hay día equivalente al inicial del cómputo, el plazo expira el último día del mes.'}},
{n:62, q:'Con respecto a la forma de computar los términos y plazos, la Ley 39/2015 dispone:', o:{a:'Que cuando el último día del plazo sea inhábil, se entenderá prorrogado al primer día hábil siguiente.',b:'Que cuando un día fuese hábil en el municipio en que reside el interesado e inhábil en la sede del órgano, se considerará hábil en todo caso.',c:'Que la declaración de un día como hábil o inhábil determinará por sí sola el funcionamiento de los centros de trabajo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 30.5 LPAC establece que cuando el último día del plazo sea inhábil, se prorroga al primer día hábil siguiente.'}},
{n:63, q:'Con respecto a la forma de computar los plazos en los registros, la Ley 39/2015 dispone:', o:{a:'Que cada administración publicará los días y el horario en que deben permanecer abiertas las oficinas de presentación electrónica.',b:'Que el registro electrónico permitirá la presentación de documentos todos los días del año durante las 24 horas.',c:'Que la presentación de un documento en el registro electrónico en día inhábil se entenderá realizada en la primera hora del primer día hábil siguiente.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 31 LPAC establece las tres características del registro electrónico: disponibilidad 24 horas todos los días del año, y cómputo desde el día hábil siguiente para los presentados en día inhábil.'}},
{n:64, q:'Con respecto a la forma de computar los plazos en los registros electrónicos, la Ley 39/2015 dispone:', o:{a:'Que los documentos se considerarán presentados por el orden de hora en que lo fueron en el día inhábil.',b:'Que los documentos presentados en el día inhábil se reputarán posteriores a los del primer día hábil anterior.',c:'Que la fecha y hora efectiva de inicio del cómputo deberá ser publicada en la sede electrónica.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 31 LPAC establece que los documentos presentados en día inhábil se ordenan por hora de presentación.'}},
{n:65, q:'Con respecto a la ampliación de los plazos establecidos en la Ley 39/2015, indique la respuesta correcta.', o:{a:'La administración podrá conceder una ampliación que no exceda de la tercera parte de los mismos.',b:'Solo podrá realizarse si las circunstancias lo aconsejan y no se perjudican los derechos de terceros.',c:'El acuerdo de ampliación se publicará en la sede electrónica.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 32 LPAC establece que la ampliación procede si las circunstancias lo aconsejan y no perjudican derechos de terceros, y no puede exceder la mitad del plazo original.'}},
{n:66, q:'Con respecto a la ampliación de los plazos establecidos en la Ley 39/2015, indique la respuesta correcta.', o:{a:'La petición de ampliación y la decisión deben producirse antes del vencimiento del plazo.',b:'En ningún caso podrá ser objeto de ampliación un plazo ya vencido.',c:'Los acuerdos sobre ampliación no serán susceptibles de recurso autónomo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 32 LPAC establece que la petición debe ser previa al vencimiento, que no se amplían plazos vencidos y que los acuerdos de ampliación no son susceptibles de recurso autónomo.'}},
{n:67, q:'El artículo 32.5 de la Ley 39/2015 determina que, cuando un ciberincidente haya afectado gravemente los sistemas utilizados para la tramitación de los procedimientos, la administración podrá acordar...', o:{a:'Una ampliación general de los plazos de los procedimientos administrativos.',b:'Que los asuntos acumulados se tramiten por el procedimiento abreviado.',c:'Que se suspendan los plazos establecidos para dictar resolución.',d:'Una situación de extraordinaria y urgente necesidad.'}, correct:'a', why:{a:'El art. 32.5 LPAC establece que ante ciberincidentes graves, la administración puede acordar una ampliación general de plazos.'}},
{n:68, q:'Con respecto a la tramitación de urgencia prevista en la Ley 39/2015, indique la respuesta incorrecta.', o:{a:'Se podrá acordar de oficio o a petición del interesado.',b:'Reduce a la mitad los plazos del procedimiento ordinario, salvo los relativos a la presentación de solicitudes y recursos.',c:'Contra el acuerdo de tramitación de urgencia puede interponerse recurso de alzada.',d:'Puede llevarse a cabo cuando razones de interés público así lo aconsejen.'}, correct:'c', why:{c:'La opción c) es incorrecta: el acuerdo de tramitación de urgencia no es recurrible de forma autónoma en alzada.'}},
{n:69, q:'La Ley 39/2015 establece que serán motivados los actos que...', o:{a:'Limiten derechos objetivos.',b:'Limiten intereses legítimos.',c:'Produzcan indefensión.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 35 LPAC establece que serán motivados los actos que limiten derechos subjetivos o intereses legítimos.'}},
{n:70, q:'La Ley 39/2015 establece que serán motivados los actos que...', o:{a:'Resuelvan procedimientos de revisión de oficio de disposiciones o actos administrativos.',b:'Resuelvan recursos administrativos.',c:'Resuelvan procedimientos de arbitraje.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 35 LPAC establece que serán motivados los actos que resuelvan revisiones de oficio, recursos y arbitrajes.'}},
{n:71, q:'La Ley 39/2015 establece que serán motivados los actos que...', o:{a:'Declaren la inadmisión de los recursos administrativos.',b:'Se separen del dictamen de los órganos consultivos.',c:'Adopten medidas provisionales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 35 LPAC establece que serán motivados los actos que declaren inadmisión de recursos, los que se separen de dictámenes consultivos y los que adopten medidas provisionales.'}},
{n:72, q:'La Ley 39/2015 establece que serán motivados los actos que...', o:{a:'Se separen del criterio seguido en actuaciones precedentes.',b:'Se deriven de actuaciones que puedan causar daños en el medio ambiente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y son incorrectas.'}, correct:'a', why:{a:'El art. 35 LPAC establece que serán motivados los actos que se separen del criterio seguido en actuaciones precedentes.'}},
{n:73, q:'La Ley 39/2015 establece que serán motivados los actos que...', o:{a:'Suspendan actos, cualquiera que sea el motivo.',b:'Rechacen pruebas propuestas por los interesados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y son incorrectas.'}, correct:'c', why:{c:'El art. 35 LPAC establece que serán motivados los actos que suspendan actos y los que rechacen pruebas propuestas.'}},
{n:74, q:'La Ley 39/2015 establece que serán motivados los actos que...', o:{a:'Apliquen la tramitación de urgencia.',b:'Decidan una ampliación de plazos.',c:'Acuerden la realización de actividades complementarias.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 35 LPAC establece que serán motivados los actos que acuerden tramitación de urgencia, ampliación de plazos y actuaciones complementarias.'}},
{n:75, q:'La Ley 39/2015 establece que serán motivados los actos que...', o:{a:'Acuerden la terminación del procedimiento mediante pacto o convenio.',b:'Acuerden la terminación del procedimiento por imposibilidad material de continuarlo por causas sobrevenidas.',c:'Acuerden la renuncia de la administración en los procedimientos iniciados a instancia de parte.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 35 LPAC establece que serán motivados los actos de terminación convencional, por imposibilidad sobrevenida y otros supuestos.'}},
{n:76, q:'La Ley 39/2015 establece que serán motivados...', o:{a:'Los actos que resuelvan procedimientos de carácter sancionador.',b:'Los actos que resuelvan procedimientos de responsabilidad patrimonial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y son incorrectas.'}, correct:'c', why:{c:'El art. 35 LPAC establece que serán motivados los actos que resuelvan procedimientos sancionadores y de responsabilidad patrimonial.'}},
{n:77, q:'La Ley 39/2015 establece que será motivada...', o:{a:'La propuesta de resolución en los procedimientos sancionadores.',b:'La propuesta de resolución en los procedimientos de responsabilidad patrimonial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y son incorrectas.'}, correct:'a', why:{a:'El art. 35 LPAC establece expresamente que será motivada la propuesta de resolución en los procedimientos sancionadores.'}},
{n:78, q:'La Ley 39/2015 establece que serán motivados los actos que...', o:{a:'Se dicten en el ejercicio de potestades regladas.',b:'Se dicten en el ejercicio de potestades discrecionales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y son incorrectas.'}, correct:'b', why:{b:'El art. 35 LPAC establece que serán motivados los actos que se dicten en el ejercicio de potestades discrecionales.'}},
{n:79, q:'La Ley 39/2015 establece que...', o:{a:'Los actos administrativos se producirán por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma.',b:'Una serie de actos administrativos de la misma naturaleza podrán refundirse en un único acto.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 36 LPAC establece que los actos se producen por escrito electrónico salvo necesidad de otra forma, y que los actos de la misma naturaleza pueden refundirse.'}},
{n:80, q:'La Ley 39/2015 establece que...', o:{a:'Las resoluciones singulares solo podrán vulnerar lo establecido en una disposición general cuando procedan de un órgano de igual o superior jerarquía.',b:'Son nulas las resoluciones administrativas que vulneren lo establecido en una disposición reglamentaria.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 37 LPAC establece que las resoluciones singulares no podrán vulnerar lo establecido en una disposición general aunque procedan de un órgano de igual o superior jerarquía.'}},
{n:81, q:'Los actos de las administraciones públicas sujetos al Derecho Administrativo...', o:{a:'Se presumirán válidos.',b:'Producirán efectos desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y son incorrectas.'}, correct:'c', why:{c:'El art. 39 LPAC establece que los actos se presumen válidos y producen efectos desde la fecha en que se dicten.'}},
{n:82, q:'La Ley 39/2015 establece que...', o:{a:'La eficacia del acto quedará demorada cuando así lo exija su contenido.',b:'La eficacia del acto quedará demorada cuando esté supeditada a su notificación, publicación o aprobación posterior.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 39.2 LPAC establece que la eficacia del acto queda demorada cuando lo exige su contenido o está supeditada a notificación, publicación o aprobación posterior.'}},
{n:83, q:'La Ley 39/2015 permite, con carácter excepcional, otorgar eficacia retroactiva a los actos cuando...', o:{a:'Se trate de actos de trámite que no produzcan efectos desfavorables.',b:'Se dicten en sustitución de otros actos anulados.',c:'El acto tenga como destinatarios a una pluralidad indeterminada de interesados.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 39.3 LPAC establece la retroactividad excepcional cuando los actos se dicten en sustitución de actos anulados o cuando produzcan efectos favorables.'}},
{n:84, q:'La Ley 39/2015 permite, con carácter excepcional, otorgar eficacia retroactiva a los actos cuando...', o:{a:'El acto produzca efectos desfavorables al interesado, siempre que los supuestos de hecho necesarios existieran ya.',b:'Se trate de procedimientos de concurrencia competitiva, siempre que los supuestos de hecho existieran ya.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El art. 39.3 LPAC establece la retroactividad solo para actos favorables, no para los que produzcan efectos desfavorables.'}},
{n:85, q:'Según la Ley 39/2015...', o:{a:'Toda notificación deberá ser cursada dentro del plazo de 15 días a partir de la fecha en la que el acto haya sido dictado.',b:'Toda notificación deberá contener el texto íntegro de la resolución, con indicación de si pone fin o no a la vía administrativa, los recursos procedentes y los plazos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y son incorrectas.'}, correct:'b', why:{b:'El art. 40 LPAC establece que la notificación debe contener el texto íntegro del acto, indicación de si pone fin a la vía administrativa, recursos procedentes y plazos.'}},
{n:86, q:'Según la Ley 39/2015, las notificaciones que omitan alguno de los demás requisitos previstos...', o:{a:'Surtirán efecto a partir de la fecha en que el interesado realice actuaciones que supongan el conocimiento del contenido del acto.',b:'Surtirán efecto a partir de la fecha en que el interesado interponga cualquier recurso que proceda.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 40.3 LPAC establece que las notificaciones defectuosas surtirán efecto desde que el interesado realice actuaciones que impliquen conocimiento del contenido o interponga recurso.'}},
{n:87, q:'Según la Ley 39/2015, será suficiente la notificación que contenga, cuando menos, el texto íntegro de la resolución, así como el intento de notificación debidamente acreditado...', o:{a:'A los solos efectos de cumplir con el trámite de información pública.',b:'A los solos efectos de garantizar la debida finalización del procedimiento.',c:'A los solos efectos de entender cumplida la obligación de notificar dentro del plazo máximo de duración de los procedimientos.',d:'A los solos efectos de posibilitar la interposición de recursos.'}, correct:'c', why:{c:'El art. 40.4 LPAC establece que el intento acreditado con el texto íntegro es suficiente a efectos de cumplir la obligación de notificar dentro del plazo máximo.'}},
{n:88, q:'Según la Ley 39/2015, las notificaciones se practicarán...', o:{a:'Preferentemente por medios electrónicos.',b:'Exclusivamente por medios electrónicos.',c:'Por medios electrónicos salvo que el interesado esté obligado a recibirlas por otra vía.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art. 41 LPAC establece que las notificaciones se practicarán preferentemente por medios electrónicos.'}},
{n:89, q:'Según la Ley 39/2015, cuando se produzca comparecencia espontánea del interesado o representante en las oficinas de asistencia en materia de registro, solicitando comunicación o notificación personal...', o:{a:'La notificación se practicará exclusivamente por medios electrónicos.',b:'La notificación se practicará por medios no electrónicos.',c:'La notificación podrá practicarse por medios no electrónicos.',d:'La notificación se llevará a cabo por edictos.'}, correct:'c', why:{c:'El art. 41.1 LPAC establece que en ese caso la notificación podrá practicarse por medios no electrónicos.'}},
{n:90, q:'Según la Ley 39/2015, la notificación podrá practicarse por medios no electrónicos...', o:{a:'En los supuestos de procedimientos sancionadores y de concurrencia competitiva.',b:'En los supuestos de agotamiento de plazos, debidamente justificado.',c:'Cuando el acto se produzca por terminación anormal del procedimiento.',d:'Cuando para asegurar la eficacia resulte necesario practicarla por entrega directa de un empleado.'}, correct:'d', why:{d:'El art. 41 LPAC establece que la notificación puede practicarse por medios no electrónicos cuando sea necesaria la entrega directa por un empleado para asegurar la eficacia.'}},
{n:91, q:'Según la Ley 39/2015, las notificaciones por medios electrónicos...', o:{a:'Se practicarán mediante comparecencia en la sede electrónica.',b:'Se practicarán a través de la dirección electrónica habilitada única.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y son incorrectas.'}, correct:'c', why:{c:'El art. 43 LPAC establece que las notificaciones electrónicas se practican mediante comparecencia en la sede electrónica o a través de la DEHú.'}},
{n:92, q:'Según la Ley 39/2015 se entiende por comparecencia en la sede electrónica...', o:{a:'El acceso del interesado debidamente identificado al contenido de la notificación.',b:'El acceso del representante del interesado debidamente identificado al contenido.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 43 LPAC establece que la comparecencia supone el acceso del interesado o su representante debidamente identificado al contenido de la notificación.'}},
{n:93, q:'Según la Ley 39/2015, las notificaciones por medios electrónicos se entenderán practicadas...', o:{a:'En el momento en que el interesado realice actuaciones que evidencien su conocimiento.',b:'En el momento en que se produzca el acceso a su contenido.',c:'En el momento en que el interesado interponga recursos procedentes.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 43.2 LPAC establece que las notificaciones electrónicas se entienden practicadas en el momento en que se produzca el acceso a su contenido.'}},
{n:94, q:'Según la Ley 39/2015, cuando la notificación electrónica sea obligatoria o haya sido expresamente elegida por el interesado, se entenderá rechazada...', o:{a:'Cuando hayan transcurridos diez días hábiles desde la puesta a disposición sin que se acceda a su contenido.',b:'Cuando hayan transcurridos diez días naturales desde la puesta a disposición sin que se acceda a su contenido.',c:'Cuando hayan transcurridos quince días hábiles desde la puesta a disposición sin que se acceda.',d:'Cuando hayan transcurridos quince días naturales desde la puesta a disposición sin que se acceda.'}, correct:'a', why:{a:'El art. 43.2 LPAC establece que se entiende rechazada la notificación cuando hayan transcurrido diez días naturales desde la puesta a disposición sin acceder. Según el solucionario la respuesta es a.'}},
{n:95, q:'Según la Ley 39/2015, la notificación se realizará por anuncio en el Boletín Oficial del Estado...', o:{a:'Cuando los interesados en un procedimiento sean desconocidos.',b:'Cuando se ignore el lugar de la notificación.',c:'Cuando, intentada la notificación, no se hubiere podido practicar.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 44 LPAC establece que la notificación edictal en el BOE procede cuando los interesados son desconocidos, se ignora el lugar o la notificación no pudo practicarse.'}},
{n:96, q:'Según la Ley 39/2015, los actos administrativos serán objeto de publicación...', o:{a:'Cuando así lo establezcan las normas reguladoras de cada procedimiento.',b:'Cuando lo aconsejen razones de interés público o privado, apreciadas por el órgano competente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 45 LPAC establece que los actos serán objeto de publicación cuando así lo establezcan las normas reguladoras del procedimiento o cuando lo aconsejen razones de interés público.'}},
{n:97, q:'Según la Ley 39/2015, los actos administrativos serán objeto de publicación...', o:{a:'Cuando el acto tenga por destinatarios a una pluralidad indeterminada de personas.',b:'Cuando la administración estime que la notificación individual es insuficiente para garantizar la notificación a todos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 45 LPAC establece la publicación cuando los destinatarios son una pluralidad indeterminada o cuando la notificación individual es insuficiente.'}},
{n:98, q:'Según la Ley 39/2015, los actos administrativos serán objeto de publicación...', o:{a:'Cuando el interesado disponga de varios domicilios válidos y no se garantice el conocimiento íntegro del acto.',b:'Cuando se trate de actos integrantes de un procedimiento selectivo o de concurrencia competitiva de cualquier tipo.',c:'En los procedimientos de expropiación forzosa.',d:'En los procedimientos disciplinarios contra empleados públicos.'}, correct:'b', why:{b:'El art. 45 LPAC establece la publicación obligatoria para los actos integrantes de procedimientos selectivos o de concurrencia competitiva.'}},
{n:99, q:'La Ley 39/2015 considera nulos de pleno derecho, los actos...', o:{a:'Que tengan un contenido imposible.',b:'Que incurran en cualquier infracción del ordenamiento jurídico.',c:'Que no hayan sido dictados en tiempo y forma.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 47 LPAC establece que son nulos de pleno derecho los actos con contenido imposible.'}},
{n:100, q:'La Ley 39/2015 considera nulos de pleno derecho, los actos...', o:{a:'Que lesionen derechos y libertades susceptibles de amparo constitucional.',b:'Dictados por órgano manifiestamente incompetente por razón de jerarquía o del territorio.',c:'Que sean constitutivos de infracción penal o administrativa.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 47 LPAC establece que son nulos de pleno derecho los actos que lesionen derechos y libertades susceptibles de amparo constitucional.'}},
{n:101, q:'La Ley 39/2015 considera nulos de pleno derecho, los actos...', o:{a:'Que incurran en desviación de poder.',b:'Que hayan sido dictados prescindiendo total y absolutamente del procedimiento legalmente establecido.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 47 LPAC establece que son nulos de pleno derecho los actos dictados prescindiendo total y absolutamente del procedimiento.'}},
{n:102, q:'La Ley 39/2015 considera nulos de pleno derecho,...', o:{a:'Los actos que prescindan de las normas esenciales para la formación de la voluntad de los órganos colegiados.',b:'Los actos expresos contrarios al ordenamiento que adquieren facultades o derechos sin los requisitos esenciales.',c:'Los actos presuntos contrarios al ordenamiento que adquieren facultades o derechos sin los requisitos esenciales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 47 LPAC establece la nulidad plena para los actos que prescindan de normas esenciales de órganos colegiados, y para los que reconozcan derechos sin los requisitos esenciales.'}},
{n:103, q:'En lo que respecta a las disposiciones administrativas, la Ley 39/2015 considera que serán nulas de pleno derecho cuando...', o:{a:'Vulneren la Constitución, las leyes u otras disposiciones administrativas de rango igual o superior.',b:'Regulen materias reservadas a ley.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 47.2 LPAC establece que serán nulas de pleno derecho las disposiciones que regulen materias reservadas a ley.'}},
{n:104, q:'En lo que respecta a las disposiciones administrativas, la Ley 39/2015 considera que serán nulas de pleno derecho cuando...', o:{a:'Incurran en desviación de poder.',b:'Establezcan la retroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos individuales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 47.2 LPAC establece que serán nulas las disposiciones que establezcan retroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos.'}},
{n:105, q:'La Ley 39/2015 considera anulables los actos...', o:{a:'Que incurran en cualquier infracción del ordenamiento jurídico.',b:'Que incurran en desviación de poder.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 48 LPAC establece que son anulables los actos que incurran en cualquier infracción del ordenamiento, incluyendo la desviación de poder.'}},
{n:106, q:'Según la Ley 39/2015, la realización de actuaciones administrativas fuera del tiempo establecido...', o:{a:'Solo implicará la nulidad del acto cuando así lo imponga la naturaleza del término o plazo.',b:'Solo implicará la anulabilidad del acto cuando así lo imponga la naturaleza del término o plazo.',c:'Podrán ser objeto de convalidación por el superior jerárquico.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 48.3 LPAC establece que la realización de actuaciones fuera de plazo solo implica anulabilidad cuando así lo imponga la naturaleza del término o plazo.'}},
{n:107, q:'Según la Ley 39/2015...', o:{a:'La nulidad o anulabilidad de un acto implicará la de los sucesivos en el procedimiento aunque sean independientes del primero.',b:'La nulidad o anulabilidad en parte del acto administrativo no implicará la de las partes independientes, salvo que la parte viciada sea esencial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 49 LPAC establece que la nulidad o anulabilidad parcial no implica la del resto si las partes son independientes, salvo que la parte viciada sea esencial.'}},
{n:108, q:'Según la Ley 39/2015.', o:{a:'Los actos nulos o anulables que contengan elementos constitutivos de otro distinto producirán los efectos de éste.',b:'El órgano que declare la nulidad dispondrá siempre la conservación de aquellos actos y trámites cuyo contenido se hubiera mantenido igual.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Los arts. 50 y 51 LPAC establecen la conversión de los actos nulos y la conservación de actos y trámites independientes del vicio.'}},
{n:109, q:'De conformidad con la Ley 39/2015, con respecto a la convalidación de actos, indique la respuesta correcta:', o:{a:'El acto de convalidación producirá efectos desde su fecha, salvo lo previsto sobre retroactividad.',b:'Cuando el vicio sea incompetencia por razón de materia o territorio, la convalidación podrá realizarse por el órgano competente superior jerárquico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 52 LPAC establece que el acto de convalidación produce efectos desde su fecha, salvo lo previsto en la ley sobre retroactividad.'}},
{n:110, q:'Según la Ley 39/2015, la administración...', o:{a:'Podrá convalidar los actos nulos subsanando los vicios de que adolezcan.',b:'Podrá convalidar los actos anulables subsanando los vicios de que adolezcan.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 52 LPAC establece que la administración puede convalidar los actos anulables; los nulos de pleno derecho no son convalidables.'}},
{n:111, q:'Los derechos del interesado en el procedimiento administrativo están regulados en...', o:{a:'El artículo 53 de la Ley 40/2015.',b:'El artículo 13 de la Ley 40/2015.',c:'El artículo 53 de la Ley 39/2015.',d:'El artículo 13 de la Ley 39/2015.'}, correct:'c', why:{c:'Los derechos del interesado en el procedimiento administrativo están regulados en el art. 53 de la Ley 39/2015.'}},
{n:112, q:'Los derechos de las personas en sus relaciones con las administraciones públicas están regulados en...', o:{a:'El artículo 53 de la Ley 40/2015.',b:'El artículo 13 de la Ley 40/2015.',c:'El artículo 53 de la Ley 39/2015.',d:'El artículo 13 de la Ley 39/2015.'}, correct:'d', why:{d:'Los derechos de las personas en sus relaciones con las AAPP están regulados en el art. 13 de la Ley 39/2015.'}},
{n:113, q:'En el procedimiento administrativo se distinguen las fases de:', o:{a:'Iniciación, gestión, instrucción y finalización.',b:'Iniciación, gestión, instrucción y resolución.',c:'Iniciación, ordenación, instrucción y finalización.',d:'Información, iniciación, instrucción y resolución.'}, correct:'c', why:{c:'Las fases del procedimiento administrativo son: iniciación, ordenación, instrucción y finalización.'}},
{n:114, q:'Los procedimientos administrativos podrán iniciarse...', o:{a:'De oficio o a solicitud del interesado.',b:'De oficio o por decisión judicial.',c:'Por propia iniciativa o cuando lo solicite una administración que tenga interés en el asunto.',d:'Por acuerdo del instructor, en los casos y forma legalmente establecidos.'}, correct:'a', why:{a:'El art. 54 LPAC establece que los procedimientos se iniciarán de oficio o a solicitud del interesado.'}},
{n:115, q:'Según la Ley 39/2015...', o:{a:'Con anterioridad al inicio del procedimiento, el órgano competente podrá abrir un periodo de información o actuaciones previas.',b:'Las actuaciones previas serán realizadas por los órganos que tengan atribuidas funciones de resolución en la materia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 55 LPAC establece que antes de iniciar el procedimiento el órgano competente puede abrir un periodo de información o actuaciones previas.'}},
{n:116, q:'Según la Ley 39/2015...', o:{a:'Iniciado el procedimiento, el instructor podrá adoptar las medidas provisionales que estime oportunas.',b:'En caso de urgencia inaplazable, antes de iniciarse el procedimiento, el órgano competente para iniciarlo o instruirlo puede adoptar medidas provisionales.',c:'Las medidas provisionales podrán adoptarse únicamente de oficio.',d:'Las medidas provisionales no precisan de motivación alguna.'}, correct:'b', why:{b:'El art. 56 LPAC establece que en casos de urgencia inaplazable, antes del inicio, el órgano competente puede adoptar medidas provisionales.'}},
{n:117, q:'Según la Ley 39/2015, en la adopción de medidas provisionales se tendrán en cuenta los principios de...', o:{a:'Proporcionalidad, publicidad y confidencialidad.',b:'Proporcionalidad, publicidad y efectividad.',c:'Proporcionalidad, efectividad e interés público.',d:'Proporcionalidad, efectividad y menor onerosidad.'}, correct:'d', why:{d:'El art. 56 LPAC establece que las medidas provisionales deben respetar los principios de proporcionalidad, efectividad y menor onerosidad.'}},
{n:118, q:'Según la Ley 39/2015, la competencia para adoptar medidas provisionales, una vez iniciado el procedimiento, corresponde a...', o:{a:'El órgano competente para resolver.',b:'El órgano competente para instruir el procedimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 56 LPAC establece que una vez iniciado el procedimiento, la competencia para adoptar medidas provisionales corresponde al órgano competente para resolver.'}},
{n:119, q:'Según la Ley 39/2015, la competencia para adoptar medidas provisionales antes de la iniciación del procedimiento corresponde a...', o:{a:'El órgano competente para iniciar el procedimiento.',b:'El órgano competente para instruir el procedimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 56 LPAC establece que antes de la iniciación, la competencia corresponde al órgano competente para iniciar o instruir el procedimiento.'}},
{n:120, q:'Según la Ley 39/2015, la adopción de medidas provisionales antes de la iniciación del procedimiento...', o:{a:'Requiere de una situación de urgencia inaplazable.',b:'Se adoptará para la protección provisional de los intereses implicados.',c:'Deberá realizarse de forma motivada.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 56 LPAC establece que las medidas provisionales previas requieren urgencia inaplazable, finalidad de protección provisional y motivación.'}},
{n:121, q:'Según la Ley 39/2015, las medidas provisionales adoptadas antes de la iniciación del procedimiento deberán ser confirmadas, modificadas o levantadas...', o:{a:'En la propuesta de resolución del procedimiento, dentro de los 15 días siguientes a su adopción.',b:'En el acuerdo de iniciación del procedimiento, dentro de los 15 días siguientes a su adopción.',c:'En la propuesta de resolución, dentro de los 10 días siguientes a su adopción.',d:'En el acuerdo de iniciación del procedimiento, dentro de los 10 días siguientes a su adopción.'}, correct:'b', why:{b:'El art. 56.3 LPAC establece que las medidas provisionales previas deben confirmarse, modificarse o levantarse en el acuerdo de iniciación, dentro de los 15 días siguientes.'}},
{n:122, q:'De conformidad con la Ley 39/2015, las medidas provisionales que se podrán adoptar antes o una vez iniciado el procedimiento, podrán consistir en:', o:{a:'Suspensión definitiva de actividades.',b:'Depósito, retención o inmovilización de inmuebles.',c:'Retirada e intervención de bienes productivos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 56.4 LPAC enumera entre las medidas provisionales la retirada e intervención de bienes productivos.'}},
{n:123, q:'De conformidad con la Ley 39/2015, las medidas provisionales podrán consistir en:', o:{a:'Prestación de fianzas.',b:'Pago de aranceles.',c:'Privación del derecho de sufragio.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 56.4 LPAC establece que la prestación de fianzas es una medida provisional posible.'}},
{n:124, q:'De conformidad con la Ley 39/2015, las medidas provisionales podrán consistir en:', o:{a:'Suspensión temporal de servicios por razones de sanidad, higiene o seguridad.',b:'Cierre temporal de establecimientos por causas previstas en la normativa reguladora.',c:'Embargo preventivo de bienes, rentas y cosas fungibles.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 56.4 LPAC enumera la suspensión temporal de servicios, el cierre temporal de establecimientos y el embargo preventivo como medidas provisionales posibles.'}},
{n:125, q:'De conformidad con la Ley 39/2015, las medidas provisionales podrán consistir en:', o:{a:'Intervención y depósito de ingresos obtenidos mediante una actividad que se considere ilícita y cuya prohibición o cesación se pretenda.',b:'Restricción de la libertad personal cuando la permanencia del interesado pueda provocar un riesgo para el interés público.',c:'Privación provisional del derecho a aproximarse o comunicarse con cualquiera de los afectados.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 56.4 LPAC establece que la intervención y depósito de ingresos obtenidos mediante actividad ilícita es una medida provisional posible.'}},
{n:126, q:'De conformidad con la Ley 39/2015, las medidas provisionales podrán consistir en:', o:{a:'Consignación o constitución de depósito de las cantidades que se reclamen.',b:'Retención de ingresos a cuenta que deban abonar las administraciones públicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 56.4 LPAC establece que la consignación o constitución de depósito es una medida provisional posible.'}},
{n:127, q:'De conformidad con la Ley 39/2015, no se podrán adoptar medidas provisionales:', o:{a:'Que puedan causar perjuicio de difícil o imposible reparación a los interesados.',b:'Que impliquen violación de los derechos amparados por las leyes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 56.2 LPAC establece que no podrán adoptarse medidas provisionales que causen perjuicio de difícil o imposible reparación, ni que impliquen violación de derechos amparados por las leyes.'}},
{n:128, q:'De conformidad con la Ley 39/2015, las medidas provisionales:', o:{a:'No podrán ser alzadas o modificadas durante la tramitación.',b:'Se extinguirán cuando surta efectos la resolución administrativa que ponga fin al procedimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 56.5 LPAC establece que las medidas provisionales se extinguirán cuando surta efectos la resolución que ponga fin al procedimiento.'}},
{n:129, q:'La iniciación de oficio de un procedimiento administrativo puede ser:', o:{a:'Por acuerdo del órgano competente.',b:'A petición razonada de otros órganos.',c:'Por denuncia.',d:'Por cualquiera de las formas anteriores.'}, correct:'d', why:{d:'El art. 58 LPAC establece que los procedimientos de oficio pueden iniciarse por acuerdo del órgano competente, a petición razonada de otros órganos o por denuncia.'}},
{n:130, q:'Cuando un procedimiento administrativo se inicia de oficio por acuerdo del órgano competente, éste puede hacerlo como consecuencia de:', o:{a:'Propia iniciativa.',b:'Orden superior.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 58 LPAC establece que el acuerdo de iniciación puede surgir por propia iniciativa, orden superior, petición razonada de otros órganos o denuncia.'}},
{n:131, q:'Cuando la Administración, a la vista de unos hechos, entiende que debe producirse un acto administrativo, decimos que el procedimiento se ha iniciado:', o:{a:'A instancia de parte.',b:'De oficio.',c:'A instancia de otra Administración.',d:'Por petición expresa de un órgano administrativo.'}, correct:'b', why:{b:'Cuando la administración actúa autónomamente sin solicitud del ciudadano, el procedimiento se inicia de oficio.'}},
{n:132, q:'De conformidad con la Ley 39/2015, con relación a la iniciación de oficio, indique la respuesta correcta:', o:{a:'Se entiende por propia iniciativa la actuación derivada del conocimiento directo o indirecto de las circunstancias por el órgano con competencia de iniciación.',b:'Se entiende por denuncia la propuesta de iniciación formulada por cualquier órgano que no tenga competencia para iniciar el procedimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 58 LPAC define la propia iniciativa como la actuación derivada del conocimiento directo o indirecto de las circunstancias por el órgano competente.'}},
{n:133, q:'De conformidad con la Ley 39/2015, la petición razonada de iniciación de un procedimiento administrativo...', o:{a:'Vincula al órgano competente para iniciar el procedimiento.',b:'El órgano competente está obligado a comunicar al peticionario los motivos por los que no procede la iniciación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 58 LPAC establece que la petición razonada no vincula al órgano competente, pero este debe comunicar al peticionario los motivos por los que no procede la iniciación.'}},
{n:134, q:'De conformidad con la Ley 39/2015, en los procedimientos iniciados por denuncia, ésta deberá expresar:', o:{a:'La identidad de la persona o personas que las presentan.',b:'El relato de los hechos que se ponen en conocimiento de la administración.',c:'Cuando los hechos pudieran constituir una infracción administrativa, deben recoger la fecha de su comisión y, cuando sea posible, la identificación de los presuntos responsables.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 62 LPAC establece que la denuncia debe expresar la identidad del denunciante, el relato de hechos y, cuando sea posible, fecha e identificación de los responsables.'}},
{n:135, q:'Con la iniciación del procedimiento administrativo, la Administración puede:', o:{a:'Abrir un periodo de información previa o adoptar medidas provisionales.',b:'Acumular los asuntos, cuando así proceda.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 57 LPAC permite la acumulación de asuntos relacionados, y el art. 56 permite adoptar medidas provisionales.'}},
{n:136, q:'De conformidad con la Ley 39/2015, indique cuál de los requisitos siguientes no es obligatorio en las solicitudes de los interesados:', o:{a:'Firma del solicitante o acreditación de la autenticidad de su voluntad.',b:'Órgano, centro o unidad administrativa al que se dirige.',c:'Identificación del medio electrónico o lugar físico donde desea recibir la notificación.',d:'Copia autenticada o compulsada del documento nacional de identidad del solicitante.'}, correct:'d', why:{d:'El art. 66 LPAC establece los requisitos mínimos de la solicitud; no incluye la copia autenticada del DNI.'}},
{n:137, q:'De conformidad con la Ley 39/2015, indique cuál de los requisitos siguientes es obligatorio en las solicitudes de los interesados:', o:{a:'Lugar y fecha.',b:'Nombre y apellidos del interesado y, en su caso, de la persona que lo represente.',c:'Hechos, razones y petición en que se concrete, con toda claridad, la solicitud.',d:'Todos los requisitos anteriores son obligatorios.'}, correct:'d', why:{d:'El art. 66 LPAC establece que son requisitos obligatorios la identificación del solicitante, lugar y fecha, hechos, razones y petición, órgano al que se dirige y firma.'}},
{n:138, q:'Según la Ley 39/2015, de las solicitudes, comunicaciones y escritos que presenten los interesados, podrán estos exigir el correspondiente recibo que acredite:', o:{a:'Fecha y hora de presentación.',b:'Fecha en la que el asunto empieza a ser tramitado.',c:'Identificación del funcionario que acusa recibo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 66 LPAC establece que el recibo de presentación debe acreditar fecha y hora de presentación, fecha de inicio de tramitación e identificación del funcionario.'}},
{n:139, q:'De conformidad con la Ley 39/2015...', o:{a:'Las administraciones deberán establecer modelos y sistemas de presentación masiva.',b:'Cuando la administración establezca expresamente modelos específicos de presentación de solicitudes, éstos serán de uso obligatorio por los interesados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 66.6 LPAC establece que cuando la administración establezca modelos específicos, su uso es obligatorio para los interesados.'}},
{n:140, q:'De conformidad con la Ley 39/2015, cuando la solicitud de iniciación no reúne los requisitos exigidos, la administración...', o:{a:'Debe rechazar la solicitud.',b:'Debe subsanar de oficio.',c:'Debe requerir al interesado para que subsane en el plazo de 10 días.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El art. 68 LPAC establece que la administración requerirá al interesado para que subsane en el plazo de 10 días con indicación de que si no lo hace se le tendrá por desistido; ninguna de las opciones a, b, c describe esto con exactitud.'}},
{n:141, q:'De conformidad con la Ley 39/2015, con relación a la subsanación y mejora de la solicitud, indique la respuesta incorrecta:', o:{a:'Si la solicitud no reúne los requisitos exigidos se requerirá al interesado para que subsane en el plazo de 15 días.',b:'Se advertirá al interesado que si no subsanare en el plazo previsto, se le tendrá por desistido.',c:'En el caso de que se tenga por desistido al solicitante, la administración dictará una resolución reconociendo esta circunstancia.',d:'El plazo para subsanar podrá ampliarse prudencialmente hasta cinco días.'}, correct:'a', why:{a:'La opción a) es incorrecta: el art. 68 LPAC establece un plazo de 10 días para subsanar, no 15.'}},
{n:142, q:'De acuerdo con la Ley 39/2015, el documento suscrito por un interesado en el que manifiesta, bajo su responsabilidad, que cumple los requisitos establecidos en la normativa para acceder al reconocimiento de un derecho o facultad, recibe el nombre de:', o:{a:'Declaración responsable.',b:'Comunicación previa.',c:'Acto de trámite.',d:'Instrucción del procedimiento.'}, correct:'a', why:{a:'El art. 69 LPAC define la declaración responsable.'}},
{n:143, q:'Según la Ley 39/2015, el documento mediante el que los interesados ponen en conocimiento de la Administración Pública sus datos identificativos y demás requisitos exigibles para el ejercicio de un derecho o inicio de una actividad, recibe el nombre de:', o:{a:'Declaración responsable.',b:'Comunicación.',c:'Compromiso previo.',d:'Recurso de alzada.'}, correct:'b', why:{b:'El art. 69 LPAC define la comunicación.'}},
{n:144, q:'Según la Ley 39/2015, permitirán el reconocimiento o ejercicio de un derecho, o bien el inicio de una actividad, desde el día de su presentación. Esta afirmación está referida a:', o:{a:'Las declaraciones responsables.',b:'Las comunicaciones.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 69 LPAC establece que tanto las declaraciones responsables como las comunicaciones habilitan para el ejercicio del derecho o inicio de la actividad desde el día de su presentación.'}},
{n:145, q:'De conformidad con la Ley 39/2015...', o:{a:'Las administraciones tendrán permanentemente publicados y actualizados modelos de declaración responsable y de comunicación.',b:'Para iniciar una misma actividad, las administraciones podrán exigir una declaración responsable, una comunicación, o ambas a la vez.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 69 LPAC establece que las AAPP deben tener publicados y actualizados los modelos de declaración responsable y de comunicación.'}},
{n:146, q:'Según la Ley 39/2015, el conjunto ordenado de documentos y actuaciones que sirven de antecedente y fundamento a la resolución administrativa recibe el nombre de...', o:{a:'Acto administrativo.',b:'Procedimiento administrativo.',c:'Expediente administrativo.',d:'Declaración responsable.'}, correct:'c', why:{c:'El art. 70 LPAC define el expediente administrativo.'}},
{n:147, q:'Según la Ley 39/2015, los expedientes administrativos...', o:{a:'Tendrán formato electrónico.',b:'Se formarán mediante la agregación ordenada de documentos, pruebas, dictámenes, informes, acuerdos y notificaciones.',c:'Dispondrán de un índice numerado de todos los documentos que contenga cuando se remita.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 70 LPAC establece que los expedientes tienen formato electrónico, se forman por agregación ordenada y deben llevar índice numerado.'}},
{n:148, q:'Según la Ley 39/2015, no formará parte del expediente administrativo...', o:{a:'La información que tenga carácter auxiliar o de apoyo.',b:'La información contenida en aplicaciones, ficheros y bases de datos informáticas.',c:'Los juicios de valor emitidos por las administraciones públicas, salvo que sean informes solicitados antes de la resolución.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 70.4 LPAC establece que no forman parte del expediente la información auxiliar, la contenida en aplicaciones informáticas y los juicios de valor que no sean informes formales.'}},
{n:149, q:'Según la Ley 39/2015, las personas designadas como órgano instructor serán responsables directos...', o:{a:'De la tramitación del procedimiento.',b:'Del cumplimiento de los plazos establecidos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 73 LPAC establece que los órganos instructores son responsables directos de la tramitación del procedimiento y del cumplimiento de los plazos.'}},
{n:150, q:'Según la Ley 39/2015, los trámites que deban ser cumplimentados por los interesados deberán realizarse, como regla general, en el plazo de...', o:{a:'20 días a partir del siguiente al de la notificación del acto.',b:'30 días a partir del siguiente al de la notificación del acto.',c:'15 días a partir del siguiente al de la notificación del acto.',d:'10 días a partir del siguiente al de la notificación del acto.'}, correct:'d', why:{d:'El art. 73.2 LPAC establece que los trámites que deben cumplimentar los interesados deben realizarse en el plazo de 10 días.'}},
{n:151, q:'Según la Ley 39/2015, en cualquier momento del procedimiento, cuando la administración considere que los actos de los interesados no reúnen los requisitos necesarios, lo pondrá en conocimiento de su autor...', o:{a:'Concediéndole un plazo de 15 días para cumplimentarlo.',b:'Concediéndole un plazo de 5 días para cumplimentarlo.',c:'Concediéndole un plazo de 10 días para cumplimentarlo.',d:'Concediéndole un plazo de 20 días para cumplimentarlo.'}, correct:'c', why:{c:'El art. 73.3 LPAC establece un plazo de 10 días para subsanar los actos que no reúnan los requisitos necesarios.'}},
{n:152, q:'Según la Ley 39/2015, con relación a las cuestiones incidentales, indique la respuesta correcta.', o:{a:'Ninguna de ellas suspende la tramitación del procedimiento.',b:'Solo la recusación suspende la tramitación del procedimiento.',c:'Solo la que se refiera a la nulidad de actuaciones suspende la tramitación.',d:'Solo el anuncio de interposición del recurso correspondiente suspende la tramitación.'}, correct:'b', why:{b:'El art. 77 LPAC establece que las cuestiones incidentales no suspenden la tramitación, salvo la recusación.'}},
{n:153, q:'Aquella fase del procedimiento administrativo que comprende las alegaciones, pruebas, informes, trámite de audiencia, información pública y propuesta de resolución, se denomina:', o:{a:'Fase de incoación.',b:'Fase de resolución.',c:'Fase de recopilación.',d:'Fase de instrucción.'}, correct:'d', why:{d:'La fase de instrucción comprende todas las actuaciones para determinar los hechos y preparar la resolución.'}},
{n:154, q:'Aquellos actos del procedimiento administrativo necesarios para la determinación, conocimiento y comprobación de los datos en virtud de los cuales deba pronunciarse la resolución, se denominan:', o:{a:'Actos de instrucción.',b:'Actos administrativos.',c:'Actos a instancia de parte.',d:'Actos de comprobación.'}, correct:'a', why:{a:'El art. 75 LPAC denomina actos de instrucción a los necesarios para la determinación, conocimiento y comprobación de los hechos.'}},
{n:155, q:'Según la Ley 39/2015...', o:{a:'Los actos de instrucción se realizarán de oficio y a través de medios electrónicos.',b:'Los actos de instrucción que requieran la intervención de los interesados habrán de practicarse de la forma más conveniente para ellos.',c:'El órgano instructor adoptará las medidas necesarias para lograr el pleno respeto a los principios de contradicción e igualdad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 75 LPAC establece las tres características de los actos de instrucción.'}},
{n:156, q:'Según la Ley 39/2015, los interesados podrán aducir alegaciones y aportar documentos u otros elementos de juicio...', o:{a:'En cualquier momento del procedimiento posterior al trámite de audiencia.',b:'En cualquier momento del procedimiento anterior al trámite de audiencia.',c:'En el periodo concedido al efecto como trámite de audiencia.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 76 LPAC establece que los interesados pueden aducir alegaciones en cualquier momento del procedimiento anterior al trámite de audiencia.'}},
{n:157, q:'Según la Ley 39/2015, los defectos de tramitación podrán ser alegados por los interesados...', o:{a:'En cualquier momento del procedimiento posterior al trámite de audiencia.',b:'En cualquier momento del procedimiento anterior al trámite de audiencia.',c:'En el periodo concedido al efecto como trámite de audiencia.',d:'En todo momento.'}, correct:'d', why:{d:'El art. 76 LPAC establece que los defectos de tramitación pueden ser alegados por los interesados en cualquier momento.'}},
{n:158, q:'Según la Ley 39/2015, la valoración de las pruebas se realizará de acuerdo con los criterios establecidos en...', o:{a:'La Ley de Enjuiciamiento Criminal.',b:'La Ley de Enjuiciamiento Civil.',c:'La Ley Reguladora de la Jurisdicción Contencioso Administrativa.',d:'La Ley Orgánica del Poder Judicial.'}, correct:'b', why:{b:'El art. 77.6 LPAC establece que la valoración de las pruebas se realiza conforme a los criterios de la Ley de Enjuiciamiento Civil.'}},
{n:159, q:'La práctica de pruebas en el procedimiento administrativo se acordará:', o:{a:'Por los interesados.',b:'Por el instructor.',c:'Por el órgano que debe resolver.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 77 LPAC establece que la práctica de las pruebas se acuerda por el instructor del procedimiento.'}},
{n:160, q:'Según la Ley 39/2015, el instructor del procedimiento podrá abrir un período de prueba por un plazo...', o:{a:'No superior a 30 días ni inferior a 10 días.',b:'De 30 días.',c:'De 10 días.',d:'No superior a 20 días ni inferior a 10 días.'}, correct:'a', why:{a:'El art. 77 LPAC establece que el período ordinario de prueba no puede ser superior a 30 días ni inferior a 10 días.'}},
{n:161, q:'Según la Ley 39/2015, cuando lo considere necesario, el instructor puede abrir un período de prueba extraordinario por un plazo no superior a...', o:{a:'10 días.',b:'15 días.',c:'20 días.',d:'30 días.'}, correct:'a', why:{a:'El art. 77.2 LPAC establece que el período extraordinario de prueba no podrá exceder de 10 días.'}},
{n:162, q:'El instructor de un procedimiento administrativo acordará la práctica de pruebas:', o:{a:'Cuando lo estime conveniente.',b:'Cuando no tenga por ciertos los hechos alegados por los interesados.',c:'Cuando la naturaleza del procedimiento lo exija.',d:'Las respuestas b y c son correctas.'}, correct:'d', why:{d:'El art. 77.1 LPAC establece que la práctica de pruebas se acuerda cuando no tenga por ciertos los hechos alegados o la naturaleza del procedimiento lo exija.'}},
{n:163, q:'En el procedimiento administrativo, el instructor solo puede rechazar las pruebas propuestas por los interesados, cuando...', o:{a:'Sean manifiestamente improcedentes.',b:'Sean innecesarias.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 77.3 LPAC establece que el instructor solo puede rechazar pruebas cuando sean manifiestamente improcedentes o innecesarias.'}},
{n:164, q:'En el procedimiento administrativo, el instructor solo puede rechazar las pruebas propuestas por los interesados...', o:{a:'Previa audiencia de los interesados.',b:'Mediante resolución motivada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 77.3 LPAC establece que el rechazo de pruebas debe realizarse mediante resolución motivada.'}},
{n:165, q:'En el procedimiento administrativo:', o:{a:'Solo se admiten como medios de prueba aquellos que de manera tasada determina la Ley 39/2015.',b:'No se puede practicar prueba alguna antes del trámite de audiencia.',c:'Se admite cualquier medio de prueba válido en Derecho.',d:'Se admite cualquier medio de prueba válido en Derecho, excepto la prueba preconstituida.'}, correct:'c', why:{c:'El art. 77.1 LPAC establece que en el procedimiento administrativo se admite cualquier medio de prueba válido en Derecho.'}},
{n:166, q:'Según la Ley 39/2015...', o:{a:'Los informes no serán facultativos ni vinculantes.',b:'Los informes serán emitidos en el plazo de 10 días, salvo que una disposición o el cumplimiento del resto de plazos permita o exija otro mayor o menor.',c:'De no emitirse el informe en plazo, podrán proseguirse las actuaciones salvo cuando sea un informe vinculante.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 79 LPAC establece que los informes se emiten en el plazo de 10 días, salvo disposición o plazo que establezca uno distinto.'}},
{n:167, q:'En el curso de un procedimiento administrativo se solicita un informe a una Administración distinta. Teniendo en cuenta lo anterior, indique la respuesta correcta.', o:{a:'Hasta que no se reciba dicho informe el procedimiento queda suspendido.',b:'Si transcurre el plazo previsto sin que el informe hubiera sido emitido, se podrán proseguir las actuaciones.',c:'Cuando el informe sea emitido fuera de plazo no podrá ser tenido en cuenta al adoptar la resolución.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 80 LPAC establece que si el informe no se emite en plazo, las actuaciones pueden proseguirse.'}},
{n:168, q:'Con respecto al trámite de audiencia en el procedimiento administrativo, previsto en el artículo 82 de la Ley 39/2015, indique la respuesta incorrecta.', o:{a:'Se lleva a cabo poniendo de manifiesto a los interesados o sus representantes el procedimiento, teniendo en cuenta las limitaciones previstas en la Ley 19/2013.',b:'Se lleva a cabo una vez instruido el procedimiento, e inmediatamente antes de redactar la propuesta de resolución.',c:'Los interesados disponen de un plazo entre 10 y 15 días para alegar y presentar los documentos y justificaciones que estimen pertinentes.',d:'Se tendrá por realizado el trámite cuando las actuaciones de los interesados obrantes en el expediente hayan sido declaradas nulas de pleno derecho por sentencia judicial firme.'}, correct:'a', why:{a:'La opción a) es incorrecta: la referencia a las limitaciones de la Ley 19/2013 en este contexto no es exacta.'}},
{n:169, q:'Según la Ley 39/2015, se podrá prescindir del trámite de audiencia...', o:{a:'En los procedimientos iniciados a instancia de parte.',b:'Cuando en el procedimiento no consten, ni sean tenidos en cuenta en la resolución, otros hechos ni otras alegaciones y pruebas que los aducidos por el interesado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 82.4 LPAC establece que se puede prescindir del trámite de audiencia cuando no consten otros hechos, alegaciones o pruebas distintos de los aducidos por el interesado.'}},
{n:170, q:'Según la Ley 39/2015, antes de dictar resolución, el órgano competente para resolver podrá decidir mediante acuerdo motivado...', o:{a:'La concesión de un nuevo trámite de audiencia a los interesados que no hayan comparecido.',b:'La emisión de una declaración responsable de los interesados.',c:'La realización de las actuaciones complementarias indispensables para resolver el procedimiento.',d:'Podrá decidir todo lo reflejado en las respuestas anteriores.'}, correct:'c', why:{c:'El art. 87 LPAC establece que el órgano competente puede acordar la realización de actuaciones complementarias indispensables para resolver.'}},
{n:171, q:'Según la Ley 39/2015, con relación a la realización de actuaciones complementarias, indique la respuesta correcta.', o:{a:'Deben notificarse a los interesados y concederles un plazo de 10 días para formular alegaciones.',b:'Deberán practicarse en un plazo no superior a 10 días.',c:'El plazo para resolver el procedimiento quedará suspendido hasta la terminación de las actuaciones complementarias.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 87 LPAC establece que el plazo para resolver queda suspendido mientras se realizan las actuaciones complementarias.'}},
{n:172, q:'Según la Ley 39/2015, debe decidir todas las cuestiones planteadas por los interesados y aquellas otras derivadas del mismo. Nos estamos refiriendo a...', o:{a:'La propuesta de resolución.',b:'La resolución.',c:'La recusación.',d:'El recurso de alzada.'}, correct:'b', why:{b:'El art. 88 LPAC establece que la resolución debe decidir todas las cuestiones planteadas por los interesados y las derivadas del procedimiento.'}},
{n:173, q:'De conformidad con la Ley 39/2015, la resolución será congruente con las peticiones formuladas por el interesado, sin que en ningún caso pueda agravar su situación inicial. Esta afirmación es aplicable a los procedimientos...', o:{a:'De naturaleza sancionadora.',b:'Tramitados de oficio.',c:'Tramitados a solicitud del interesado.',d:'Iniciados como consecuencia de denuncia.'}, correct:'c', why:{c:'El principio de congruencia y no agravación se aplica a los procedimientos tramitados a solicitud del interesado.'}},
{n:174, q:'De conformidad con la Ley 39/2015, las resoluciones deberán contener...', o:{a:'La decisión, que será motivada en los casos previstos en el artículo 35 de esta ley.',b:'Los recursos que contra la misma procedan.',c:'El órgano ante quien hubieran de presentarse los recursos y el plazo para interponerlos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 88.2 LPAC establece que la resolución debe contener la decisión motivada, los recursos procedentes, el órgano ante el que interponer y el plazo.'}},
{n:175, q:'En un procedimiento administrativo, la Administración podrá abstenerse de resolver:', o:{a:'Cuando no obren en el procedimiento otros actos ni otras alegaciones que las aducidas por el interesado.',b:'En los casos previstos para la aplicación del silencio administrativo.',c:'En caso de insuficiencia de preceptos legales aplicables al caso.',d:'En ningún caso.'}, correct:'d', why:{d:'El art. 21 LPAC establece la obligación incondicional de resolver; la administración no puede abstenerse en ningún caso.'}},
{n:176, q:'De conformidad con la Ley 39/2015...', o:{a:'La resolución del procedimiento se dictará electrónicamente.',b:'La resolución del procedimiento garantizará la identidad del órgano competente.',c:'La resolución garantizará la autenticidad e integridad del documento mediante los instrumentos previstos en la ley.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 88 LPAC establece que la resolución se dicta electrónicamente, garantizando la identidad del órgano competente y la autenticidad e integridad del documento.'}},
{n:177, q:'Según la Ley 39/2015 pone fin al procedimiento...', o:{a:'La caducidad.',b:'La prescripción.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 84 LPAC establece como formas de terminación: la resolución, el desistimiento, la renuncia, la imposibilidad sobrevenida y la caducidad.'}},
{n:178, q:'La renuncia en un procedimiento administrativo, solo se admite:', o:{a:'Cuando no esté prohibida por el ordenamiento jurídico.',b:'Cuando los procedimientos finalicen por pacto o convenio.',c:'Cuando exista la imposibilidad de continuarlo por causas sobrevenidas.',d:'En todos los casos citados en las respuestas anteriores.'}, correct:'a', why:{a:'El art. 94 LPAC establece que la renuncia solo es posible cuando no está prohibida por el ordenamiento jurídico.'}},
{n:179, q:'Según la Ley 39/2015 pone fin al procedimiento...', o:{a:'La resolución.',b:'El desistimiento.',c:'La renuncia al derecho en que se funde la solicitud.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 84 LPAC enumera la resolución, el desistimiento, la renuncia y la imposibilidad sobrevenida como formas de terminación.'}},
{n:180, q:'Según la Ley 39/2015, con respecto al desistimiento, indique la respuesta correcta...', o:{a:'Si el escrito de iniciación se hubiera formulado por dos o más interesados, el desistimiento afectará a todos ellos.',b:'Podrá hacerse por cualquier medio que permita su constancia, siempre que incorpore las firmas que correspondan.',c:'La administración lo aceptará de plano y declarará concluso el procedimiento, salvo que terceros interesados instasen su continuación en el plazo de 15 días.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 93 LPAC establece que el desistimiento puede hacerse por cualquier medio que permita su constancia, incorporando las firmas necesarias.'}},
{n:181, q:'Según la Ley 39/2015, con respecto a la renuncia de derechos, indique la respuesta correcta...', o:{a:'Si el escrito de iniciación se hubiera formulado por dos o más interesados, la renuncia solo afectará a aquellos a quienes la hubiesen formulado.',b:'Podrá hacerse por cualquier medio que permita su constancia.',c:'La administración la aceptará de plano y declarará concluso el procedimiento, salvo que terceros interesados instasen su continuación en el plazo de 10 días.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 94 LPAC establece que la renuncia solo afecta al o a los interesados que la hayan formulado.'}},
{n:182, q:'La renuncia de derechos en un procedimiento administrativo, solo se admite:', o:{a:'Cuando no esté prohibida por el ordenamiento jurídico.',b:'En los procedimientos que finalicen por pacto o convenio.',c:'Cuando exista la imposibilidad de continuarlo por causas sobrevenidas.',d:'En todos los casos citados en las respuestas anteriores.'}, correct:'a', why:{a:'El art. 94 LPAC establece que la renuncia de derechos solo es admisible cuando no esté prohibida por el ordenamiento jurídico.'}},
{n:183, q:'De conformidad con la Ley 39/2015, en los procedimientos iniciados a solicitud del interesado, cuando se produzca su paralización por causa imputable al mismo, la administración le advertirá que se producirá la caducidad transcurridos...', o:{a:'6 meses.',b:'3 meses.',c:'20 días.',d:'10 días.'}, correct:'b', why:{b:'El art. 95 LPAC establece que cuando el procedimiento está paralizado por causa imputable al interesado, la administración le advertirá de la caducidad transcurridos 3 meses.'}},
{n:184, q:'De conformidad con la Ley 39/2015, después que la administración advierta sobre la paralización y transcurrido el plazo sin actividad, la administración...', o:{a:'Acordará el archivo de actuaciones.',b:'Notificará al interesado el archivo de actuaciones, con expresión de los recursos pertinentes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 95 LPAC establece que la administración acordará el archivo de actuaciones y lo notificará con expresión de los recursos pertinentes.'}},
{n:185, q:'De conformidad con la Ley 39/2015, no podrá acordarse la caducidad por la simple inactividad del interesado en la cumplimentación de trámites...', o:{a:'Cuando estos no sean indispensables para dictar resolución.',b:'Cuando dichos trámites pudieran ser subsanados en vía contencioso administrativa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 95.2 LPAC establece que no procede la caducidad por inactividad cuando los trámites no sean indispensables para dictar resolución.'}},
{n:186, q:'De conformidad con la Ley 39/2015...', o:{a:'La caducidad producirá por sí sola la prescripción de acciones del particular.',b:'La caducidad producirá por sí sola la prescripción de acciones de la administración.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 95.3 LPAC establece que la caducidad no produce por sí sola la prescripción de las acciones del particular ni de la administración.'}},
{n:187, q:'De conformidad con la Ley 39/2015, podrá no ser aplicable la caducidad...', o:{a:'En el supuesto de que la cuestión suscitada afecte al interés general.',b:'En el supuesto de que la cuestión suscitada fuere conveniente sustanciarla para su definición y esclarecimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 95.4 LPAC establece que la caducidad puede no aplicarse cuando la cuestión afecte al interés general o sea conveniente sustanciarla para su definición.'}},
{n:188, q:'La terminación convencional en un procedimiento administrativo:', o:{a:'Puede tener la consideración de acto finalizador del procedimiento.',b:'No puede tener la consideración de acto finalizador del procedimiento.',c:'Solo se considera acto finalizador cuando así lo disponga una ley.',d:'Se considera acto finalizador cuando así lo disponga una ley y no se perjudiquen derechos de terceros.'}, correct:'a', why:{a:'El art. 86 LPAC establece que la terminación convencional mediante acuerdo, pacto o convenio puede tener la consideración de acto finalizador del procedimiento.'}},
{n:189, q:'De conformidad con la Ley 39/2015, las administraciones públicas podrán acordar la tramitación simplificada del procedimiento...', o:{a:'Cuando razones de interés público así lo aconsejen.',b:'Cuando la falta de complejidad del procedimiento así lo aconseje.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 96 LPAC establece que la tramitación simplificada puede acordarse por razones de interés público o cuando la falta de complejidad lo permita.'}},
{n:190, q:'De conformidad con la Ley 39/2015, con respecto a la tramitación simplificada del procedimiento, indique la respuesta que no es correcta.', o:{a:'El acuerdo de tramitación simplificada debe notificarse a los interesados.',b:'Cuando alguno de los interesados se oponga a la tramitación simplificada, la administración debe seguir la tramitación ordinaria.',c:'La tramitación simplificada siempre será adoptada de oficio, sin que pueda ser solicitada por los interesados.',d:'Los procedimientos tramitados de manera simplificada deberán ser resueltos en el plazo de 30 días.'}, correct:'c', why:{c:'La opción c) es incorrecta: la tramitación simplificada puede adoptarse de oficio pero también puede ser solicitada por los interesados.'}},
{n:191, q:'De conformidad con la Ley 39/2015,', o:{a:'Las administraciones públicas no iniciarán ninguna actuación material de ejecución de resoluciones que limiten derechos sin previa resolución que sirva de fundamento jurídico.',b:'El órgano que ordene un acto de ejecución material estará obligado a notificar al particular interesado la resolución que autorice la actuación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 97 LPAC establece que las AAPP no pueden iniciar actuaciones materiales de ejecución que limiten derechos sin previa resolución que las fundamente.'}},
{n:192, q:'Los actos de las administraciones públicas sujetos al derecho administrativo serán inmediatamente ejecutivos, salvo que...', o:{a:'Se produzca la suspensión de la ejecución del acto.',b:'El interesado formule el recurso procedente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 98 LPAC establece que los actos son inmediatamente ejecutivos salvo que se haya acordado su suspensión.'}},
{n:193, q:'Los actos de las administraciones públicas sujetos al derecho administrativo serán inmediatamente ejecutivos, salvo que...', o:{a:'Una disposición establezca lo contrario.',b:'Se necesite aprobación o autorización superior.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 98 LPAC establece que los actos son inmediatamente ejecutivos salvo que una disposición establezca lo contrario o necesiten aprobación o autorización superior.'}},
{n:194, q:'Son medios que pueden utilizar las Administraciones públicas en la ejecución forzosa:', o:{a:'La ejecución dineraria y patrimonial.',b:'El apremio sobre el patrimonio.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 100 LPAC establece como medios de ejecución forzosa: apremio sobre el patrimonio, ejecución subsidiaria, multa coercitiva y compulsión sobre las personas.'}},
{n:195, q:'Son medios que pueden utilizar las Administraciones públicas en la ejecución forzosa:', o:{a:'La multa compulsiva.',b:'La ejecución subsidiaria.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 100 LPAC establece que la ejecución subsidiaria es un medio de ejecución forzosa.'}},
{n:196, q:'Son medios que pueden utilizar las Administraciones públicas en la ejecución forzosa:', o:{a:'La multa compulsiva.',b:'La coerción sobre las personas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El art. 100 LPAC establece la compulsión sobre las personas y la multa coercitiva; la formulación de "multa compulsiva" y "coerción" no es exacta.'}},
{n:197, q:'Son medios que pueden utilizar las Administraciones públicas en la ejecución forzosa:', o:{a:'La multa coercitiva.',b:'La compulsión sobre las personas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 100 LPAC establece que la multa coercitiva y la compulsión sobre las personas son medios de ejecución forzosa.'}},
{n:198, q:'Son medios que pueden utilizar las Administraciones públicas en la ejecución forzosa:', o:{a:'El apremio sobre el patrimonio y la ejecución subsidiaria.',b:'La multa coercitiva.',c:'La compulsión sobre las personas.',d:'Todos los citados en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 100 LPAC enumera como medios de ejecución forzosa: apremio sobre el patrimonio, ejecución subsidiaria, multa coercitiva y compulsión sobre las personas.'}},
{n:199, q:'Según la Ley 39/2015, si fuese necesario entrar en el domicilio del afectado, las administraciones públicas...', o:{a:'Deben obtener el consentimiento de su titular.',b:'Deben obtener la oportuna autorización judicial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 100.3 LPAC establece que si la ejecución forzosa exige entrada en el domicilio del afectado, es necesario su consentimiento o autorización judicial.'}},
{n:200, q:'Cuando se trata de actos no personalísimos que pueden ser realizados por un sujeto distinto al obligado, la Administración utilizará, como medio de ejecución forzosa:', o:{a:'El apremio sobre el patrimonio.',b:'La ejecución subsidiaria.',c:'La multa coercitiva.',d:'La compulsión sobre las personas.'}, correct:'b', why:{b:'El art. 102 LPAC establece que la ejecución subsidiaria procede para los actos no personalísimos que pueden ejecutar sujetos distintos al obligado.'}},
{n:201, q:'La multa coercitiva:', o:{a:'Solo podrá utilizarse cuando lo autoricen las leyes.',b:'Solo podrá utilizarse cuando el administrado no sea insolvente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 103 LPAC establece que la multa coercitiva solo puede utilizarse cuando esté expresamente autorizada por las leyes.'}},
{n:202, q:'La multa coercitiva se emplea:', o:{a:'En actos no personalísimos, excepto cuando exista compulsión directa sobre la persona del obligado.',b:'En actos personalísimos, en los que no procede compulsión directa sobre la persona obligada.',c:'En actos no personalísimos, en los que no puede imponerse la ejecución subsidiaria.',d:'En actos personalísimos, en los que no puede imponerse la ejecución subsidiaria.'}, correct:'b', why:{b:'El art. 103 LPAC establece que la multa coercitiva se emplea en actos personalísimos en los que no cabe la compulsión directa.'}},
{n:203, q:'La multa coercitiva se emplea:', o:{a:'En actos personalísimos, en los que no proceda compulsión directa sobre la persona del obligado.',b:'En aquellos actos en que, aun procediendo la compulsión, ésta no se estime conveniente.',c:'En aquellos actos cuya ejecución pueda encargar el obligado a otra persona.',d:'En todos los actos citados en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 103 LPAC establece que la multa coercitiva se aplica en los tres supuestos.'}},
{n:204, q:'Aquel medio de ejecución forzosa en el que la Administración impone multas sucesivas, periódicas y progresivas, hasta que el administrado cumple la obligación, se denomina:', o:{a:'Apremio sobre el patrimonio.',b:'Ejecución subsidiaria.',c:'Multa coercitiva.',d:'Compulsión sobre las personas.'}, correct:'c', why:{c:'La multa coercitiva consiste en la imposición de multas sucesivas, periódicas y progresivas para compeler al cumplimiento.'}},
{n:205, q:'Aquel medio de ejecución forzosa que se aplica a actos administrativos que impongan una obligación personalísima de no hacer o soportar, se denomina:', o:{a:'Apremio sobre el patrimonio.',b:'Ejecución subsidiaria.',c:'Multa coercitiva.',d:'Compulsión sobre las personas.'}, correct:'d', why:{d:'La compulsión sobre las personas es el medio de ejecución para obligaciones personalísimas de no hacer o soportar.'}},
{n:206, q:'De conformidad con la Ley 39/2015, las Administraciones Públicas declararán de oficio la nulidad de los actos administrativos, en los supuestos de nulidad de pleno derecho...', o:{a:'Cuando hayan puesto fin a la vía administrativa o exista imposibilidad de continuar el procedimiento.',b:'En cualquier momento, previo dictamen del Consejo de Estado u órgano consultivo de la CC.AA.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 106 LPAC establece que las AAPP pueden declarar de oficio la nulidad en cualquier momento, previo dictamen del Consejo de Estado u órgano consultivo autonómico.'}},
{n:207, q:'De conformidad con la Ley 39/2015, las Administraciones Públicas declararán de oficio la nulidad de las disposiciones administrativas, en los supuestos de nulidad de pleno derecho...', o:{a:'Cuando hayan puesto fin a la vía administrativa o exista imposibilidad de continuar el procedimiento.',b:'En cualquier momento, previo dictamen del Consejo de Estado u órgano consultivo de la CC.AA.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 106.2 LPAC establece que las disposiciones administrativas nulas pueden ser declaradas de oficio en cualquier momento, previo dictamen del Consejo de Estado u órgano consultivo autonómico.'}},
{n:208, q:'De conformidad con la Ley 39/2015, el órgano administrativo competente para la revisión de un acto podrá acordar motivadamente la inadmisión a trámite de las solicitudes, sin necesidad de dictamen del Consejo de Estado, cuando...', o:{a:'No se basen en alguna de las causas de nulidad del artículo 47.1 de esta ley.',b:'Se hubieren desestimado en cuanto al fondo otras solicitudes sustancialmente iguales.',c:'Carezcan manifiestamente de fundamento.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 106.5 LPAC establece que la inadmisión sin dictamen procede en los tres supuestos.'}},
{n:209, q:'De conformidad con la Ley 39/2015, cuando el proceso de revisión de actos en vía administrativa se hubiera iniciado a solicitud del interesado y transcurriere el plazo de 6 meses sin que se haya dictado resolución...', o:{a:'Se entenderá prescrito.',b:'Se entenderá que ha caducado.',c:'El interesado debe entender desestimada su pretensión por silencio administrativo.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 106.6 LPAC establece que si transcurren 6 meses sin resolución del procedimiento de revisión iniciado a instancia de parte, se producirá la caducidad.'}},
{n:210, q:'De conformidad con la Ley 39/2015, cuando la administración pretenda revisar actos anulables que sean favorables para los interesados...', o:{a:'Podrá impugnarlos ante el Orden Contencioso Administrativo, previa declaración de lesividad para el interés público.',b:'Podrá proceder a la revisión de oficio, previo dictamen favorable del Consejo de Estado u Órgano Consultivo de la CC.AA.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 107 LPAC establece que para revisar actos anulables favorables, la administración debe declararlos lesivos e impugnarlos ante la jurisdicción contencioso-administrativa.'}},
{n:211, q:'De conformidad con la Ley 39/2015, la declaración de lesividad...', o:{a:'No podrá adoptarse una vez transcurridos cuatro años desde que se dictó el acto administrativo.',b:'Exigirá la previa audiencia de cuantos aparezcan como interesados en el procedimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 107 LPAC establece que la declaración de lesividad no puede adoptarse transcurridos 4 años desde el acto y exige la previa audiencia de los interesados.'}},
{n:212, q:'De conformidad con la Ley 39/2015, la Administración podrá rectificar en cualquier momento:', o:{a:'Los actos de contenido discrecional.',b:'Los errores de derecho existentes en sus actos.',c:'Los errores aritméticos existentes en sus actos.',d:'Los actos de contenido reglado.'}, correct:'c', why:{c:'El art. 109 LPAC establece que la administración puede rectificar en cualquier momento los errores materiales, de hecho o aritméticos existentes en sus actos.'}},
{n:213, q:'De conformidad con la Ley 39/2015, la Administración podrá rectificar en cualquier momento:', o:{a:'Los errores materiales existentes en sus actos.',b:'Los errores de hecho existentes en sus actos.',c:'Los errores aritméticos existentes en sus actos.',d:'Todos los errores citados en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 109 LPAC establece que la administración puede rectificar errores materiales, de hecho o aritméticos en sus actos en cualquier momento.'}},
{n:214, q:'De conformidad con la Ley 39/2015, la Administración podrá rectificar los errores materiales, de hecho o aritméticos existentes en sus actos:', o:{a:'Antes de dictar la resolución.',b:'Antes de dictar la propuesta de resolución.',c:'Antes del trámite de audiencia.',d:'En cualquier momento.'}, correct:'d', why:{d:'El art. 109.2 LPAC establece que la rectificación de errores materiales, de hecho o aritméticos puede realizarse en cualquier momento.'}},
{n:215, q:'De conformidad con la Ley 39/2015, la Administración podrá revocar sus actos de gravamen o desfavorables...', o:{a:'Siempre que tal revocación no constituya dispensa o exención no permitida por las leyes.',b:'Siempre que haya transcurrido el plazo de prescripción.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 109.1 LPAC establece que la administración puede revocar en cualquier momento sus actos de gravamen, siempre que ello no constituya dispensa o exención no permitida.'}},
{n:216, q:'De conformidad con la Ley 39/2015, la Administración podrá revocar sus actos de gravamen o desfavorables...', o:{a:'Siempre que ello no sea contrario al principio de igualdad.',b:'Siempre que ello no sea contrario al interés público.',c:'Siempre que ello no sea contrario al ordenamiento jurídico.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 109.1 LPAC establece que la revocación no puede ser contraria al principio de igualdad, al interés público ni al ordenamiento jurídico.'}},
{n:217, q:'La revisión de actos en vía administrativa no puede llevarse a cabo...', o:{a:'Durante los estados de alarma, excepción o sitio.',b:'Cuando por el tiempo transcurrido su ejercicio resulte contrario al derecho de los particulares.',c:'En aquellos actos que hayan sido objeto de delegación.',d:'En ninguno de los supuestos citados en las respuestas anteriores.'}, correct:'c', why:{c:'El art. 110 LPAC establece que la revisión no puede llevarse a cabo cuando su ejercicio resulte contrario a la equidad, la buena fe, el derecho de los particulares o las leyes.'}},
{n:218, q:'La revisión de actos en vía administrativa no puede llevarse a cabo...', o:{a:'Cuando por prescripción de acciones, su ejercicio resulte contrario a la equidad.',b:'Cuando por prescripción de acciones, su ejercicio resulte contrario a la buena fe.',c:'Cuando por prescripción de acciones, su ejercicio resulte contrario al derecho de los particulares o a las leyes.',d:'En ninguno de los supuestos citados en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 110 LPAC establece las causas que impiden la revisión; según el solucionario la respuesta es d.'}},
{n:219, q:'Una vez iniciado el procedimiento de revisión de oficio de un acto administrativo, el órgano competente para declarar su nulidad o lesividad:', o:{a:'Suspenderá la ejecución del acto cuando ésta pudiera causar perjuicios de imposible o difícil reparación.',b:'Podrá suspender la ejecución del acto cuando ésta pudiera causar perjuicios de imposible o difícil reparación.',c:'Podrá acordar medidas cautelares al margen del procedimiento, con informe favorable del Consejo de Estado.',d:'Las respuestas b y c son correctas.'}, correct:'b', why:{b:'El art. 108 LPAC establece que el órgano competente podrá (no deberá) suspender la ejecución cuando pueda causar perjuicios de imposible o difícil reparación.'}},
{n:220, q:'De conformidad con la Ley 39/2015, pueden interponerse recursos administrativos contra...', o:{a:'Las resoluciones, en todo caso.',b:'Los actos de trámite en determinados supuestos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 112 LPAC establece que los recursos pueden interponerse contra las resoluciones y contra los actos de trámite cualificados.'}},
{n:221, q:'De conformidad con la Ley 39/2015, pueden interponerse recursos administrativos contra los actos de trámite...', o:{a:'En ningún caso.',b:'En los procedimientos de naturaleza selectiva o de concurrencia competitiva.',c:'En cualquier caso.',d:'Cuando decidan directa o indirectamente el fondo del asunto.'}, correct:'d', why:{d:'El art. 112 LPAC establece que los recursos contra actos de trámite son admisibles cuando decidan directa o indirectamente el fondo del asunto.'}},
{n:222, q:'De conformidad con la Ley 39/2015, pueden interponerse recursos administrativos contra los actos de trámite...', o:{a:'Cuando éstos determinen la imposibilidad de continuar el procedimiento.',b:'Cuando los actos hayan sido dictados fuera de plazo.',c:'En los supuestos de actos dictados en sustitución de otros anteriores.',d:'En todos los casos anteriores.'}, correct:'a', why:{a:'El art. 112 LPAC establece que los recursos contra actos de trámite son admisibles cuando determinen la imposibilidad de continuar el procedimiento.'}},
{n:223, q:'De conformidad con la Ley 39/2015, pueden interponerse recursos administrativos contra los actos de trámite...', o:{a:'Cuando éstos produzcan indefensión.',b:'Cuando produzcan un perjuicio irreparable a los derechos e intereses legítimos de los interesados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 112 LPAC establece que los recursos contra actos de trámite son admisibles cuando produzcan indefensión o perjuicio irreparable.'}},
{n:224, q:'De conformidad con la Ley 39/2015, contra aquellos actos de trámite que no decidan el fondo del asunto ni causen indefensión ni perjuicio irreparable...', o:{a:'Puede interponerse recurso de alzada.',b:'Podrá alegarse por los interesados para su consideración en la resolución que ponga fin al procedimiento.',c:'Puede interponerse recurso potestativo de reposición.',d:'Procederá la declaración de lesividad como requisito previo.'}, correct:'b', why:{b:'El art. 112.2 LPAC establece que los actos de trámite no recurribles solo podrán ser alegados para su consideración en la resolución final.'}},
{n:225, q:'No cabe recurso alguno en vía administrativa...', o:{a:'Contra actos administrativos dictados por autoridades que carecen de superior jerárquico.',b:'Contra disposiciones administrativas de carácter general.',c:'Contra las resoluciones que determinen la imposibilidad de continuar el procedimiento por causas sobrevenidas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 112.3 LPAC establece que no cabe recurso en vía administrativa contra las disposiciones administrativas de carácter general.'}},
{n:226, q:'Los recursos contra un acto administrativo que se funden únicamente en la nulidad de alguna disposición administrativa de carácter general...', o:{a:'Serán objeto de declaración de lesividad con carácter previo.',b:'Podrán alegarse por los interesados para su consideración en la resolución final.',c:'Podrán interponerse directamente ante el órgano que dictó dicha disposición.',d:'Se pondrán de manifiesto a los interesados para que formulen alegaciones.'}, correct:'c', why:{c:'El art. 112.3 LPAC establece que los recursos contra actos basados en la nulidad de una disposición general pueden interponerse directamente ante el órgano que dictó dicha disposición.'}},
{n:227, q:'El recurso extraordinario de revisión se puede interponer contra actos firmes en vía administrativa:', o:{a:'Siempre y cuando se trate de resoluciones que no pongan fin a la vía administrativa.',b:'En caso de silencio administrativo, cuando se hubiere formulado la correspondiente declaración de lesividad.',c:'Solo cuando determinen la imposibilidad de continuar el procedimiento o puedan causar indefensión.',d:'Solo cuando concurra alguna circunstancia de las previstas en el artículo 125.1 de la Ley 39/2015.'}, correct:'d', why:{d:'El art. 125 LPAC establece que el recurso extraordinario de revisión solo puede interponerse cuando concurran las circunstancias tasadas en ese artículo.'}},
{n:228, q:'De conformidad con la Ley 39/2015, pone fin a la vía administrativa:', o:{a:'La resolución de un recurso contencioso-administrativo.',b:'La resolución de los recursos de alzada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 114 LPAC establece que ponen fin a la vía administrativa las resoluciones de los recursos de alzada.'}},
{n:229, q:'De conformidad con la Ley 39/2015, ponen fin a la vía administrativa:', o:{a:'Las resoluciones de los órganos administrativos que carezcan de superior jerárquico.',b:'Las resoluciones de los procedimientos de impugnación, reclamación, conciliación y mediación y arbitraje, sustitutivos de los recursos de alzada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 114 LPAC establece que ponen fin a la vía administrativa las resoluciones de órganos sin superior jerárquico y las resoluciones de los procedimientos sustitutivos de los recursos de alzada.'}},
{n:230, q:'De conformidad con la Ley 39/2015, ponen fin a la vía administrativa:', o:{a:'Los acuerdos, pactos, convenios o contratos que tengan la consideración de finalizadores del procedimiento.',b:'La resolución administrativa de los procedimientos de responsabilidad patrimonial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 114 LPAC establece que ponen fin a la vía administrativa los acuerdos y convenios finalizadores y las resoluciones de responsabilidad patrimonial.'}},
{n:231, q:'De conformidad con la Ley 39/2015, constituye causa de inadmisión de los recursos administrativos...', o:{a:'La incompetencia del órgano administrativo, cuando el órgano competente pertenezca a otra administración pública.',b:'La existencia de terceros interesados a los que se pueda causar perjuicios de imposible o difícil reparación.',c:'Que su ejercicio resulte contrario al interés público protegido por la ley.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 116 LPAC establece que la incompetencia del órgano cuando el competente pertenece a otra administración es causa de inadmisión.'}},
{n:232, q:'De conformidad con la Ley 39/2015, constituye causa de inadmisión de los recursos administrativos...', o:{a:'Que se hubiere interpuesto un recurso contencioso administrativo por la misma causa.',b:'La falta de legitimación del recurrente.',c:'No haber acreditado debidamente la representación del recurrente.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 116 LPAC establece que la falta de legitimación del recurrente es causa de inadmisión.'}},
{n:233, q:'De conformidad con la Ley 39/2015, constituye causa de inadmisión de los recursos administrativos...', o:{a:'Que el acto no sea susceptible de recurso.',b:'Que haya transcurrido el plazo para la interposición del recurso.',c:'Que el recurso carezca manifiestamente de fundamento.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 116 LPAC establece que son causas de inadmisión: que el acto no sea recurrible, que haya transcurrido el plazo y que el recurso carezca manifiestamente de fundamento.'}},
{n:234, q:'De conformidad con la Ley 39/2015, la interposición de cualquier recurso:', o:{a:'Suspenderá la ejecución del acto impugnado.',b:'No suspenderá la ejecución del acto impugnado.',c:'No suspenderá la ejecución del acto impugnado, excepto en los casos en que una disposición establezca lo contrario.',d:'Suspenderá la ejecución del acto impugnado, excepto cuando una disposición establezca lo contrario.'}, correct:'c', why:{c:'El art. 117 LPAC establece que la interposición de recursos no suspende la ejecución del acto impugnado, salvo disposición contraria.'}},
{n:235, q:'De conformidad con la Ley 39/2015, el órgano a quien competa resolver el recurso podrá suspender la ejecución del acto impugnado:', o:{a:'Cuando la ejecución pudiera causar perjuicios de imposible o difícil reparación.',b:'Cuando la impugnación se fundamente en alguna de las causas de nulidad de pleno derecho previstas en esta ley.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 117.2 LPAC establece que el órgano puede suspender la ejecución cuando cause perjuicios de imposible o difícil reparación o cuando se fundamente en nulidad de pleno derecho.'}},
{n:236, q:'El recurso de alzada puede interponerse:', o:{a:'Contra resoluciones que pongan fin a la vía administrativa.',b:'Contra actos de trámite que produzcan indefensión.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 121 LPAC establece que el recurso de alzada se interpone contra resoluciones que NO pongan fin a la vía administrativa. Según el solucionario la respuesta es a.'}},
{n:237, q:'El recurso de alzada puede interponerse:', o:{a:'Contra resoluciones que no pongan fin a la vía administrativa.',b:'Contra actos de trámite que determinen la imposibilidad de continuar el procedimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 121 LPAC establece que el recurso de alzada se interpone contra resoluciones que no pongan fin a la vía administrativa y contra actos de trámite cualificados.'}},
{n:238, q:'El recurso de alzada puede interponerse:', o:{a:'Ante el órgano que dictó el acto.',b:'Ante el órgano competente para resolverlo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 121.2 LPAC establece que el recurso de alzada puede interponerse ante el órgano que dictó el acto o ante el competente para resolverlo.'}},
{n:239, q:'Cuando el recurso de alzada se interponga ante el órgano que dictó el acto:', o:{a:'Este deberá remitirlo al órgano competente en el plazo de diez días.',b:'Este lo archivará sin más trámite.',c:'Este lo resolverá y dará cuenta de ello a su superior jerárquico.',d:'Este se abstendrá de intervenir y lo devolverá al interesado.'}, correct:'a', why:{a:'El art. 121.2 LPAC establece que cuando el recurso de alzada se interpone ante el órgano que dictó el acto, este debe remitirlo al competente en el plazo de 10 días.'}},
{n:240, q:'El plazo máximo para dictar y notificar la resolución de un recurso de alzada es de ...', o:{a:'Un mes.',b:'Tres meses.',c:'Un mes cuando el acto es expreso y tres meses cuando no lo es.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 122 LPAC establece que el plazo máximo para dictar y notificar la resolución del recurso de alzada es de 3 meses.'}},
{n:241, q:'El plazo de interposición de un recurso de alzada es de ...', o:{a:'Un mes cuando el acto es expreso.',b:'Tres meses cuando el acto es presunto.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 122 LPAC establece que el recurso de alzada debe interponerse en el plazo de un mes cuando el acto sea expreso, y en el de tres meses cuando sea presunto.'}},
{n:242, q:'De conformidad con la Ley 39/2015...', o:{a:'Las resoluciones que pongan fin a la vía administrativa podrán ser recurridas en alzada ante el mismo órgano.',b:'Contra la resolución de un recurso de alzada no cabrá ningún otro recurso administrativo, salvo el extraordinario de revisión en los casos establecidos en el artículo 125.1.',c:'Si el recurso de alzada se interpusiere ante el órgano que dictó el acto impugnado, éste deberá remitirlo al competente en el plazo de 5 días.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El art. 122.3 LPAC establece que contra la resolución del recurso de alzada no cabe ningún otro recurso administrativo, salvo el extraordinario de revisión.'}},
{n:243, q:'El recurso de reposición:', o:{a:'Se interpone contra aquellos actos que no ponen fin a la vía administrativa.',b:'Es potestativo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 123 LPAC establece que el recurso de reposición es potestativo y se interpone contra actos que pongan fin a la vía administrativa.'}},
{n:244, q:'De conformidad con la Ley 39/2015, contra aquellos actos que pongan fin a la vía administrativa podrá interponerse:', o:{a:'Recurso de alzada.',b:'Recurso potestativo de reposición.',c:'Recurso contencioso administrativo.',d:'Las respuestas b y c son correctas.'}, correct:'d', why:{d:'El art. 123 LPAC establece que contra los actos que ponen fin a la vía administrativa se puede interponer recurso potestativo de reposición o recurso contencioso-administrativo directamente.'}},
{n:245, q:'De conformidad con la Ley 39/2015, el plazo para la interposición del recurso de reposición...', o:{a:'Será de un mes cuando el acto sea expreso.',b:'Será de tres meses cuando el acto no fuere expreso.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 124.1 LPAC establece que el recurso de reposición debe interponerse en el plazo de un mes cuando el acto sea expreso.'}},
{n:246, q:'De conformidad con la Ley 39/2015, si el acto no fuera expreso, el interesado podrá interponer recurso de reposición...', o:{a:'En el plazo de tres meses, a partir del día siguiente a aquel en que se produzca el acto presunto.',b:'En cualquier momento a partir del día siguiente a aquel en que se produzca el acto presunto.',c:'En cualquier momento a partir del día siguiente a aquel en que de acuerdo con su normativa específica se produzca el acto presunto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 124.1 LPAC establece que cuando el acto no sea expreso, el recurso de reposición puede interponerse en cualquier momento a partir del día siguiente al que se produce el acto presunto.'}},
{n:247, q:'De conformidad con la Ley 39/2015...', o:{a:'El plazo máximo para dictar y notificar la resolución del recurso de reposición será de un mes.',b:'Contra la resolución de un recurso de reposición podrá interponerse de nuevo dicho recurso.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 124.3 LPAC establece que el plazo para dictar y notificar la resolución del recurso de reposición es de un mes.'}},
{n:248, q:'De conformidad con la Ley 39/2015, es causa que habilita para la interposición de un recurso extraordinario de revisión:', o:{a:'Que aparezcan documentos de valor esencial para la resolución del asunto que evidencien el error de la resolución recurrida.',b:'Que en la resolución recurrida hayan influido esencialmente documentos o testimonios declarados falsos por sentencia judicial firme, anterior o posterior a aquella resolución.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 125 LPAC establece como causas del recurso de revisión tanto la aparición de documentos esenciales posteriores como la influencia de documentos o testimonios declarados falsos.'}},
{n:249, q:'De conformidad con la Ley 39/2015, es causa que habilita para la interposición de un recurso extraordinario de revisión:', o:{a:'Que en la resolución recurrida hayan influido esencialmente documentos o testimonios declarados falsos por sentencia judicial firme, anteriores a aquella resolución.',b:'Que la resolución se hubiese dictado como consecuencia de prevaricación, cohecho, violencia, maquinación fraudulenta u otra conducta punible y así se haya declarado en virtud de sentencia judicial firme.',c:'Que los actos recurridos se hayan dictado con infracción de las normas aplicables, produciendo la indefensión de los interesados.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 125.1.c) LPAC establece como causa del recurso de revisión que la resolución se haya dictado como consecuencia de prevaricación u otra conducta punible declarada por sentencia firme.'}},
{n:250, q:'De conformidad con la Ley 39/2015, el recurso extraordinario de revisión podrá interponerse...', o:{a:'Contra actos firmes en vía administrativa.',b:'Contra actos que no pongan fin a la vía administrativa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 125 LPAC establece que el recurso extraordinario de revisión se interpone contra actos firmes en vía administrativa.'}},
{n:251, q:'El recurso extraordinario de revisión se interpone:', o:{a:'Ante el órgano administrativo que dictó el acto.',b:'Ante la sala de lo Contencioso del Tribunal Superior de Justicia de la Comunidad Autónoma.',c:'Ante el superior jerárquico del que dictó el acto.',d:'Ante el órgano administrativo que dictó el acto o ante su superior jerárquico.'}, correct:'a', why:{a:'El art. 125.2 LPAC establece que el recurso extraordinario de revisión se interpone ante el órgano administrativo que dictó el acto impugnado.'}},
{n:252, q:'El plazo para interponer un recurso extraordinario de revisión:', o:{a:'Es de cuatro años en los supuestos de error de hecho y de tres años en los demás casos.',b:'Es de tres años en los supuestos de error de hecho y de cuatro años en los demás casos.',c:'Es de cuatro años en los supuestos de error de hecho y de tres meses en los demás casos.',d:'Es de tres meses en los supuestos de error de hecho y de cuatro años en los demás casos.'}, correct:'c', why:{c:'El art. 125.1 LPAC establece que el recurso de revisión se interpone en el plazo de 4 años cuando se funda en error de hecho, y en el de 3 meses para las demás causas.'}},
{n:253, q:'Transcurrido el plazo de tres meses desde la interposición de un recurso de revisión, sin haberse dictado y notificado la resolución...', o:{a:'Se entenderá desestimado.',b:'Quedará expedita la vía contencioso administrativa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 126 LPAC establece que transcurridos 3 meses sin resolución del recurso de revisión, se entenderá desestimado y queda expedita la vía contencioso-administrativa.'}},
{n:254, q:'Los principios de la potestad sancionadora están recogidos en:', o:{a:'El capítulo II de la Ley 39/2015.',b:'El capítulo III de la Ley 39/2015.',c:'El capítulo II de la Ley 40/2015.',d:'El capítulo III de la Ley 40/2015.'}, correct:'d', why:{d:'Los principios de la potestad sancionadora de las AAPP están regulados en el Capítulo III del Título Preliminar de la Ley 40/2015.'}},
{n:255, q:'La potestad sancionadora de las administraciones públicas se ejercerá cuando haya sido reconocida en una norma con rango de ley. En este precepto se recoge el principio de...', o:{a:'Legalidad.',b:'Irretroactividad.',c:'Tipicidad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El principio de legalidad establece que la potestad sancionadora debe estar reconocida en norma con rango de ley.'}},
{n:256, q:'El ejercicio de la potestad sancionadora corresponde a los órganos administrativos que la tengan expresamente atribuida...', o:{a:'Por disposición de rango legal.',b:'Por disposición de rango reglamentario.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 63 Ley 40/2015 establece que la potestad sancionadora corresponde a los órganos que la tengan expresamente atribuida por disposición de rango legal o reglamentario.'}},
{n:257, q:'Según lo dispuesto en la Ley 40/2015, cuando se trate de entidades locales, la potestad sancionadora se ejercerá...', o:{a:'De la forma que reglamentariamente se determine.',b:'Sin perjuicio de lo dispuesto en el Título XI de la Ley 7/1985.',c:'Con arreglo a lo dispuesto en las respectivas ordenanzas locales.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 63.2 Ley 40/2015 establece que en el caso de las entidades locales, la potestad sancionadora se ejercerá sin perjuicio de lo dispuesto en el Título XI de la LRBRL.'}},
{n:258, q:'Según lo dispuesto en la Ley 40/2015, las infracciones administrativas se clasificarán por la ley en...', o:{a:'Leves, graves y muy graves.',b:'Leves y graves.',c:'Leves, menos graves y graves.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art. 64 Ley 40/2015 establece que las infracciones administrativas se clasifican por la ley en leves, graves y muy graves.'}},
{n:259, q:'Según lo dispuesto en la Ley 40/2015, cuando se trate de entidades locales, las disposiciones reglamentarias de desarrollo podrán introducir especificaciones o graduaciones al cuadro de infracciones o sanciones establecidas legalmente. La exposición anterior forma parte del principio de...', o:{a:'Legalidad.',b:'Irretroactividad.',c:'Tipicidad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El principio de tipicidad permite que las normas reglamentarias introduzcan especificaciones o graduaciones al cuadro de infracciones y sanciones sin crear nuevas categorías.'}},
{n:260, q:'Indique la respuesta correcta.', o:{a:'Las normas definidoras de infracciones y sanciones serán susceptibles de aplicación extensiva.',b:'Las normas definidoras de infracciones y sanciones serán susceptibles de aplicación analógica.',c:'Solo podrán ser sancionadas por hechos constitutivos de infracción administrativa las personas físicas y jurídicas que resulten responsables de los mismos a título de dolo o culpa.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 64 Ley 40/2015 establece que solo pueden ser sancionadas las personas físicas y jurídicas responsables de los hechos a título de dolo o culpa.'}},
{n:261, q:'Indique la respuesta correcta.', o:{a:'Cuando el cumplimiento de una obligación corresponda a varias personas conjuntamente, responderán solidariamente de las infracciones que se cometan.',b:'Cuando el cumplimiento de una obligación corresponda a varias personas conjuntamente, responderán solidariamente de las sanciones que se impongan.',c:'Cuando el cumplimiento de una obligación corresponda a varias personas, la sanción pecuniaria, si es posible, se individualizará en función del grado de participación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 64.3 Ley 40/2015 establece que el cumplimiento conjunto implica solidaridad en infracciones y sanciones, con posible individualización de la sanción pecuniaria.'}},
{n:262, q:'Según lo dispuesto en la Ley 40/2015,...', o:{a:'Las sanciones administrativas de naturaleza pecuniaria en ningún caso podrán implicar, directamente, privación de libertad.',b:'Las sanciones administrativas de naturaleza pecuniaria en ningún caso podrán implicar, subsidiariamente, privación de libertad.',c:'Las sanciones administrativas de naturaleza no pecuniaria en ningún caso podrán implicar, directamente, privación de libertad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 66 Ley 40/2015 establece que las sanciones pecuniarias no pueden implicar privación de libertad directa ni subsidiariamente, y las no pecuniarias tampoco directamente.'}},
{n:263, q:'Según lo dispuesto en la Ley 40/2015, la graduación de cualquier sanción administrativa tendrá en cuenta...', o:{a:'La naturaleza de los perjuicios causados.',b:'La causación de daños innecesarios para la comisión de la infracción.',c:'La de haber procedido el infractor, antes de conocer que el procedimiento se dirige contra él, a reparar el daño ocasionado.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 66 Ley 40/2015 establece que la graduación tiene en cuenta la naturaleza de los perjuicios, los daños innecesarios y la reparación voluntaria del daño.'}},
{n:264, q:'Según lo dispuesto en la Ley 40/2015, la graduación de cualquier sanción administrativa tendrá en cuenta...', o:{a:'La de haber procedido el infractor, antes de conocer la apertura del procedimiento, a confesar la infracción a las autoridades.',b:'El grado de culpabilidad.',c:'La personalidad del infractor.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 66 Ley 40/2015 establece que la graduación tiene en cuenta la confesión previa, el grado de culpabilidad y la personalidad del infractor.'}},
{n:265, q:'Según lo dispuesto en la Ley 40/2015, la graduación de cualquier sanción administrativa tendrá en cuenta...', o:{a:'La existencia de intencionalidad.',b:'La resolución recaída en el proceso penal, en su caso.',c:'La inexistencia de ánimo de lucro.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 66 Ley 40/2015 establece que la graduación tiene en cuenta la intencionalidad, las resoluciones penales y el ánimo de lucro.'}},
{n:266, q:'Según lo dispuesto en la Ley 40/2015, la graduación de cualquier sanción administrativa tendrá en cuenta...', o:{a:'La continuidad o persistencia de la conducta infractora.',b:'La reincidencia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 66 Ley 40/2015 establece que la graduación tiene en cuenta la continuidad o persistencia de la conducta infractora y la reincidencia.'}},
{n:267, q:'Según lo dispuesto en la Ley 40/2015, para aplicar la reincidencia en la graduación de los procedimientos sancionadores, es necesario...', o:{a:'Que se hayan cometido en el término de un año más de dos infracciones de la misma naturaleza.',b:'Que la infracción o infracciones sancionadas hayan sido declaradas por resolución judicial firme.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 66.1 Ley 40/2015 establece que para apreciar reincidencia es necesario que en el término de un año se hayan cometido más de dos infracciones de la misma naturaleza.'}},
{n:268, q:'Según lo dispuesto en la Ley 40/2015, en los procedimientos de naturaleza sancionadora, cuando lo justifique la debida adecuación entre la sanción y la gravedad del hecho, el órgano competente para resolver...', o:{a:'Podrá imponer la sanción superior en grado.',b:'Podrá imponer la sanción en su mitad superior.',c:'Podrá imponer la sanción en el grado inferior.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 67 Ley 40/2015 establece que el órgano puede imponer la sanción en el grado inferior cuando lo justifique la adecuación entre sanción y gravedad del hecho.'}},
{n:269, q:'Según lo dispuesto en la Ley 40/2015, la realización de una pluralidad de acciones u omisiones que infrinjan el mismo o semejantes preceptos administrativos, en ejecución de un plan preconcebido o aprovechando idéntica ocasión...', o:{a:'Será sancionable como infracción continuada.',b:'Será sancionable como infracción penal.',c:'Será sancionable de conformidad con lo dispuesto en el Título IV de esta Ley.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art. 65 Ley 40/2015 establece que la realización de múltiples acciones que infrinjan preceptos similares en ejecución de un plan preconcebido se sancionará como infracción continuada.'}},
{n:270, q:'Según lo dispuesto en la Ley 40/2015, las infracciones y sanciones prescribirán...', o:{a:'Según lo dispuesto en la Ley 39/2015.',b:'De conformidad con lo que determine la legislación penal aplicable.',c:'Según lo dispuesto en las leyes que las establezcan.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 30 Ley 40/2015 establece que las infracciones y sanciones administrativas prescribirán según lo dispuesto en las leyes que las establezcan.'}},
{n:271, q:'Según lo dispuesto en la Ley 40/2015, cuando las leyes que las establezcan no fijen plazos para ello, las infracciones administrativas prescribirán...', o:{a:'A los 6 años si se trata de infracciones muy graves.',b:'A los 2 años si se trata de infracciones graves.',c:'A los 3 meses cuando se trate de infracciones leves.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 30 Ley 40/2015 establece que a falta de plazos específicos, las infracciones muy graves prescriben a los 3 años, las graves al año y las leves a los 6 meses. Según el solucionario la respuesta es d.'}},
{n:272, q:'Según lo dispuesto en la Ley 40/2015, cuando las leyes no fijen plazos, las sanciones administrativas prescribirán...', o:{a:'A los 3 años si han sido impuestas por faltas muy graves.',b:'A los 2 años si han sido impuestas por faltas graves.',c:'Al año cuando hayan sido impuestas por infracciones leves.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 30 Ley 40/2015 establece que a falta de plazos específicos, las sanciones por infracciones muy graves prescriben a los 3 años, las graves a los 2 años y las leves al año.'}},
{n:273, q:'De conformidad con la Ley 40/2015, con relación a la prescripción de las infracciones administrativas, indique la respuesta que no es correcta.', o:{a:'El plazo de prescripción de las infracciones empezará a contarse desde el día en que la infracción se hubiere cometido.',b:'En el caso de infracciones continuadas o permanentes, el plazo comenzará a correr desde que finalizó la conducta infractora.',c:'La prescripción no se interrumpe con la iniciación de un procedimiento administrativo sancionador.',d:'El plazo de prescripción interrumpido se reiniciará si el expediente sancionador estuviera paralizado durante más de un mes por causa no imputable al presunto responsable.'}, correct:'c', why:{c:'La opción c) es incorrecta: la prescripción SÍ se interrumpe con la iniciación del procedimiento sancionador con conocimiento del interesado.'}},
{n:274, q:'De conformidad con la Ley 40/2015, con relación a la prescripción de las sanciones administrativas, indique la respuesta que no es correcta...', o:{a:'El plazo de prescripción de las sanciones empezará a contarse desde el día en que la infracción se hubiere cometido.',b:'Interrumpe la prescripción la iniciación, con conocimiento del interesado, del procedimiento de ejecución.',c:'El plazo de prescripción interrumpido se reiniciará si el procedimiento de ejecución estuviera paralizado durante más de un mes por causa no imputable al presunto responsable.',d:'En caso de desestimación presunta del recurso de alzada contra la resolución sancionadora, el plazo de prescripción comenzará a contarse desde el día siguiente a aquel en que finalice el plazo legalmente previsto para la resolución de dicho recurso.'}, correct:'a', why:{a:'La opción a) es incorrecta: el plazo de prescripción de las sanciones comienza desde que la resolución es ejecutable, no desde el día de la infracción.'}},
{n:275, q:'De conformidad con la Ley 40/2015, no podrán sancionarse los hechos que lo hayan sido penal o administrativamente, en los casos en los que se aprecie identidad...', o:{a:'Del Derecho aplicable, de los hechos y de la conducta castigada.',b:'Del sujeto, hechos y fundamento.',c:'Del sujeto, hechos y de la norma infringida.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El principio non bis in idem exige identidad de sujeto, hechos y fundamento para su aplicación.'}},
{n:276, q:'Según el artículo 53.1 de la Ley 39/2015, en los procedimientos de naturaleza sancionadora, los presuntos responsables tendrán derecho...', o:{a:'A ser notificados de los hechos que se les imputen.',b:'A ser notificados de las infracciones que los hechos que se les imputen pudieran constituir.',c:'A ser notificados de las sanciones que se les pudieran imponer en su caso.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 53.1 LPAC establece que en los procedimientos sancionadores los presuntos responsables tienen derecho a ser informados de los hechos, las infracciones y las sanciones posibles.'}},
{n:277, q:'Según el artículo 53.1 de la Ley 39/2015, en los procedimientos de naturaleza sancionadora, los presuntos responsables tendrán derecho...', o:{a:'A ser notificados de la identidad del instructor del procedimiento.',b:'A ser notificados de la identidad de la autoridad competente para imponer la sanción, en su caso, así como de la norma que le atribuya tal competencia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 53.1 LPAC establece que los presuntos responsables tienen derecho a conocer la identidad del instructor y de la autoridad sancionadora, así como la norma atributiva de competencia.'}},
{n:278, q:'Según el artículo 53.1 de la Ley 39/2015, en los procedimientos de naturaleza sancionadora, los presuntos responsables tendrán derecho...', o:{a:'A la presunción de no existencia de responsabilidad administrativa mientras no se demuestre lo contrario.',b:'A solicitar las correspondientes ayudas y subvenciones para el pago de la sanción pecuniaria.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 53.2 LPAC establece que en los procedimientos sancionadores los presuntos responsables tienen derecho a la presunción de inocencia.'}},
{n:279, q:'Según la Ley 39/2015, en los procedimientos de naturaleza sancionadora, las actuaciones previas...', o:{a:'No están permitidas.',b:'Estarán orientadas a determinar los hechos susceptibles de motivar la incoación del procedimiento.',c:'Estarán orientadas a determinar la identificación de la persona o personas que pudieran resultar responsables.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 55 LPAC establece que las actuaciones previas en procedimientos sancionadores se orientan a determinar los hechos e identificar a los presuntos responsables.'}},
{n:280, q:'Según la Ley 39/2015, con respecto a las formas de iniciación de los procedimientos de naturaleza sancionadora, indique la respuesta correcta.', o:{a:'Si el procedimiento se inicia por orden superior, la orden expresará la persona o personas presuntamente responsables, las conductas o hechos y el lugar y fecha.',b:'Si el procedimiento se inicia por petición razonada de otros órganos, la petición deberá especificar la persona o personas presuntamente responsables, las conductas o hechos, así como el lugar y fecha.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 60 LPAC establece los contenidos mínimos de la orden superior y la petición razonada que inician el procedimiento sancionador.'}},
{n:281, q:'Según la Ley 39/2015, los procedimientos de naturaleza sancionadora...', o:{a:'Se iniciarán siempre de oficio y por medio de denuncia.',b:'Establecerán la separación entre la fase instructora y la sancionadora, que se encomendarán a órganos distintos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 63.1 LPAC establece que los procedimientos sancionadores establecerán la separación entre la fase instructora y la sancionadora, encomendándose a órganos distintos.'}},
{n:282, q:'Según la Ley 39/2015, con respecto a los procedimientos de naturaleza sancionadora, indique cuál de las siguientes afirmaciones no es correcta.', o:{a:'Se considera que un órgano es competente para iniciar el procedimiento cuando así lo determinen las normas reguladoras del mismo.',b:'En ningún caso se podrá imponer una sanción sin que se haya tramitado el oportuno procedimiento.',c:'No se podrán iniciar nuevos procedimientos sancionadores por hechos tipificados como infracciones en cuya comisión el infractor persista de forma continuada, en tanto no haya recaído una primera resolución sancionadora ejecutiva.',d:'El acuerdo de incoación se comunicará al denunciante salvo que las normas del procedimiento exigieren obrar de otra forma.'}, correct:'d', why:{d:'La opción d) es incorrecta: el art. 64 LPAC no establece la obligación general de comunicar el acuerdo de incoación al denunciante.'}},
{n:283, q:'Según la Ley 39/2015, el acuerdo de incoación de un procedimiento sancionador debe contener, como mínimo:', o:{a:'Identificación de la persona o personas responsables.',b:'Identificación del denunciante o persona que le represente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 64 LPAC establece que el acuerdo de incoación debe contener, como mínimo, la identificación de la persona o personas presuntamente responsables.'}},
{n:284, q:'Según la Ley 39/2015, el acuerdo de incoación de un procedimiento sancionador debe contener, como mínimo:', o:{a:'Los hechos que motivan la incoación del procedimiento.',b:'La calificación de los hechos y las sanciones que pudieran corresponder.',c:'El órgano competente para la resolución del procedimiento y la norma que le atribuya tal competencia.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 64 LPAC establece que el acuerdo de incoación debe contener los hechos, la calificación, las posibles sanciones y el órgano competente con la norma habilitante.'}},
{n:285, q:'Según la Ley 39/2015, el acuerdo de incoación de un procedimiento sancionador debe contener, como mínimo:', o:{a:'El domicilio a efecto de notificaciones designado por la administración.',b:'La identificación del instructor, y en su caso del secretario del procedimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 64 LPAC establece que el acuerdo de incoación debe incluir la identificación del instructor y, en su caso, del secretario.'}},
{n:286, q:'Según la Ley 39/2015, el acuerdo de incoación de un procedimiento sancionador debe contener, como mínimo:', o:{a:'La advertencia de la posibilidad de que el presunto responsable pueda reconocer voluntariamente su responsabilidad.',b:'El régimen de recusación del instructor y del secretario del procedimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 64 LPAC establece que el acuerdo de incoación debe incluir la advertencia de reconocimiento voluntario de responsabilidad y el régimen de recusación.'}},
{n:287, q:'Según la Ley 39/2015, el acuerdo de incoación de un procedimiento sancionador debe contener, como mínimo:', o:{a:'Las medidas de carácter provisional acordadas para iniciar el procedimiento.',b:'La indicación del derecho que asiste al presunto responsable a personarse en el procedimiento asistido por abogado o representante.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El art. 64 LPAC establece que el acuerdo de incoación debe incluir las medidas provisionales y el derecho de asistencia letrada; según el solucionario la respuesta es d.'}},
{n:288, q:'Según la Ley 39/2015, el acuerdo de incoación de un procedimiento sancionador debe contener, como mínimo:', o:{a:'La indicación del derecho a formular alegaciones y a la audiencia en el procedimiento y de los plazos para su ejercicio.',b:'La indicación de que, en caso de no efectuar alegaciones en el plazo previsto, el acuerdo de iniciación podrá ser considerado propuesta de resolución.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 64 LPAC establece que el acuerdo de incoación debe incluir el derecho a formular alegaciones y la advertencia de que si no se formulan puede considerarse propuesta de resolución.'}},
{n:289, q:'Según la Ley 39/2015, en los procedimientos de carácter sancionador, los hechos declarados probados por resoluciones judiciales penales firmes...', o:{a:'Vinculan a la administración como a los interesados en los procedimientos sancionadores.',b:'Vinculan a la administración solo en aquellos extremos sobre los que el pronunciamiento judicial así lo disponga.',c:'No vinculan ni a la administración ni a los interesados, salvo norma legal contraria.',d:'Vincularán a las administraciones públicas respecto de los procedimientos sancionadores que se substancien.'}, correct:'d', why:{d:'El art. 77.4 LPAC establece que los hechos probados por resoluciones penales firmes vinculan a las administraciones públicas en los procedimientos sancionadores.'}},
{n:290, q:'Según la Ley 39/2015, con respecto a los procedimientos de naturaleza sancionadora, indique la afirmación que no es correcta.', o:{a:'Iniciado un procedimiento sancionador, si el infractor reconoce su responsabilidad, se podrá resolver éste con la imposición de la sanción en su grado mínimo.',b:'Cuando la sanción tenga únicamente carácter pecuniario, el pago voluntario por el presunto responsable, en cualquier momento anterior a la resolución, implicará la terminación del procedimiento.',c:'Cuando la sanción tenga únicamente carácter pecuniario, el órgano competente para resolver aplicará reducciones de, al menos, el 20 % del importe de la sanción propuesta.',d:'Las reducciones sobre el importe de la sanción deberán estar determinadas en la notificación de iniciación y su efectividad estará condicionada al desistimiento o renuncia de cualquier acción o recurso en vía administrativa.'}, correct:'a', why:{a:'La opción a) es incorrecta según el solucionario: el art. 85 LPAC no siempre permite resolver en grado mínimo por reconocimiento de responsabilidad.'}},
{n:291, q:'Según la Ley 39/2015, con respecto a los procedimientos de naturaleza sancionadora, indique la respuesta que no es correcta.', o:{a:'La propuesta de resolución deberá ser notificada a los interesados.',b:'La propuesta de resolución se formulará una vez concluida la ordenación del procedimiento.',c:'La propuesta de resolución deberá indicar la puesta de manifiesto del procedimiento y el plazo para formular alegaciones.',d:'En la propuesta de resolución se fijarán de forma motivada los hechos considerados probados y su exacta calificación jurídica.'}, correct:'b', why:{b:'La opción b) es incorrecta: la propuesta de resolución se formula una vez concluida la instrucción del procedimiento, no la ordenación.'}},
{n:292, q:'Según la Ley 39/2015, con respecto a la propuesta de resolución en los procedimientos de naturaleza sancionadora, indique la respuesta que no es correcta.', o:{a:'En ella se determinará la infracción que se entiende cometida.',b:'En ella se determinará la persona o personas responsables.',c:'En ella se determinará la sanción que se proponga.',d:'En ella se incluirá una valoración de las infracciones cometidas anteriormente por los presuntos responsables para determinar la cuantía exacta de las sanciones.'}, correct:'d', why:{d:'La opción d) es incorrecta: la propuesta de resolución no debe incluir valoración de infracciones anteriores del presunto responsable.'}},
{n:293, q:'Según la Ley 39/2015, en los procedimientos de naturaleza sancionadora, el órgano instructor resolverá la finalización del procedimiento con archivo de actuaciones, sin necesidad de propuesta de resolución...', o:{a:'Cuando debido a la escasa entidad de la infracción se considere que esta medida es la más adecuada.',b:'Cuando se constate la inexistencia de los hechos que pudieran constituir infracción.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 89 LPAC establece que el órgano instructor puede archivar sin propuesta de resolución cuando se constate la inexistencia de los hechos.'}},
{n:294, q:'Según la Ley 39/2015, en los procedimientos de naturaleza sancionadora, el órgano instructor resolverá la finalización del procedimiento con archivo de actuaciones sin propuesta de resolución...', o:{a:'Cuando los hechos no resulten acreditados.',b:'Cuando la resolución pudiera causar perjuicios de imposible o difícil reparación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 89 LPAC establece que el órgano instructor puede archivar sin propuesta cuando los hechos no resulten acreditados.'}},
{n:295, q:'Según la Ley 39/2015, en los procedimientos de naturaleza sancionadora, el órgano instructor resolverá la finalización del procedimiento con archivo de actuaciones sin propuesta de resolución...', o:{a:'Cuando los hechos probados no constituyan, de modo manifiesto, infracción administrativa.',b:'Cuando no exista o no se haya podido identificar a la persona o personas responsables, o bien aparezcan exentos de responsabilidad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El art. 89 LPAC establece el archivo en ambos supuestos; según el solucionario la respuesta es d.'}},
{n:296, q:'Según la Ley 39/2015, en los procedimientos de naturaleza sancionadora, el órgano instructor resolverá la finalización del procedimiento con archivo de actuaciones sin propuesta de resolución...', o:{a:'Cuando se concluya que ha prescrito la infracción.',b:'Cuando se concluya que ha caducado el procedimiento.',c:'Cuando la resolución pudiera causar perjuicios de imposible o difícil reparación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 89 LPAC establece que el archivo sin propuesta de resolución procede cuando se concluya que ha prescrito la infracción.'}},
{n:297, q:'Según la Ley 39/2015, en los procedimientos de naturaleza sancionadora, la resolución incluirá...', o:{a:'La valoración de las pruebas practicadas, en especial la de aquellas que hayan sido propuestas por el interesado.',b:'La fijación de los hechos y de la persona o personas responsables, si fueren conocidas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 90 LPAC establece que la resolución sancionadora incluirá la valoración de las pruebas y la fijación de los hechos y de los responsables conocidos.'}},
{n:298, q:'Según la Ley 39/2015, en los procedimientos de naturaleza sancionadora, la resolución incluirá...', o:{a:'La infracción o infracciones cometidas y la sanción o sanciones que se imponen.',b:'La declaración de no existencia de infracción o responsabilidad, en su caso.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 90 LPAC establece que la resolución sancionadora incluirá las infracciones y sanciones impuestas, o la declaración de no existencia de infracción o responsabilidad.'}},
{n:299, q:'Según la Ley 39/2015, en la resolución de los procedimientos de naturaleza sancionadora...', o:{a:'No se podrán aceptar hechos distintos a los determinados en el curso del procedimiento.',b:'Cuando el órgano competente considere que la infracción o la sanción revisten mayor gravedad que la determinada en la propuesta de resolución, se notificará al inculpado para que aporte alegaciones en el plazo de 15 días.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 90 LPAC establece que si el órgano aprecia mayor gravedad que la propuesta, debe notificarlo al inculpado para que formule alegaciones.'}},
{n:300, q:'Según la Ley 39/2015, la resolución de los procedimientos de naturaleza sancionadora...', o:{a:'Será ejecutiva cuando no quepa contra ella ningún recurso ordinario ni extraordinario en vía administrativa.',b:'Podrá adoptar las disposiciones cautelares precisas para garantizar su eficacia en tanto no sea ejecutiva.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 90.3 LPAC establece que la resolución sancionadora es ejecutiva cuando no quepa contra ella recurso ordinario ni extraordinario en vía administrativa.'}},
{n:301, q:'Según la Ley 39/2015, la resolución de los procedimientos de naturaleza sancionadora...', o:{a:'Se podrá suspender cautelarmente cuando sea ejecutiva, si el interesado manifiesta a la administración su intención de interponer recurso contencioso administrativo.',b:'Se podrá suspender cautelarmente cuando sea ejecutiva, si el interesado manifiesta a la administración su intención de cumplirla en el improrrogable plazo de veinte días.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 90.3 LPAC establece que la resolución sancionadora ejecutiva puede suspenderse cautelarmente si el interesado manifiesta su intención de interponer recurso contencioso-administrativo.'}},
{n:302, q:'Según la Ley 39/2015, en los procedimientos de naturaleza sancionadora...', o:{a:'Se podrá adoptar la tramitación simplificada del procedimiento cuando el órgano considere que existen elementos de juicio suficientes para calificar la infracción como leve.',b:'Si alguno de los interesados manifestara su oposición expresa a la tramitación simplificada del procedimiento, la administración debe seguir la tramitación ordinaria.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 96 LPAC establece que cuando algún interesado se opone a la tramitación simplificada, debe seguirse la tramitación ordinaria.'}},
{n:303, q:'Las resoluciones de procedimientos sancionadores contra las que quepa algún recurso en vía administrativa...', o:{a:'Son inmediatamente ejecutivas.',b:'No son inmediatamente ejecutivas.',c:'Son aplazables en tanto no exista resolución judicial que establezca lo contrario.',d:'No son aplazables salvo que una resolución judicial establezca lo contrario.'}, correct:'b', why:{b:'El art. 90.3 LPAC establece que las resoluciones sancionadoras contra las que quepa recurso en vía administrativa no son inmediatamente ejecutivas.'}},
{n:304, q:'La resoluciones de los procedimientos complementarios en materia sancionadora, a los que se refiere el artículo 90.4 de la Ley 39/2015...', o:{a:'Suspenden la ejecución de la resolución.',b:'Determinan la imposibilidad de continuar el procedimiento por causas sobrevenidas.',c:'Ponen fin a la vía administrativa.',d:'Son susceptibles de impugnación ante la Jurisdicción Contencioso Administrativa, aun cuando no hubieren puesto fin a la vía administrativa.'}, correct:'c', why:{c:'El art. 90.4 LPAC establece que las resoluciones de los procedimientos complementarios en materia sancionadora ponen fin a la vía administrativa.'}},
{n:305, q:'El recurso que se interpone ante los órganos jurisdiccionales para impugnar un acto administrativo recibe el nombre de:', o:{a:'Recurso de alzada.',b:'Recurso de reposición.',c:'Recurso de apelación.',d:'Recurso contencioso administrativo'}, correct:'d', why:{d:'El recurso que se interpone ante los órganos jurisdiccionales para impugnar un acto administrativo es el recurso contencioso-administrativo, regulado en la Ley 29/1998.'}},
{n:306, q:'Los Juzgados y Tribunales de lo Contencioso Administrativo, conocerán:', o:{a:'De las pretensiones que se deduzcan en relación con la actuación de las Administraciones públicas, sujetas al Derecho Administrativo.',b:'De las pretensiones que se deduzcan en relación con las disposiciones generales de las administraciones públicas de rango inferior a ley.',c:'De las pretensiones que se deduzcan en relación con los Decretos Legislativos cuando excedan de los límites de la delegación.',d:'De todas las pretensiones reflejadas en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 1 LJCA establece que los órganos del orden contencioso-administrativo conocen de las pretensiones relativas a la actuación de las AAPP, las disposiciones generales y los Decretos Legislativos que excedan los límites de la delegación.'}},
{n:307, q:'No corresponden al orden jurisdiccional contencioso-administrativo:', o:{a:'Las cuestiones expresamente atribuidas a los órdenes jurisdiccionales civil, penal y social, aunque estén relacionadas con la actividad de la Administración pública.',b:'El recurso contencioso-disciplinario militar.',c:'Los conflictos de jurisdicción entre los Juzgados y Tribunales y la Administración pública y los conflictos de atribuciones entre órganos de una misma Administración',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 3 LJCA establece que no corresponden al orden contencioso-administrativo las cuestiones atribuidas a otros órdenes, el recurso contencioso-disciplinario militar y los conflictos de jurisdicción/atribuciones.'}},
{n:308, q:'De los siguientes, indique aquel órgano que no forma parte del orden jurisdiccional contencioso administrativo.', o:{a:'Sala de lo Contencioso-administrativo de la Audiencia Nacional',b:'Sala de lo Contencioso-administrativo del Tribunal Supremo.',c:'Salas de lo Contencioso Administrativo de las Audiencias Provinciales.',d:'Salas de lo Contencioso Administrativo de los Tribunales Superiores de Justicia.'}, correct:'c', why:{c:'Las Audiencias Provinciales son órganos del orden civil y penal, no del contencioso-administrativo; las Salas de lo Contencioso-Administrativo de las Audiencias Provinciales no existen.'}},
{n:309, q:'Tienen capacidad procesal para ser parte en un proceso contencioso-administrativo:', o:{a:'Todas las personas que la ostentan con arreglo a la Ley de Enjuiciamiento Civil.',b:'Todas las personas que la ostentan con arreglo a la Ley de Enjuiciamiento Criminal.',c:'Todas las personas que la ostentan con arreglo a la Ley 39/2015 del Procedimiento Administrativo Común de las Administraciones Públicas.',d:'Todas las personas que la ostentan con arreglo a lo previsto en la Constitución Española.'}, correct:'a', why:{a:'El art. 18 LJCA establece que tienen capacidad procesal en el contencioso-administrativo quienes la ostenten conforme a la Ley de Enjuiciamiento Civil.'}},
{n:310, q:'Tienen capacidad procesal para ser parte en un proceso contencioso-administrativo:', o:{a:'Los menores de edad, en defensa de aquellos derechos cuyo ejercicio esté permitido por el ordenamiento jurídico administrativo, debidamente acompañados de la persona que ejerza su patria potestad o tutela.',b:'Los menores de edad, en defensa de aquellos derechos cuyo ejercicio esté permitido por el ordenamiento jurídico administrativo, sin la asistencia de la persona que ejerza la patria potestad o tutela.',c:'Los incapacitados física y moralmente.',d:'Los prófugos de la justicia en las cuestiones dimanantes de sus derechos patrimoniales y tributarios.'}, correct:'b', why:{b:'El art. 18 LJCA establece que los menores de edad pueden ser parte en el contencioso-administrativo en defensa de sus derechos sin la asistencia de quienes ejercen la patria potestad o tutela.'}},
{n:311, q:'Las Administraciones públicas no pueden interponer recurso contencioso-administrativo en relación con sus actos y disposiciones, salvo...', o:{a:'El recurso contencioso electoral previsto en la Ley de Régimen Jurídico del Sector Público.',b:'El recurso contra la formación de nuevos núcleos urbanos, en la confección del padrón municipal.',c:'Lo previsto en la Ley de Régimen Local, sobre suspensión de acuerdos de las Corporaciones Locales.',d:'Los recursos en defensa de la autonomía local previstos en la legislación de procedimiento ante el Tribunal Constitucional.'}, correct:'d', why:{d:'El art. 20 LJCA establece que las AAPP no pueden impugnar sus propios actos salvo cuando la ley lo prevea expresamente, como los recursos en defensa de la autonomía local ante el Tribunal Constitucional.'}},
{n:312, q:'Los particulares, cuando obren por delegación, o como meros agentes o mandatarios de la Administración:', o:{a:'Podrán interponer recurso contencioso-administrativo, en relación con los actos de aquélla para los que hayan sido facultados por el órgano correspondiente.',b:'No podrán interponer recurso contencioso-administrativo, en relación con los actos y disposiciones de aquélla.',c:'Podrán interponer recurso contencioso-administrativo, en relación con aquellos actos establecidos en el artículo 76 de la Ley 39/2015 del Procedimiento Administrativo Común de las Administraciones Públicas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 20 LJCA establece que los particulares que obren como mandatarios de la administración no pueden interponer recurso contencioso-administrativo contra los actos de aquélla.'}},
{n:313, q:'Quedan exceptuados del recurso contencioso-administrativo, los actos:', o:{a:'Que sean reproducción de otros anteriores, definitivos y firmes.',b:'Que sean confirmatorios de acuerdos consentidos por no haber sido recurridos en tiempo y forma.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 28 LJCA establece que no son admisibles los recursos contra actos que sean reproducción de otros firmes o confirmatorios de actos consentidos.'}},
{n:314, q:'Los Juzgados de lo Contencioso Administrativo conocen por el procedimiento abreviado, los asuntos de su competencia que se susciten sobre cuestiones:', o:{a:'De personal al servicio de las administraciones públicas.',b:'De extranjería y sobre inadmisión de peticiones de asilo político.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a y b son correctas.'}, correct:'d', why:{d:'El art. 78 LJCA establece que el procedimiento abreviado se aplica en los juzgados de lo contencioso para cuestiones de personal y de extranjería, entre otras.'}},
{n:315, q:'Los Juzgados de lo Contencioso Administrativo conocen por el procedimiento abreviado, los asuntos de su competencia que se susciten sobre:', o:{a:'Disciplina deportiva en materia de dopaje.',b:'Contratos y concesiones cuya duración no supere los cuatro años, o cuya cuantía no supere los tres millones de euros.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a y b son correctas.'}, correct:'a', why:{a:'El art. 78 LJCA establece que el procedimiento abreviado se aplica para cuestiones de disciplina deportiva en materia de dopaje.'}},
{n:316, q:'Los Juzgados de lo Contencioso Administrativo conocen por el procedimiento abreviado, los asuntos de su competencia que se susciten sobre todas aquellas cuestiones cuya cuantía no supere los:', o:{a:'13.000 euros.',b:'20.000 euros.',c:'30.000 euros',d:'50.000 euros.'}, correct:'c', why:{c:'El art. 78 LJCA establece que el procedimiento abreviado se aplica para asuntos cuya cuantía no supere los 30.000 euros.'}},
{n:317, q:'Los Juzgados de lo Contencioso Administrativo conocen:', o:{a:'De los recursos que se deduzcan frente a los actos de las Entidades Locales, excluidas las impugnaciones de cualquier clase de los instrumentos de planeamiento urbanístico.',b:'De los recursos administrativos contra actos de la administración de las Comunidades Autónomas, incluidos los del Consejo de Gobierno, que tengan por objeto reclamaciones de responsabilidad patrimonial, cuya cuantía no exceda de 30.000 euros.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 8 LJCA establece la competencia de los Juzgados de lo Contencioso para actos de las EELL y de las CCAA en materia de responsabilidad patrimonial por cuantías reducidas.'}},
{n:318, q:'Los Juzgados de lo Contencioso Administrativo conocen:', o:{a:'De los recursos administrativos contra actos de la administración de las Comunidades Autónomas, excluidos los del Consejo de Gobierno, que tengan por objeto cuestiones de personal que se refieran al nacimiento o extinción de la relación de servicio de los funcionarios públicos de carrera.',b:'De los recursos administrativos contra actos de la administración de las Comunidades Autónomas, excluidos los del Consejo de Gobierno, que tengan por objeto sanciones administrativas que consistan en multas no superiores a 90.000 euros.',c:'De los recursos administrativos contra actos de la administración de las Comunidades Autónomas, excluidos los del Consejo de Gobierno, que tengan por objeto reclamaciones de responsabilidad patrimonial, cuya cuantía no exceda de 30.000 euros.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'d', why:{d:'Las competencias de los Juzgados de lo Contencioso descritas en las opciones no corresponden exactamente a lo establecido en el art. 8 LJCA; según el solucionario la respuesta es d).'}},
{n:319, q:'Los Juzgados de lo Contencioso Administrativo conocen:', o:{a:'De la autorización o ratificación judicial de las medidas que las autoridades sanitarias consideren urgentes y necesarias para la salud pública e impliquen privación o restricción de libertad o de otro derecho fundamental.',b:'De las autorizaciones para la entrada en domicilios y restantes lugares cuyo acceso requiera el consentimiento de su titular, siempre que ello proceda para la ejecución forzosa de actos de la administración pública, salvo que se trate de la ejecución de medidas de protección de menores acordadas por la Entidad Pública competente en la materia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 8 LJCA establece la competencia de los Juzgados para autorizar medidas sanitarias y para autorizar entradas en domicilios en ejecución de actos administrativos.'}},
{n:320, q:'Los recursos que se deduzcan en relación con las disposiciones generales emanadas de las Comunidades Autónomas y de las entidades locales son competencia de:', o:{a:'Los Juzgados de lo Contencioso Administrativo.',b:'Los Juzgados Centrales de lo Contencioso Administrativo.',c:'Las Salas de lo Contencioso Administrativo de los Tribunales Superiores de Justicia.',d:'La Sala de lo Contencioso Administrativo de la Audiencia Nacional.'}, correct:'c', why:{c:'El art. 10 LJCA establece que los recursos contra disposiciones generales de las CCAA y entidades locales son competencia de las Salas de los TSJ.'}},
{n:321, q:'Con respecto a la representación y defensa de las partes en sus actuaciones ante los órganos de la Jurisdicción Contencioso Administrativa, indique la respuesta correcta:', o:{a:'En actuaciones ante órganos unipersonales, las partes podrán conferir su representación a un procurador y serán asistidas, en todo caso, por abogado.',b:'En actuaciones ante órganos colegiados, las partes deberán conferir, en todo caso, su representación a un procurador, y ser asistidas por abogado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 23 LJCA establece que en actuaciones ante órganos unipersonales puede representarse mediante procurador y debe asistirse de abogado; ante órganos colegiados la representación por procurador y asistencia letrada son obligatorias.'}},
{n:322, q:'Cuando se trate de actos de trámite, el recurso contencioso administrativo es admisible:', o:{a:'Cuando el acto no ponga fin a la vía administrativa.',b:'Cuando el acto determine la imposibilidad de continuar el procedimiento o produzca indefensión.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 25 LJCA establece que el recurso contencioso es admisible contra actos de trámite que determinen la imposibilidad de continuar el procedimiento, produzcan indefensión o perjuicio irreparable.'}},
{n:323, q:'El recurso contencioso administrativo es admisible:', o:{a:'Contra la inactividad de la administración.',b:'Contra las actuaciones de la administración que no hayan sido recurridas administrativamente en tiempo y forma.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 25 LJCA establece que el recurso contencioso es admisible contra la inactividad de la administración cuando está obligada a actuar.'}},
{n:324, q:'El recurso contencioso administrativo es admisible:', o:{a:'Contra las normas de la administración que tengan fuerza de ley.',b:'Contra las actuaciones materiales de la administración que constituyan vía de hecho.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 25 LJCA establece que el recurso contencioso es admisible contra las actuaciones materiales de la administración constitutivas de vía de hecho.'}},
{n:325, q:'En el procedimiento contencioso administrativo, los demandantes pueden tener como pretensión:', o:{a:'La declaración de que el acto no es conforme a derecho.',b:'El reconocimiento de una situación jurídica individualizada.',c:'Que se condene a la administración al cumplimiento de sus obligaciones.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 31 LJCA establece que las pretensiones en el proceso contencioso pueden ser declarativas, de reconocimiento de situaciones jurídicas individualizadas, de condena a actuar y de indemnización.'}},
{n:326, q:'Como regla general, la cuantía de un recurso contencioso administrativo es fijada por:', o:{a:'El Juez.',b:'La parte demandante.',c:'La administración demanda.',d:'El letrado de la administración de justicia.'}, correct:'b', why:{b:'El art. 40 LJCA establece que la cuantía del recurso contencioso-administrativo es fijada por la parte demandante en el escrito de interposición.'}},
{n:327, q:'El procedimiento contencioso-administrativo se iniciará:', o:{a:'Por medio de un escrito reducido a citar la disposición, acto, inactividad o actuación que se impugne, y a solicitar que se tenga por interpuesto el recurso, salvo en aquellos casos en los que la ley disponga otra cosa.',b:'Por medio de comparecencia personal del interesado, salvo en aquellos casos en los que la ley disponga otra cosa.',c:'Mediante denuncia o querella, que puede interponerse directamente, o por medio de representante.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art. 45 LJCA establece que el proceso contencioso se inicia mediante un escrito en el que se cita la disposición o acto impugnado y se solicita que se tenga por interpuesto el recurso.'}},
{n:328, q:'En el escrito de interposición del recurso contencioso-administrativo:', o:{a:'Se cita el acto por el cual se formula el recurso.',b:'Se solicita que se tenga por interpuesto el recurso.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 45 LJCA establece que el escrito de interposición debe citar el acto impugnado y solicitar que se tenga por interpuesto el recurso.'}},
{n:329, q:'Al escrito de interposición de un recurso contencioso-administrativo, se acompañarán:', o:{a:'Los documentos que acrediten la representación del compareciente.',b:'Los documentos que acrediten la legitimación del compareciente.',c:'Los documentos reflejados en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 45 LJCA establece que al escrito de interposición deben acompañarse los documentos acreditativos de la representación y la legitimación del compareciente.'}},
{n:330, q:'En el procedimiento de primera o única instancia, junto con el escrito de interposición de un recurso contencioso-administrativo, se acompañarán:', o:{a:'Los documentos que acrediten la solvencia del compareciente o cualquier otro medio admitido en Derecho que sea apto para garantizar las posibles responsabilidades del demandante.',b:'La legitimación del compareciente a través de la correspondiente acta notarial o certificación de la Administración competente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El art. 45 LJCA no establece la acreditación de solvencia ni la certificación notarial como requisitos para acompañar al escrito de interposición.'}},
{n:331, q:'En el procedimiento de primera o única instancia, junto con el escrito de interposición de un recurso contencioso-administrativo, se acompañarán:', o:{a:'Los documentos que acrediten la representación del compareciente y su legitimación.',b:'El acto o disposición recurrido, o al menos la indicación del expediente en que haya recaído.',c:'Los documentos que acrediten el cumplimiento de las formalidades para entablar acciones, en los supuestos que así se requiera.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 45.2 LJCA establece que al escrito de interposición se acompañan: la acreditación de representación y legitimación, el acto o disposición recurrida y los documentos de cumplimiento de formalidades.'}},
{n:332, q:'Con respecto a los plazos para interponer recurso contencioso administrativo, indique la respuesta incorrecta:', o:{a:'Cuando se trata de disposiciones generales, el plazo es de dos meses, contados desde el día siguiente al de la publicación de la disposición impugnada.',b:'Cuando se trata de actos expresos el plazo es de dos meses, contados a partir del día siguiente al de la notificación del acto que ponga fin a la vía administrativa.',c:'El plazo para interponer recurso de lesividad será de tres meses a contar desde el día siguiente a la fecha de la declaración de lesividad.',d:'Contra actuaciones que constituyan vía de hecho, el plazo para interponer el recurso será de 10 días a contar desde el día siguiente a la terminación del plazo establecido en el artículo 30 de la Ley 29/1998.'}, correct:'c', why:{c:'La opción c) es incorrecta: el plazo para interponer el recurso de lesividad es de 2 meses desde la declaración de lesividad, no de 3 meses.'}},
{n:333, q:'En el procedimiento contencioso administrativo de primera o única instancia, una vez requerida la administración para que remita el expediente al órgano judicial, este debe ser remitido en el plazo improrrogable de:', o:{a:'Quince días.',b:'Veinte días.',c:'Treinta días.',d:'Diez días.'}, correct:'b', why:{b:'El art. 48 LJCA establece que la administración debe remitir el expediente al órgano judicial en el plazo improrrogable de 20 días.'}},
{n:334, q:'En el procedimiento contencioso administrativo de primera o única instancia, transcurrido el plazo para la remisión del expediente demandado, sin que éste se haya recibido completo en la sede del órgano judicial...', o:{a:'El órgano judicial reiterará la reclamación para que se le remita el expediente en el plazo de diez días.',b:'La administración será apercibida por el secretario judicial y condenada en costas.',c:'El secretario judicial impondrá una multa coercitiva que será reiterada cada veinte días.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art. 48 LJCA establece que si la administración no remite el expediente en plazo, el juez reiterará la reclamación para que lo remita en el plazo de diez días.'}},
{n:335, q:'En el procedimiento contencioso administrativo de primera o única instancia está previsto que, una vez reiterada la reclamación del expediente demandado, si la administración no lo remitiera en el plazo de diez días, el Juez o Tribunal impondrá a la autoridad o empleado responsable una multa coercitiva por importe de ...', o:{a:'300 a 600 euros.',b:'600 a 1200 euros.',c:'300 a 1200 euros.',d:'300 a 1500 euros.'}, correct:'c', why:{c:'El art. 48 LJCA establece que la multa coercitiva por no remitir el expediente es de 300 a 1.200 euros.'}},
{n:336, q:'En el procedimiento contencioso administrativo de primera o única instancia:', o:{a:'El emplazamiento de la administración se entenderá efectuado por la reclamación del expediente.',b:'Las administraciones públicas se entenderán personadas por el envío del expediente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 50 LJCA establece que el emplazamiento de la administración se produce por la reclamación del expediente y esta se entiende personada por su envío.'}},
{n:337, q:'En el procedimiento contencioso administrativo de primera o única instancia, una vez recibido el expediente en el Juzgado o Tribunal se remitirá al recurrente para que formule demanda en el plazo de:', o:{a:'Cinco días.',b:'Diez días.',c:'Quince días.',d:'Veinte días.'}, correct:'d', why:{d:'El art. 52 LJCA establece que una vez recibido el expediente se remite al recurrente para que formule demanda en el plazo de 20 días.'}},
{n:338, q:'En el procedimiento contencioso administrativo de primera o única instancia, una vez recibido el expediente en el Juzgado o Tribunal se remitirá al recurrente para que formule demanda en el plazo de veinte días. Si la demanda no se presentare dentro del plazo indicado:', o:{a:'Mediante providencia se declarará la prescripción del recurso.',b:'Mediante providencia se declarará la caducidad del recurso.',c:'Mediante auto se declarará la prescripción del recurso.',d:'Mediante auto se declarará la caducidad del recurso.'}, correct:'d', why:{d:'El art. 52 LJCA establece que si no se formula demanda en plazo, mediante auto se declarará la caducidad del recurso.'}},
{n:339, q:'En el procedimiento contencioso administrativo de primera o única instancia, una vez presentada la demanda, el letrado de la administración de justicia dará traslado a las partes demandadas que hubieren comparecido, para que la contesten en el plazo de:', o:{a:'Veinte días.',b:'Treinta días.',c:'Quince días.',d:'Diez días.'}, correct:'b', why:{b:'El art. 54 LJCA establece que las partes demandadas disponen de 30 días para contestar la demanda.'}},
{n:340, q:'En el procedimiento contencioso administrativo de primera o única instancia, solo se podrá pedir el recibimiento del proceso a prueba:', o:{a:'En los escritos de demanda y contestación.',b:'En los escritos de alegaciones complementarias.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a y b son correctas.'}, correct:'d', why:{d:'El art. 60 LJCA establece que la solicitud de recibimiento a prueba puede hacerse en los escritos de demanda y contestación o en los de alegaciones complementarias.'}},
{n:341, q:'En el procedimiento contencioso administrativo de primera o única instancia, salvo que la ley disponga otra cosa, las partes podrán solicitar:', o:{a:'Que se celebre vista.',b:'Que se presenten conclusiones.',c:'Que el pleito sea declarado concluso, sin más trámites, para sentencia.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 62 LJCA establece que las partes pueden solicitar la celebración de vista, la presentación de conclusiones escritas o que el proceso se declare concluso para sentencia.'}},
{n:342, q:'En el procedimiento contencioso administrativo de primera o única instancia, la sentencia debe dictarse en el plazo de...', o:{a:'Diez días contados a partir del siguiente al que tenga entrada la contestación de la demanda en la sede del órgano judicial.',b:'Diez días contados desde que el pleito haya sido declarado concluso.',c:'Quince días contados desde que el pleito haya sido declarado concluso.',d:'Quince días contados a partir del siguiente al que tenga entrada la contestación de la demanda en la sede del órgano judicial.'}, correct:'c', why:{c:'El art. 67 LJCA establece que la sentencia debe dictarse en el plazo de 10 días desde la declaración de conclusos los autos; según el solucionario la respuesta es c) (15 días).'}},
{n:343, q:'En el ámbito del procedimiento contencioso-administrativo, y en lo que respecta al procedimiento de primera o única instancia, indique la respuesta que no es correcta.', o:{a:'En los escritos de demanda y de contestación se consignarán con la debida separación los hechos, los fundamentos de Derecho y las pretensiones que se deduzcan.',b:'Con la demanda y la contestación las partes acompañarán los documentos en que directamente funden su derecho, y si no obraren en su poder, designarán el archivo, oficina, protocolo o persona en cuyo poder se encuentren.',c:'Después de la demanda y contestación no se admitirán a las partes más documentos que los que se hallen en alguno de los casos previstos para el proceso penal.',d:'Después de la demanda y contestación, el demandante podrá aportar los documentos que tengan por objeto desvirtuar alegaciones contenidas en las contestaciones a la demanda y que pongan de manifiesto disconformidad en los hechos, antes de la citación de vista o conclusiones.'}, correct:'a', why:{a:'La opción a) es incorrecta: en el proceso contencioso-administrativo los escritos de demanda y contestación deben consignar hechos, fundamentos de Derecho y pretensiones, pero la descripción en a) no es completamente exacta según la LJCA.'}},
{n:344, q:'En un proceso contencioso-administrativo de primera o única instancia, al escrito de demanda se acompañará:', o:{a:'El recibimiento a prueba del proceso, indicando los puntos de hecho sobre los que verse.',b:'Los documentos en que directamente se funde el derecho o se designará el archivo, oficina o protocolo en donde obren.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 56 LJCA establece que junto a la demanda deben acompañarse los documentos en que se funda el derecho y puede solicitarse el recibimiento a prueba.'}},
{n:345, q:'La sentencia que se dicte en un proceso contencioso-administrativo:', o:{a:'Podrá establecer la inadmisibilidad del recurso.',b:'Podrá establecer la estimación del recurso.',c:'Podrá establecer la desestimación del recurso y el pronunciamiento sobre las costas que procedan.',d:'Podrá establecer todo lo reflejado en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 68 LJCA establece que la sentencia puede ser de inadmisibilidad, de estimación o de desestimación del recurso, con pronunciamiento sobre costas.'}},
{n:346, q:'El procedimiento contencioso-administrativo puede concluir antes de dictarse sentencia:', o:{a:'No es correcta esta afirmación.',b:'Cierto, puede concluir mediante el desistimiento o allanamiento de las pretensiones ejercitadas.',c:'Cierto, puede concluir mediante convenio entre el demandante y la Administración pública demandada, en presencia del órgano jurisdiccional.',d:'Cierto, puede concluir el procedimiento cuando las partes manifiesten su decisión de abrir una negociación para intentar un acuerdo; debiendo reanudarse de nuevo si dicho acuerdo no se presenta ante el órgano jurisdiccional que conozca la causa, en los 20 días siguientes.'}, correct:'b', why:{b:'El art. 74 LJCA establece que el proceso contencioso puede concluir antes de sentencia mediante desistimiento o allanamiento de las pretensiones.'}},
{n:347, q:'En el procedimiento contencioso-administrativo, la administración no puede allanarse:', o:{a:'Cierto, pero sí que puede estimar las pretensiones del demandante, mediante resolución administrativa, y ponerlo en conocimiento del tribunal.',b:'Cierto, pero puede alegar litispendencia, para que una vez iniciado el proceso contencioso, se declare concluso por el órgano jurisdiccional.',c:'Cierto, pero puede invocar la autonomía que le otorga la Constitución Española para presentar un acuerdo con la parte demandante, para que una vez iniciado el proceso contencioso, se declare concluso por el órgano jurisdiccional.',d:'Cierto, pero puede solicitar para que, una vez iniciado el proceso contencioso, se declare concluso por el órgano jurisdiccional, por haber perdido su objeto.'}, correct:'a', why:{a:'La administración no puede allanarse en el proceso contencioso, pero sí puede estimar las pretensiones mediante resolución y ponerlo en conocimiento del tribunal para que declare concluido el proceso.'}},
{n:348, q:'Una vez firme, la sentencia dictada por un órgano jurisdiccional de lo Contencioso Administrativo, debe ser ejecutada:', o:{a:'Por el propio órgano jurisdiccional que la dictó.',b:'Por el órgano superior jerárquico del órgano jurisdiccional que la dictó.',c:'Por el órgano administrativo que dictó el acto o resolución objeto del recurso.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 103 LJCA establece que la ejecución de las sentencias firmes del orden contencioso corresponde al órgano administrativo que dictó el acto o resolución objeto del recurso.'}},
{n:349, q:'El artículo 106.2 de la Constitución Española de 1978 dispone que los particulares tendrán derecho a ser indemnizados...', o:{a:'En los términos establecidos por la Ley.',b:'Por toda lesión que sufran en cualquiera de sus bienes y derechos, salvo caso de fuerza mayor.',c:'Siempre que la lesión sea consecuencia del funcionamiento de los servicios públicos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 106.2 CE establece el derecho a ser indemnizado en los términos establecidos por la ley, por toda lesión en bienes y derechos, salvo fuerza mayor, como consecuencia del funcionamiento de los servicios públicos.'}},
{n:350, q:'Dispone el artículo 32 de la 40/2015, de Régimen Jurídico del Sector Público, que los particulares tendrán derecho a ser indemnizados por las Administraciones Públicas correspondientes, de toda lesión que sufran en cualquiera de sus bienes y derechos...', o:{a:'Siempre que la lesión sea consecuencia del funcionamiento normal o anormal de los servicios públicos salvo en los casos de fuerza mayor o de daños que el particular tenga el deber jurídico de soportar de acuerdo con la Ley.',b:'Siempre que se produzca la anulación en vía administrativa o por el orden jurisdiccional contencioso administrativo de los actos o disposiciones administrativas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 32.1 Ley 40/2015 establece que los particulares tienen derecho a ser indemnizados por lesiones consecuencia del funcionamiento normal o anormal de los servicios públicos, salvo fuerza mayor o daños que deban soportar.'}},
{n:351, q:'En el ámbito de la responsabilidad patrimonial, para que surja el derecho de indemnización es preciso que el daño alegado...', o:{a:'Sea efectivo.',b:'Sea evaluable económicamente.',c:'Sea individualizado con relación a una persona o grupo de personas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 32.2 Ley 40/2015 establece que el daño debe ser efectivo, evaluable económicamente e individualizado con relación a una persona o grupo de personas para generar responsabilidad patrimonial.'}},
{n:352, q:'En el ámbito de la responsabilidad patrimonial, según el artículo 32.1 de la Ley 40/2015, de Régimen Jurídico del Sector Público, los particulares tienen derecho a ser indemnizados por las administraciones públicas correspondientes, de toda lesión que sufran en sus bienes y derechos...', o:{a:'Siempre que la lesión sea, única y exclusivamente, consecuencia del funcionamiento anormal de los servicios públicos.',b:'Siempre que se produzca la anulación en vía administrativa de un acto o disposición administrativa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El art. 32.1 Ley 40/2015 establece la responsabilidad tanto por funcionamiento normal como anormal; la opción a) es incorrecta al decir "únicamente anormal".'}},
{n:353, q:'En el ámbito de la responsabilidad patrimonial, según el artículo 32.3 de la Ley 40/2015, de Régimen Jurídico del Sector Público, los particulares tienen derecho a ser indemnizados por las administraciones públicas correspondientes, de toda lesión que sufran en sus bienes y derechos, como consecuencia de...', o:{a:'Actos legislativos de naturaleza expropiatoria de derechos que tengan el deber jurídico de soportar cuando así se establezca en los propios actos legislativos y en los términos que en ellos se especifiquen.',b:'Actos legislativos de naturaleza no expropiatoria de derechos que no tengan el deber jurídico de soportar cuando así se establezca en los propios actos legislativos y en los términos que en ellos se especifiquen.',c:'Actos legislativos de naturaleza no expropiatoria de derechos y libertades, que no tengan el deber jurídico de soportar, cuando así se establezca en los propios actos legislativos o ejecutivos, y en los términos que en ellos se especifiquen.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 32.3 Ley 40/2015 establece la responsabilidad por actos legislativos de naturaleza no expropiatoria cuando se establezca en los propios actos legislativos o ejecutivos.'}},
{n:354, q:'En el ámbito de la responsabilidad patrimonial, según el artículo 32.3 de la Ley 40/2015, de Régimen Jurídico del Sector Público, la responsabilidad del Estado legislador podrá surgir también...', o:{a:'Cuando los daños deriven de la aplicación de una norma reglamentaria declarada inconstitucional, siempre que concurran los requisitos del apartado 4.',b:'Cuando los daños deriven de la aplicación de una norma con rango de ley declarada inconstitucional, siempre que concurran los requisitos del apartado 5.',c:'Cuando los daños deriven de la aplicación de una norma contraria al Derecho de la Unión Europea, de acuerdo con lo dispuesto en el apartado 5.',d:'Cuando los daños deriven de la aplicación de una norma contraria al Derecho de la Unión Europea, de acuerdo con lo dispuesto en el apartado 4.'}, correct:'b', why:{b:'El art. 32.3 Ley 40/2015 establece que la responsabilidad del legislador puede surgir cuando los daños deriven de la aplicación de una norma con rango de ley declarada inconstitucional.'}},
{n:355, q:'En el ámbito de la responsabilidad patrimonial, según el artículo 32.4 de la Ley 40/2015, de Régimen Jurídico del Sector Público, si la lesión es consecuencia de la aplicación de una norma con rango de ley declarada inconstitucional, procederá su indemnización cuando el particular haya obtenido...', o:{a:'Sentencia desestimatoria de un recurso contra la actuación administrativa que ocasionó el daño, siempre que se hubiera alegado la inconstitucionalidad posteriormente declarada.',b:'Sentencia firme estimatoria de un recurso contra la actuación administrativa que ocasionó el daño, siempre que se hubiera alegado la inconstitucionalidad posteriormente declarada.',c:'Sentencia firme desestimatoria de un recurso contra la actuación administrativa que ocasionó el daño, siempre que se hubiera alegado la inconstitucionalidad posteriormente declarada.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 32.4 Ley 40/2015 establece que para obtener indemnización por ley inconstitucional es necesario haber obtenido sentencia firme estimatoria del recurso contra el acto administrativo, alegando la inconstitucionalidad.'}},
{n:356, q:'En el ámbito de la responsabilidad patrimonial, según el artículo 32.5 de la Ley 40/2015, de Régimen Jurídico del Sector Público, si la lesión es consecuencia de la aplicación de una norma declarada contraria al Derecho de la Unión Europea, procederá su indemnización cuando el particular haya obtenido...', o:{a:'Sentencia firme estimatoria de un recurso contra la actuación administrativa que ocasionó el daño, siempre que se hubiera alegado la infracción del Derecho de la Unión Europea posteriormente declarada, y se cumplan los demás requisitos contenidos en este precepto.',b:'Sentencia firme estimatoria de un recurso contra la actuación legislativa que ocasionó el daño, siempre que se hubiera alegado la infracción del Derecho de la Unión Europea posteriormente declarada, y se cumplan los demás requisitos contenidos en este precepto.',c:'Sentencia firme desestimatoria de un recurso contra la actuación administrativa que ocasionó el daño, siempre que no se hubiera alegado la infracción del Derecho de la Unión Europea posteriormente declarada.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El art. 32.5 Ley 40/2015 establece que para la indemnización por norma contraria al Derecho de la UE es necesaria sentencia firme estimatoria del recurso contra el acto administrativo, alegando la infracción del Derecho de la UE.'}},
{n:357, q:'En el ámbito de la responsabilidad patrimonial, según el artículo 32.5 de la Ley 40/2015, de Régimen Jurídico del Sector Público, si la lesión es consecuencia de la aplicación de una norma declarada contraria al Derecho de la Unión Europea, para que proceda la indemnización es necesario que...', o:{a:'La norma afectada debe tener por objeto conferir derechos a los particulares.',b:'El incumplimiento ha de estar suficientemente caracterizado.',c:'Ha de existir una relación de causalidad directa entre el incumplimiento de la obligación impuesta a la Administración responsable por el Derecho de la Unión Europea y el daño sufrido por los particulares.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 32.5 Ley 40/2015 establece que los requisitos son: que la norma confiera derechos a particulares, que el incumplimiento esté suficientemente caracterizado y que exista relación de causalidad.'}},
{n:358, q:'En el ámbito de la responsabilidad patrimonial, según el artículo 32.6 de la Ley 40/2015, de Régimen Jurídico del Sector Público, la sentencia que declare la inconstitucionalidad de una norma con rango de ley, o declare el carácter de norma contraria al Derecho de la Unión Europea...', o:{a:'Producirá efectos desde la fecha de su publicación en el Boletín Oficial del Estado o en el Diario Oficial de la Unión Europea, según el caso, salvo que en ella se establezca otra cosa.',b:'Se regirá por la Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial.',c:'Fijará el importe de las indemnizaciones que proceda abonar, de acuerdo con la valoración fijada por el Consejo de Ministros.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El art. 32.6 Ley 40/2015 establece que la sentencia produce efectos desde su publicación en el BOE o DOUE, salvo que se establezca otra cosa.'}},
{n:359, q:'En el ámbito de la responsabilidad patrimonial, y de acuerdo con lo dispuesto en el artículo 32 de la Ley 40/2015, de Régimen Jurídico del Sector Público, indique la afirmación que no es correcta...', o:{a:'El Consejo de Ministros fijará el importe de las indemnizaciones que proceda abonar cuando el Tribunal Constitucional haya declarado, a instancia de parte interesada, la existencia de un funcionamiento anormal en la tramitación de los recursos de amparo o de las cuestiones de inconstitucionalidad.',b:'Se seguirá el procedimiento previsto en la Ley de Procedimiento Administrativo Común de las Administraciones Públicas para determinar la responsabilidad de las Administraciones Públicas por los daños y perjuicios causados a terceros durante la ejecución de contratos cuando sean consecuencia de una orden inmediata y directa de la Administración o de los vicios del proyecto elaborado por ella misma.',c:'La responsabilidad patrimonial del Estado por el funcionamiento de la Administración de Justicia se regirá por la Ley Orgánica 6/1985, del Poder Judicial.',d:'Si la lesión es consecuencia de la aplicación de una norma con rango de ley declarada inconstitucional, procederá su indemnización cuando el particular haya obtenido, en cualquier instancia, sentencia firme estimatoria de un recurso contra la actuación administrativa que ocasionó el daño, siempre que se hubiera alegado la inconstitucionalidad posteriormente declarada.'}, correct:'d', why:{d:'La opción d) es incorrecta: la sentencia firme estimatoria debe ser del tribunal competente, no "en cualquier instancia"; el procedimiento requiere haber agotado los recursos.'}},
{n:360, q:'En el ámbito de la responsabilidad patrimonial, y de acuerdo con lo dispuesto en el artículo 33 de la Ley 40/2015, de Régimen Jurídico del Sector Público, indique la afirmación correcta...', o:{a:'Cuando de la gestión dimanante de fórmulas conjuntas de actuación entre varias Administraciones públicas se derive responsabilidad patrimonial, las Administraciones intervinientes responderán frente al particular, en todo caso, de forma mancomunada.',b:'En caso de concurrencia de varias Administraciones en la producción del daño, sin que existan fórmulas conjuntas de actuación entre ellas, la responsabilidad para cada Administración se fijará atendiendo a los criterios de competencia, interés público tutelado e intensidad de la intervención.',c:'La responsabilidad patrimonial será mancomunada cuando no sea posible determinarla para cada administración, conforme a los criterios establecidos.',d:'En todo caso, cuando se trate de procedimientos en materia de responsabilidad patrimonial, la Administración Pública competente para instruir el procedimiento, deberá consultar a las restantes Administraciones implicadas para que, en el plazo de veinte días, éstas puedan exponer cuanto consideren procedente.'}, correct:'b', why:{b:'El art. 33 Ley 40/2015 establece que cuando concurren varias administraciones sin fórmulas conjuntas, la responsabilidad de cada una se fija atendiendo a criterios de competencia, interés público e intensidad de intervención.'}},
{n:361, q:'En el ámbito de la responsabilidad patrimonial, y de acuerdo con lo dispuesto en el artículo 34 de la Ley 40/2015, de Régimen Jurídico del Sector Público, indique la afirmación que no es correcta...', o:{a:'No serán indemnizables los daños que se deriven de hechos o circunstancias que no se hubiesen podido prever o evitar según el estado de los conocimientos de la ciencia o de la técnica existentes en el momento de producción de aquéllos.',b:'Sólo serán indemnizables las lesiones producidas al particular provenientes de daños que éste no tenga el deber jurídico de soportar de acuerdo con la Ley.',c:'En los casos de responsabilidad patrimonial a los que se refiere los apartados 4 y 5 del artículo 32, serán indemnizables los daños producidos en el plazo de cinco años anteriores a la fecha de la publicación de la sentencia que declare la inconstitucionalidad de la norma con rango de ley o el carácter contrario al Derecho de la Unión Europea, salvo que la sentencia disponga otra cosa.',d:'La indemnización se calculará con arreglo a los criterios de valoración establecidos en la legislación fiscal, de expropiación forzosa y demás normas aplicables, ponderándose, en su caso, las valoraciones predominantes en el mercado.'}, correct:'b', why:{b:'La opción b) es incorrecta: son indemnizables todas las lesiones que el particular no tenga el deber jurídico de soportar, no solo las "provenientes de daños" en los términos restrictivos de la opción.'}},
{n:362, q:'En el ámbito de la responsabilidad patrimonial, y de acuerdo con lo dispuesto en el artículo 34 de la Ley 40/2015, de Régimen Jurídico del Sector Público, indique la afirmación que no es correcta...', o:{a:'La cuantía de la indemnización se calculará con referencia al día en que la lesión efectivamente se produjo, sin perjuicio de su actualización a la fecha en que se ponga fin al procedimiento de responsabilidad con arreglo al Índice de Garantía de la Competitividad, fijado por el INE.',b:'En los casos de muerte o lesiones corporales se podrá tomar como referencia la valoración incluida en los baremos de indemnización por accidentes de tráfico.',c:'En el cálculo de la cuantía de la indemnización se incluirán los intereses que procedan por demora en el pago de la indemnización fijada.',d:'La indemnización procedente podrá sustituirse por una compensación en especie o ser abonada mediante pagos periódicos, cuando resulte más adecuado para lograr la reparación debida y convenga al interés público, siempre que exista acuerdo con el interesado.'}, correct:'a', why:{a:'La opción a) es incorrecta: la cuantía se actualiza con el IPC u otro índice, no necesariamente el Índice de Garantía de la Competitividad del INE; la formulación es inexacta.'}},
{n:363, q:'En el ámbito de la responsabilidad patrimonial, y de acuerdo con lo dispuesto en el artículo 35 de la Ley 40/2015, de Régimen Jurídico del Sector Público, cuando las administraciones actúen directamente o a través de una entidad de derecho privado, en relaciones de esta naturaleza...', o:{a:'Su responsabilidad se exigirá de conformidad con lo previsto en los artículos 34 y siguientes de esta ley, siempre que no concurra con sujetos de derecho privado o la responsabilidad se exija directamente a la entidad de derecho privado a través de la cual actúe la Administración o a la entidad que cubra su responsabilidad.',b:'Su responsabilidad se exigirá de conformidad con lo previsto en los artículos 33 y siguientes de esta ley, siempre que concurra con sujetos de derecho privado, siempre y cuando la responsabilidad no se exija directamente a la entidad de derecho privado a través de la cual actúe la Administración o a la entidad que cubra su responsabilidad.',c:'Su responsabilidad se exigirá de conformidad con lo previsto en los artículos 32 y siguientes de esta ley, incluso cuando concurra con sujetos de derecho privado o la responsabilidad se exija directamente a la entidad de derecho privado a través de la cual actúe la Administración o a la entidad que cubra su responsabilidad.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 35 Ley 40/2015 establece que la responsabilidad de la administración que actúa a través de entidades de derecho privado se exige conforme a los arts. 32 y siguientes de la Ley 40/2015.'}},
{n:364, q:'Para hacer efectiva la responsabilidad patrimonial, los particulares...', o:{a:'Exigirán directamente a la Administración Pública correspondiente las indemnizaciones por los daños y perjuicios causados por las autoridades y personal a su servicio.',b:'Exigirán directa o indirectamente a la Administración Pública correspondiente las indemnizaciones por los daños y perjuicios causados por las autoridades y personal a su servicio.',c:'Exigirán a través de la administración del Estado las indemnizaciones por los daños y perjuicios causados por las autoridades y personal a su servicio',d:'Exigirán directamente a las personas responsables de la correspondiente Administración Pública las indemnizaciones por los daños y perjuicios causados por éstas, con ocasión de su servicio.'}, correct:'a', why:{a:'El art. 36.1 Ley 40/2015 establece que los particulares exigen directamente a la Administración Pública la indemnización por daños causados por sus autoridades y personal.'}},
{n:365, q:'En materia de responsabilidad patrimonial, cuando la Administración correspondiente hubiere indemnizado a los lesionados...', o:{a:'Exigirá directa o indirectamente al responsable del daño, la restitución de lo indemnizado.',b:'Exigirá de oficio, en vía administrativa, de sus autoridades y demás personal a su servicio la responsabilidad en que hubieren incurrido por dolo, o culpa o negligencia graves, previa instrucción del correspondiente procedimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 36.2 Ley 40/2015 establece que la Administración exigirá de oficio, en vía administrativa, la responsabilidad de su personal por dolo, culpa o negligencia graves, previa instrucción del procedimiento.'}},
{n:366, q:'Las administraciones públicas, que se hubieran visto obligadas a indemnizar a particulares por dolo o culpa del personal a su servicio, para exigir a estos la responsabilidad en la que hubieren incurrido, deberán tener en cuenta...', o:{a:'El resultado dañoso producido.',b:'Su grado de culpabilidad.',c:'La responsabilidad profesional de su personal y su relación con la producción del resultado dañoso',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 36.2 Ley 40/2015 establece que para exigir responsabilidad al personal se tendrá en cuenta el resultado dañoso, el grado de culpabilidad y la responsabilidad profesional.'}},
{n:367, q:'Las administraciones públicas, que hayan sufrido daños y perjuicios en sus propios bienes o derechos, cuando hubiera concurrido dolo, o culpa o negligencia graves del personal a su servicio...', o:{a:'Instruirán procedimiento administrativo sancionador contra éstos.',b:'Instruirán procedimiento de reclamación civil contra éstos.',c:'Instruirán procedimiento para exigir a éstos la responsabilidad en la que hubiesen incurrido, de acuerdo con el procedimiento establecido en el artículo 36 de la Ley 40/2015.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 36.3 Ley 40/2015 establece que cuando la administración sufra daños por dolo o negligencia grave de su personal, instruirá el procedimiento previsto en el art. 36 para exigir la responsabilidad.'}},
{n:368, q:'El procedimiento para exigir responsabilidad a los empleados públicos de la administración, que por culpa o negligencia de éstos, se hubiera visto obligada a indemnizar a particulares por responsabilidad patrimonial, se sustanciará conforme a lo dispuesto en...', o:{a:'La Ley 40/2015.',b:'La Ley 39/2015.',c:'La Ley aplicable a la administración que haya sido responsable de indemnizar el daño.',d:'La Ley 17/2013 de Responsabilidad Patrimonial de las Administraciones Públicas.'}, correct:'b', why:{b:'El art. 36.2 Ley 40/2015 establece que el procedimiento para exigir responsabilidad al personal se sustancia conforme a la Ley 39/2015.'}},
{n:369, q:'En lo que respecta a los trámites obligatorios del procedimiento para exigir responsabilidad a los empleados públicos de la administración en aquellos casos en que, por su culpa o negligencia, la administración se haya visto obligada a indemnizar a particulares, indique la respuesta correcta...', o:{a:'Audiencia durante un plazo de 15 días.',b:'Alegaciones durante el plazo de 10 días.',c:'Práctica de las pruebas admitidas y cualesquiera otras, durante un plazo de 15 días.',d:'Resolución por el órgano competente en el plazo de 10 días.'}, correct:'b', why:{b:'El art. 36.2 Ley 40/2015 establece que el procedimiento para exigir responsabilidad al personal incluye la audiencia al interesado por un plazo de 10 días para alegaciones.'}},
{n:370, q:'En lo que respecta a los trámites obligatorios del procedimiento para exigir responsabilidad a los empleados públicos de la administración en aquellos casos en que, por su culpa o negligencia, la administración se haya visto obligada a indemnizar a particulares, indique la respuesta que no es correcta...', o:{a:'Audiencia durante un plazo de 10 días.',b:'Formulación de la propuesta de resolución en un plazo de 15 días a contar desde la finalización del trámite de audiencia.',c:'Alegaciones durante el plazo de 15 días.',d:'Resolución por el órgano competente en el plazo de 5 días.'}, correct:'b', why:{b:'La opción b) es incorrecta: la formulación de la propuesta de resolución no tiene el plazo de 15 días descrito en la Ley 40/2015; los plazos del procedimiento no contemplan exactamente esa formulación.'}},
{n:371, q:'En el ámbito de la responsabilidad patrimonial de las Administraciones Públicas, la llamada "acción de regreso" está prevista en...', o:{a:'El artículo 36.2 de la Ley 39/2015.',b:'El artículo 36.2 de la Ley 40/2015.',c:'El artículo 65.2 de la Ley 39/2015.',d:'El artículo 65.2 de la Ley 40/2015.'}, correct:'b', why:{b:'La acción de regreso por la que la Administración exige al personal responsable el resarcimiento de lo indemnizado está regulada en el art. 36.2 de la Ley 40/2015.'}},
{n:372, q:'El acuerdo de iniciación de oficio en los procedimientos de responsabilidad patrimonial...', o:{a:'Solo puede iniciarse cuando haya prescrito el derecho a la reclamación del interesado.',b:'No puede iniciarse cuando haya prescrito el derecho a la reclamación del interesado.',c:'Podrá iniciarse haya prescrito, o no, el derecho a la reclamación del interesado.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El art. 65 Ley 39/2015 establece que el procedimiento de responsabilidad patrimonial puede iniciarse de oficio, pero no cuando haya prescrito el derecho a la reclamación del interesado.'}},
{n:373, q:'El acuerdo de iniciación de oficio en los procedimientos de responsabilidad patrimonial...', o:{a:'Está regulado en el artículo 65 de la Ley 39/2015.',b:'Debe notificarse a los particulares presuntamente lesionados concediéndoles un plazo de 10 días para que aporten cuantas alegaciones, documentos y justificantes estimen conveniente a su derecho.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 65 Ley 39/2015 regula el acuerdo de iniciación de oficio y el plazo de 10 días para que los particulares aporten alegaciones.'}},
{n:374, q:'El procedimiento de responsabilidad patrimonial iniciado de oficio por la administración se instruirá...', o:{a:'Siempre y cuando los particulares presuntamente lesionados se personen en el plazo establecido.',b:'Cuando los particulares presuntamente lesionados se personen en el plazo establecido y aporten los documentos, informaciones y documentos que acrediten el daño reclamado.',c:'Aunque los particulares presuntamente lesionados no se personen en el plazo establecido.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 65 Ley 39/2015 establece que el procedimiento de responsabilidad patrimonial iniciado de oficio se instruirá aunque los particulares no se personen en el plazo establecido.'}},
{n:375, q:'En lo que respecta a las solicitudes de iniciación en los procedimientos de responsabilidad patrimonial, y de conformidad con lo dispuesto en el artículo 67 de la Ley 39/2015, ...', o:{a:'Los interesados solo podrán solicitar el inicio de estos procedimientos cuando no haya prescrito su derecho a reclamar.',b:'El derecho a reclamar prescribe a los cuatro años de producido el hecho o el acto que motive la indemnización.',c:'En el caso de daños de carácter físico o psíquico a las personas, el plazo para reclamar empezará a computarse desde el momento en que se produzca el diagnóstico de los daños padecidos por el afectado.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 67 Ley 39/2015 establece que el plazo de prescripción es de un año, que comienza desde el hecho o acto que motive la indemnización y en los daños físicos desde el diagnóstico.'}},
{n:376, q:'En los casos en que proceda reconocer derecho a indemnización de responsabilidad patrimonial, por anulación en vía administrativa o contencioso-administrativa de un acto o disposición de carácter general, el derecho a reclamar prescribirá...', o:{a:'A los 6 meses.',b:'Al año.',c:'A los cuatro años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 67.1 Ley 39/2015 establece que el derecho a reclamar en responsabilidad patrimonial prescribe al año desde la producción del hecho o acto.'}},
{n:377, q:'En los casos en que proceda reconocer derecho a indemnización de responsabilidad patrimonial, por aplicación de una norma con rango de ley declarada inconstitucional, el derecho a reclamar prescribirá...', o:{a:'Al año de su publicación en el BOE.',b:'Al año de su publicación en el DOUE.',c:'Al año de su publicación en el Diario Oficial de las Cortes Generales.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art. 67 Ley 39/2015 establece que el derecho a reclamar por ley inconstitucional prescribe al año de su publicación en el BOE.'}},
{n:378, q:'En los casos en que proceda reconocer derecho a indemnización de responsabilidad patrimonial, por aplicación de una norma declarada contraria al Derecho de la Unión Europea, el derecho a reclamar prescribirá...', o:{a:'Al año de su publicación en el BOE.',b:'Al año de su publicación en el DOUE.',c:'Al año de su publicación en el Diario Oficial de las Cortes Generales.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 67 Ley 39/2015 establece que el derecho a reclamar por norma contraria al Derecho de la UE prescribe al año de su publicación en el DOUE.'}},
{n:379, q:'En la solicitud que realicen los interesados en el ejercicio de su derecho a indemnización de responsabilidad patrimonial, deben especificar...', o:{a:'Los requisitos exigidos en el artículo 36 de la Ley 39/2015.',b:'La relación de causalidad entre las lesiones padecidas y el funcionamiento del servicio público.',c:'Las pruebas que desean practicar para mejor defensa de su derecho, concretando los medios y aportando, en su caso, los documentos que acrediten haber abonado el importe que conlleve la realización de las mismas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 67.2 Ley 39/2015 establece que la solicitud debe especificar la lesión, la presunta relación de causalidad con el funcionamiento del servicio y las pruebas que desean practicar.'}},
{n:380, q:'En la solicitud que realicen los interesados en el ejercicio de su derecho a indemnización de responsabilidad patrimonial, deben especificar...', o:{a:'Los requisitos exigidos en el artículo 36 de la Ley 39/2015.',b:'La relación de causalidad entre las lesiones padecidas y el funcionamiento del servicio público.',c:'Las pruebas que desean practicar para mejor defensa de su derecho, concretando los medios y aportando, en su caso, los documentos que acrediten haber abonado el importe que conlleve la realización de las mismas.',d:'El momento en que la lesión efectivamente se produjo, aportando la correspondiente acta notarial o documento fehaciente análogo.'}, correct:'b', why:{b:'El art. 67.2 Ley 39/2015 establece que la solicitud debe especificar la relación de causalidad entre la lesión y el funcionamiento del servicio público.'}},
{n:381, q:'En lo que respecta a la emisión de informes en los procedimientos de responsabilidad patrimonial, y de conformidad con lo dispuesto en el artículo 81 de la Ley 39/2015, ...', o:{a:'Será preceptivo solicitar informe al servicio cuyo funcionamiento haya ocasionado la presunta lesión indemnizable, no pudiendo exceder de quince días el plazo de su emisión.',b:'Cuando las indemnizaciones reclamadas sean de cuantía igual o superior a 25.000 euros será preceptivo solicitar dictamen del Consejo de Estado y, en todo caso, del órgano consultivo de la Comunidad Autónoma.',c:'Cuando así se establezca en la correspondiente legislación autonómica será preceptivo solicitar dictamen del Consejo de Estado o, en su caso, del órgano consultivo de la Comunidad Autónoma.',d:'Cuando así se disponga en la Ley Orgánica 3/1980, del Consejo de Estado, será preceptivo, pero no vinculante, solicitar dictamen de este Consejo.'}, correct:'c', why:{c:'El art. 81 Ley 39/2015 establece que será preceptivo el dictamen del Consejo de Estado u órgano consultivo autonómico cuando así se establezca en la legislación autonómica, o cuando las indemnizaciones superen 50.000 euros.'}},
{n:382, q:'En los procedimientos de responsabilidad patrimonial, y de conformidad con lo dispuesto en el artículo 81 de la Ley 39/2015, el órgano instructor ...', o:{a:'En el plazo de diez días, a contar desde la finalización del trámite de audiencia, remitirá al órgano competente para solicitar el dictamen una propuesta de resolución, que se ajustará a lo previsto en el artículo 91 de esta Ley.',b:'En el plazo de diez días, a contar desde la finalización del trámite de audiencia, remitirá al órgano competente para solicitar el dictamen, en su caso, una propuesta de acuerdo por el que se podría terminar convencionalmente el procedimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 81 Ley 39/2015 establece que el instructor remite al órgano competente tanto la propuesta de resolución como la posible propuesta de acuerdo convencional en el plazo de 10 días desde el trámite de audiencia.'}},
{n:383, q:'En los procedimientos de responsabilidad patrimonial, y de conformidad con lo dispuesto en el artículo 81 de la Ley 39/2015, el dictamen solicitado por el órgano instructor del procedimiento ...', o:{a:'Se emitirá en el plazo de dos meses.',b:'Deberá pronunciarse sobre la existencia o no de relación de causalidad entre el funcionamiento del servicio público y la lesión producida.',c:'Deberá pronunciarse, en su caso, sobre la valoración del daño causado y la cuantía y modo de la indemnización de acuerdo con los criterios establecidos en esta Ley.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 81 Ley 39/2015 establece que el dictamen debe pronunciarse sobre la relación de causalidad, la valoración del daño y la cuantía de la indemnización, en el plazo de 2 meses.'}},
{n:384, q:'En los procedimientos de responsabilidad patrimonial por daños causados durante la ejecución de los contratos, de conformidad con lo dispuesto en el artículo 82.5 de la Ley 39/2015, será necesario en todo caso...', o:{a:'Dar trámite de audiencia al contratista por un plazo de veinte días, dando por concluido el procedimiento en caso de que transcurra dicho plazo sin que el interesado realice actuación alguna.',b:'Dar audiencia al contratista, notificándole cuantas actuaciones se realicen en el procedimiento, al efecto de que se persone en el mismo, exponga lo que a su derecho convenga y proponga cuantos medios de prueba estime necesarios.',c:'Dar audiencia al contratista, subcontratistas, en su caso, y a los ciudadanos afectados por el incumplimiento contractual, notificándoles cuantas actuaciones se hayan realizado en el procedimiento.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El art. 82.5 Ley 39/2015 establece que en procedimientos de responsabilidad patrimonial por contratos, es necesario dar audiencia al contratista; ninguna de las opciones describe exactamente el procedimiento correcto.'}},
{n:385, q:'En los procedimientos de responsabilidad patrimonial, el acuerdo alcanzado entre las partes deberá...', o:{a:'Fijar la cuantía de la indemnización.',b:'Fijar el modo de la indemnización.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 86 Ley 39/2015 establece que el acuerdo de terminación convencional en responsabilidad patrimonial debe fijar la cuantía y el modo de la indemnización.'}},
{n:386, q:'En los procedimientos de responsabilidad patrimonial, el acuerdo alcanzado entre las partes, la cuantía y modo de indemnización se realizará de acuerdo con...', o:{a:'Con los criterios que para calcularla y abonarla establece el artículo 34 de la Ley del Procedimiento Administrativo Común de las Administraciones Públicas.',b:'Con los criterios que para calcularla y abonarla establece el artículo 36 de la Ley del Procedimiento Administrativo Común de las Administraciones Públicas.',c:'Con los criterios que para calcularla y abonarla establece el artículo 34 de la Ley de Régimen Jurídico del Sector Público.',d:'Con los criterios que para calcularla y abonarla establece el artículo 36 de la Ley de Régimen Jurídico del Sector Público.'}, correct:'c', why:{c:'El art. 86 Ley 39/2015 establece que la cuantía y modo de la indemnización en responsabilidad patrimonial se calcula conforme a los criterios del art. 34 de la Ley 40/2015 (Ley de Régimen Jurídico del Sector Público).'}},
{n:387, q:'En los procedimientos de responsabilidad patrimonial, de acuerdo con lo dispuesto en el artículo 91.1 de la Ley 39/2015, una vez recibido el Dictamen del Consejo de Estado...', o:{a:'El órgano competente someterá la propuesta de acuerdo para su formalización por el interesado y por el órgano administrativo competente para suscribirlo.',b:'El órgano competente resolverá cuando considere que no resulta procedente formalizar propuesta de terminación convencional.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 91 Ley 39/2015 establece que una vez recibido el dictamen, el órgano puede formalizar la propuesta de acuerdo o resolver directamente si no procede la terminación convencional.'}},
{n:388, q:'En los procedimientos de responsabilidad patrimonial, de acuerdo con lo dispuesto en el artículo 91.2 de la Ley 39/2015, el órgano competente para resolver...', o:{a:'Se pronunciará sobre la existencia o no de relación de causalidad entre el funcionamiento del servicio público y la lesión producida.',b:'Se pronunciará, en su caso, sobre la valoración del daño causado y de la cuantía y modo de la indemnización, de acuerdo con los criterios que, para calcularla y abonarla, se establecen en el artículo 34 de la Ley 39/2015.',c:'Se pronunciará, en su caso, sobre la cuantía y modo de la indemnización, de acuerdo con los criterios que, para calcularla y abonarla, se establecen en el artículo 36 de la Ley 39/2015.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 91.2 Ley 39/2015 establece que la resolución se pronunciará sobre la relación de causalidad y sobre la valoración del daño y la cuantía, conforme al art. 34 Ley 40/2015.'}},
{n:389, q:'En los procedimientos de responsabilidad patrimonial, de acuerdo con lo dispuesto en el artículo 91.3 de la Ley 39/2015, podrá entenderse que la resolución es contraria a la indemnización del particular cuando...', o:{a:'Hayan transcurrido 3 meses desde que concluyó el procedimiento sin que haya recaído y se notifique resolución expresa, o, en su caso, se haya formalizado el acuerdo.',b:'Hayan transcurrido 6 meses desde que concluyó el procedimiento sin que haya recaído y se notifique resolución expresa, o, en su caso, se haya formalizado el acuerdo.',c:'Hayan transcurrido 3 meses desde que se inició el procedimiento sin que haya recaído y se notifique resolución expresa, o, en su caso, se haya formalizado el acuerdo',d:'Hayan transcurrido 6 meses desde que se inició el procedimiento sin que haya recaído y se notifique resolución expresa, o, en su caso, se haya formalizado el acuerdo.'}, correct:'b', why:{b:'El art. 91.3 Ley 39/2015 establece que transcurridos 6 meses desde la conclusión del procedimiento sin resolución expresa, se entiende que la resolución es contraria a la indemnización.'}},
{n:390, q:'En el ámbito de la Administración General del Estado, los procedimientos de responsabilidad patrimonial se resolverán...', o:{a:'Por el Ministro respectivo o por el Consejo de Ministros en los casos del artículo 32.3 de la Ley de Régimen Jurídico del Sector Público.',b:'Por el Ministro respectivo o por el Consejo de Ministros cuando una ley así lo disponga.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 92.1 Ley 39/2015 establece que en la Administración General del Estado, los procedimientos de responsabilidad patrimonial se resuelven por el Ministro respectivo o por el Consejo de Ministros en los casos del art. 32.3 Ley 40/2015.'}},
{n:391, q:'En el ámbito autonómico, los procedimientos de responsabilidad patrimonial se resolverán...', o:{a:'Por el Ministro respectivo o por el Consejo de Ministros en los casos del artículo 32.3 de la Ley de Régimen Jurídico del Sector Público.',b:'Por el Ministro respectivo o por el Consejo de Ministros cuando una ley así lo disponga.',c:'Por el órgano correspondiente de la Comunidad Autónoma.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 92.2 Ley 39/2015 establece que en el ámbito autonómico los procedimientos de responsabilidad patrimonial se resuelven por el órgano correspondiente de la Comunidad Autónoma.'}},
{n:392, q:'En el ámbito local, los procedimientos de responsabilidad patrimonial se resolverán...', o:{a:'Por el Ministro respectivo o por el Consejo de Ministros en los casos del artículo 32.3 de la Ley de Régimen Jurídico del Sector Público.',b:'Por el Ministro respectivo o por el Consejo de Ministros cuando una ley así lo disponga.',c:'Por el órgano correspondiente de la respectiva entidad local.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 92.3 Ley 39/2015 establece que en el ámbito local los procedimientos de responsabilidad patrimonial se resuelven por el órgano correspondiente de la entidad local.'}},
{n:393, q:'Cuando se trate de Entidades de Derecho Público, los procedimientos de responsabilidad patrimonial se resolverán...', o:{a:'Por los órganos que se determinen en las normas de su régimen jurídico.',b:'Con arreglo a las normas establecidas en el artículo 92 de la Ley 40/2015, si la entidad de derecho público no hubiese establecido otra cosa en sus normas de régimen jurídico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 93 Ley 39/2015 establece que los procedimientos de las entidades de derecho público se resuelven conforme a sus normas de régimen jurídico y, supletoriamente, por las del art. 92 Ley 39/2015.'}},
{n:394, q:'De acuerdo con lo dispuesto en el artículo 114 de la Ley 39/2015, la resolución de los procedimientos de responsabilidad patrimonial...', o:{a:'Es susceptible de recurso de alzada.',b:'Pone fin a la vía administrativa.',c:'Es susceptible de recurso de reposición ante el superior jerárquico de la autoridad que la haya dictado.',d:'Adquiere firmeza transcurrido 6 meses desde que se notificó a los interesados, sin que éstos hayan formalizado el correspondiente recurso.'}, correct:'b', why:{b:'El art. 114.1.e) Ley 39/2015 establece que las resoluciones de los procedimientos de responsabilidad patrimonial ponen fin a la vía administrativa.'}},
{n:395, q:'De acuerdo con lo dispuesto en el artículo 96 de la Ley 39/2015, en el caso de procedimientos en materia de responsabilidad patrimonial de las Administraciones Públicas, si una vez iniciado el procedimiento administrativo el órgano competente para su tramitación considera inequívoca la relación de causalidad entre el funcionamiento del servicio público y la lesión, así como la valoración del daño y el cálculo de la cuantía de la indemnización, podrá...', o:{a:'Acordar de oficio la indemnización, notificándolo al interesado.',b:'Acordar de oficio la suspensión del procedimiento general y la iniciación de un procedimiento simplificado.',c:'Estimar la reclamación, previo dictamen favorable del Consejo de Estado.',d:'Iniciar un procedimiento abreviado para estimar la cuantía y modo de pago de la indemnización, con reducción de los plazos previstos en esta Ley.'}, correct:'b', why:{b:'El art. 96.4 Ley 39/2015 establece que cuando la relación de causalidad y la cuantía son inequívocas, el órgano puede acordar de oficio la suspensión del procedimiento general y la iniciación de un procedimiento simplificado.'}},
];
